window.LUMINA_E = {"fetched":"2026-11-08","by_topic":{"dermatologie":[{"nct":"NCT07699679","title":"Photobiomodulation in Coronary Artery Bypass Grafting With No-Touch vs Conventional Saphenous Vein Harvesting.","acronym":"PHOTON","status":"NOT_YET_RECRUITING","phases":["NA"],"n":292,"start":"2027-01","end":"2027-08","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Coronary Artery Disease","Coronary Artery Bypass Graft (CABG)","Surgical Wound Healing"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation Therapy"},{"type":"DEVICE","name":"Sham Laser irradiation"},{"type":"PROCEDURE","name":"Conventional Saphenous Vein Harvesting"},{"type":"PROCEDURE","name":"No-Touch Saphenous Vein Harvesting"}],"sponsor":"Federal University of São Paulo","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Solange Guizilini","title":"Principal Investigator","affiliation":"Federal University of São Paulo"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"Hospital São Paulo, Federal University of São Paulo","city":"São Paulo","country":"Brazil"}],"n_sites":1,"outcome":"Incidence of surgical wound complications at the saphenous vein harvesting site","summary":"This randomized, double-blind clinical trial aims to evaluate the impact of photobiomodulation therapy on postoperative outcomes in patients undergoing coronary artery bypass grafting (CABG). The study will compare two techniques for saphenous vein graft harvesting: the conventional technique and the no-touch technique. Participants will be randomly allocated into four groups: conventional harvesting with sham laser, conventional harvesting with photobiomodulation, no-touch harvesting with sham laser, and no-touch harvesting with photobiomodulation. The primary objective is to evaluate the effects of photobiomodulation on wound healing and postoperative complications related to the saphenous vein harvesting site. Secondary outcomes include clinical outcomes and functional capacity after surgery. The results may contribute to improving postoperative recovery and optimizing surgical strate","updated":"2026-10-07","first_posted":"2026-07-13","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM et cicatrisation du site de prélèvement saphène après pontage coronarien"},{"nct":"NCT07739147","title":"Comparing Standard Platelet-Rich Plasma and Light-Enhanced Platelet-Rich Plasma for Treating Hair Loss in Androgenetic Alopecia: A Randomized Controlled Trial","acronym":null,"status":"NOT_YET_RECRUITING","phases":["EARLY_PHASE1"],"n":30,"start":"2026-12-30","end":"2027-12-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Androgenetic Alopecia"],"interventions":[{"type":"DRUG","name":"Platelet-Rich Plasma (PRP) Injections"},{"type":"DEVICE","name":"Red-light photobiomodulation with cooling"},{"type":"DEVICE","name":"Blue-light photobiomodulation"}],"sponsor":"Kimberly Meathrel","sponsor_class":"INDUSTRY","collaborators":[],"responsible":{"name":"Kimberly Meathrel","title":"Surgeon and Principal Investigator","affiliation":"BespokeSkin MD"},"officials":[{"name":"Kimberly Meathrel","role":"STUDY_DIRECTOR","affiliation":"Bespoke Skin MD"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Hair rate Terminal/Vellus (%)","summary":"The goal of this clinical trial is to compare 3 different types of PRP in androgenetic alopecia patients. The main questions it aims to answer:\n\nDoes Redlight enhanced, Blue light enhanced, or traditional PRP result in higher hair density and health? Does Redlight enhanced, Blue light enhanced, or traditional PRP result in other improved hair metrics.\n\nParticipants will consent to a PRP treatment but will be blinded to the type. They will then be asked to return for Tricholab analysis at set post-operative timepoints to record changes in hair metrics (Baseline, 1 month, 3 months, 6 months, 9 months, 12 months).","updated":"2026-07-31","first_posted":"2026-07-31","type":"INTERVENTIONAL","ctx":"alopécie","titre":"PRP seul ou enrichi par PBM rouge ou bleue dans l'alopécie androgénétique"},{"nct":"NCT07890233","title":"Efficacy of an LED Mask","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":110,"start":"2026-11-30","end":"2027-03-30","allocation":"NA","masking":"NONE","conditions":["Fine Lines and Wrinkles","Skin Health","Skin Tone"],"interventions":[{"type":"DEVICE","name":"Light emitting diode treatment"}],"sponsor":"Therabody, Inc.","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"ALS Global Clinical Studies","city":"Purchase","country":"United States"}],"n_sites":1,"outcome":"Expert Clinical Grading","summary":"The goal of this interventional study is to evaluate the efficacy and perception a commercial LED device in 110 healthy adult females and males between the ages of 35-65 years old, inclusively. The main questions it aims to answer are:\n\nDoes daily use of this commercial LED device improve overall skin appearance as measured by clinical tools (expert clinical grading, cutometer, digital photography, and VISIA-CR? Does daily use of this commercial LED device improve subjective skin appearance? Is daily use of this commercial LED device well tolerated?\n\nParticipants will complete a 9-minute LED treatment (4.5 minutes LED, 4.5 minutes LED+ infrared light therapy) with a commercially available device every day for 12 weeks. They will visit the clinic three times (baseline, 6 weeks, 12 weeks) for clinical grading of skin.","updated":"2026-10-22","first_posted":"2026-10-22","type":"INTERVENTIONAL","ctx":"esthétique","titre":"Efficacité d'un masque LED sur la peau du visage"},{"nct":"NCT07594678","title":"Minoxidil With or Without Low-Level Red-Light Therapy for Improving Chemotherapy-Induced Alopecia in Breast Cancer Patients","acronym":null,"status":"NOT_YET_RECRUITING","phases":["PHASE2"],"n":50,"start":"2026-11-15","end":"2027-12-31","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Anatomic Stage I Breast Cancer AJCC v8","Anatomic Stage II Breast Cancer AJCC v8","Anatomic Stage III Breast Cancer AJCC v8","Anatomic Stage IV Breast Cancer AJCC v8","Chemotherapy-Induced Alopecia"],"interventions":[{"type":"OTHER","name":"Electronic Health Record Review"},{"type":"DRUG","name":"Minoxidil"},{"type":"DEVICE","name":"Revian RED LED-light cap"},{"type":"OTHER","name":"Survey Administration"}],"sponsor":"Ohio State University Comprehensive Cancer Center","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Brittany Dulmage","title":"Principal Investigator","affiliation":"Ohio State University Comprehensive Cancer Center"},"officials":[{"name":"Brittany L Dulmage, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Ohio State University Comprehensive Cancer Center"}],"countries":["United States"],"sites":[{"facility":"Ohio State University Comprehensive Cancer Center","city":"Columbus","country":"United States"}],"n_sites":1,"outcome":"Dean scale score","summary":"This phase II trial compares the safety and effectiveness of topical minoxidil alone to topical minoxidil in combination with low-level red-light therapy for improving chemotherapy-induced hair loss or thinning (alopecia). Minoxidil has been approved by the Food and Drug Administration as a treatment for hair loss. It increases blood flow in the skin and may have a direct stimulatory effect on hair follicle cells, forcing them from their resting phase into their active growth phase. Low-level light therapy is regarded as a safe and medically accepted treatment for a variety of skin conditions, including acne, scars, and psoriasis. Red light wavelengths are readily absorbed into the skin and do not contain harmful ultraviolet light. When absorbed into the skin, these wavelengths stimulate fibroblasts, which are connective tissue cells that make and secrete collagen proteins. Low-level red","updated":"2026-09-02","first_posted":"2026-05-19","type":"INTERVENTIONAL","ctx":"alopécie","titre":"Minoxidil avec ou sans casque LED rouge dans l'alopécie chimio-induite du cancer du sein"},{"nct":"NCT07557524","title":"Pulsed High Intensity Laser Versus Negative Pressure Therapy On Neuropathic Ulcers","acronym":"VAC","status":"NOT_YET_RECRUITING","phases":["NA"],"n":70,"start":"2026-11-12","end":"2027-02-28","allocation":"RANDOMIZED","masking":"NONE","conditions":["Neuropathic Ulcers"],"interventions":[{"type":"DEVICE","name":"Laser therapy"},{"type":"DEVICE","name":"Negative pressure therapy is applied to the negative pressure group"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yomna El-Rafaie","title":"Physiotherapy practitioner","affiliation":"Cairo University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"ELshiek Zayed spicilized hospital","city":"Giza","country":"Egypt"}],"n_sites":1,"outcome":"wound surface area","summary":"the study comparess between laser therapy and vac to decide which on is superior","updated":"2026-11-05","first_posted":"2026-04-29","type":"INTERVENTIONAL","ctx":"plaies","titre":"Laser haute intensité pulsé ou thérapie par pression négative dans les ulcères neuropathiques"},{"nct":"NCT07899866","title":"Determinants of Radiation Dermatitis in Head and Neck Cancer Patients Receiving Preventive Photobiomodulation","acronym":"COH-PBM-3J","status":"NOT_YET_RECRUITING","phases":[],"n":150,"start":"2026-11-02","end":"2028-11","allocation":null,"masking":null,"conditions":["Head and Neck Neoplasms","Radiodermatitis"],"interventions":[{"type":"DEVICE","name":"Preventive photobiomodulation"},{"type":"RADIATION","name":"External beam radiotherapy"},{"type":"OTHER","name":"Functional, quality-of-life and photographic assessments"}],"sponsor":"Hopital Forcilles","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Romain PLOUZE","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Hôpital Forcilles - Fondation Cognacq-Jay"}],"countries":["France"],"sites":[{"facility":"Hôpital Forcilles - Fondation Cognacq-Jay","city":"Férolles-Attilly","country":"France"}],"n_sites":1,"outcome":"Number of Participants With Grade 2 or Higher Radiation Dermatitis Assessed by NCI-CTCAE v5.0","summary":"The goal of this observational study is to identify factors associated with the occurrence of grade 2 or higher radiation dermatitis in adults with head and neck cancer treated with radiotherapy who receive preventive photobiomodulation (PBM) as part of their standard care.\n\nThe main question it aims to answer is: which clinical, demographic, tumor-related, treatment-related and functional factors are associated with grade 2 or higher radiation dermatitis (NCI-CTCAE v5.0) despite preventive PBM?\n\nParticipants will receive their usual radiotherapy and their usual preventive PBM sessions (3 sessions per week throughout radiotherapy). In addition, for the purpose of the study, they will:\n\n* perform a 1-minute sit-to-stand test and a handgrip strength measurement at inclusion and at the end of radiotherapy;\n* complete the EORTC QLQ-H\\&N35 quality-of-life questionnaire before radiotherapy, at","updated":"2026-10-28","first_posted":"2026-10-28","type":"OBSERVATIONAL","ctx":"radiodermite","titre":"Facteurs de radiodermite chez les patients ORL sous PBM préventive"},{"nct":"NCT07922681","title":"Recurrent Aphthous Stomatitis Management in Children Using Diode Laser 980 Nanometer Versus Hyaluronic Acid Gel (RCT)","acronym":"RCT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":30,"start":"2026-11-01","end":"2027-01-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Apthous Ulcer"],"interventions":[{"type":"DEVICE","name":"laser therapy"},{"type":"DRUG","name":"Hyaluronic acid group"},{"type":"BEHAVIORAL","name":"Negative control group"}],"sponsor":"National Research Centre, Egypt","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mohamed Farouk Rashed","title":"Researcher of Pediatric Dentistry","affiliation":"National Research Centre, Egypt"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Severity of preoperative pain related to the ulcer","summary":"Thirty children with recurrent apthous ulcer will be divided into 3 groups of different treatment modalities to assess their effect on pain, ulcer size, healing and postoperative pain","updated":"2026-11-06","first_posted":"2026-11-06","type":"INTERVENTIONAL","ctx":"inflammatoire","titre":"Laser diode 980 nm ou acide hyaluronique dans les aphtes récidivants de l'enfant"},{"nct":"NCT07866716","title":"Effectiveness of Laser Therapy for Pain Relief From Chronic Wounds in Adults in Guaviare","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":32,"start":"2026-10","end":"2027-07","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Pain Alleviation"],"interventions":[{"type":"OTHER","name":"low-level laser therapy added to usual care."}],"sponsor":"Universidad Nacional de Colombia","sponsor_class":"OTHER","collaborators":["Ministry of Science, Technology and Innovation","Call for Proposals 15 by the Department of Guaviare."],"responsible":{"name":"Sandra Guerrero Gamboa","title":"PhD","affiliation":"Universidad Nacional de Colombia"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Change From Pre-Procedure to Post-Procedure in Pain Intensity Score on the Brief Pain Inventory Short Form (BPI-SF) Numeric Rating Scale","summary":"Traditionally, the clinical management of chronic wounds has concentrated primarily on tissue closure, leaving persistent pain under-addressed. Discomfort during routine dressing changes is often worsened by tissue trauma. Even with standard pain medications and gentle dressing procedures, patients in Guaviare, Colombia, continue to suffer from unmet pain management needs. To bridge this gap, Low-Level Laser Therapy (photobiomodulation) offers a nurse-driven, non-pharmacological complementary option designed to target pain directly and enhance overall quality of life.\n\nThis research aims to evaluate the effectiveness of low-level laser therapy added to standard care, compared to standard care alone, for the relief of pain experienced by patients with chronic wounds during nursing consultations at a wound care clinic in a healthcare institution in San José del Guaviare, Colombia.\n\nThe stu","updated":"2026-10-08","first_posted":"2026-10-08","type":"INTERVENTIONAL","ctx":"plaies","titre":"Laser basse énergie contre la douleur des plaies chroniques (Guaviare, Colombie)"},{"nct":"NCT07123285","title":"Effect of Photobiomodulation on Healing of Venous Leg Ulcers","acronym":null,"status":"RECRUITING","phases":["NA"],"n":102,"start":"2026-08-03","end":"2027-11-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Venous Leg Ulcer (VLU)","Venous Hypertension Ulcers","Chronic Venous Insufficiency","Chronic Venous Disease"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation Therapy"},{"type":"DEVICE","name":"Sham Photobiomodulation"},{"type":"PROCEDURE","name":"Compression Therapy"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Anna Carolina Ratto Tempestini Horliana","title":"Professor","affiliation":"University of Nove de Julho"},"officials":[{"name":"Anna C Ratto Tempestini Horliana, PhD","role":"STUDY_DIRECTOR","affiliation":"University of Nove de Julho"}],"countries":["Brazil"],"sites":[{"facility":"Estratégia Saúde da Família Vereador Carlos Alberto Baptistela - Maria Cristina","city":"Lençóis Paulista","country":"Brazil"}],"n_sites":1,"outcome":"Percentage Reduction in Wound Volume","summary":"Venous leg ulcers are a significant public health problem because of their prolonged duration, high recurrence rates, and economic, social, and quality-of-life effects. Compression therapy is the standard treatment; however, healing may remain slow. Photobiomodulation is being investigated as an adjunctive treatment to promote tissue repair and wound healing.\n\nThis prospective, randomized, controlled, double-blind clinical trial will evaluate the efficacy of photobiomodulation combined with compression therapy in the healing of lower-limb venous leg ulcers. A total of 102 participants will be randomly allocated in a 1:1 ratio to an Experimental Group (n=51), receiving active photobiomodulation plus compression therapy, or a Control Group (n=51), receiving sham photobiomodulation plus compression therapy. Treatment will be administered twice weekly on Mondays and Thursdays for 16 weeks, t","updated":"2026-09-09","first_posted":"2025-08-14","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM et cicatrisation de l'ulcère veineux de jambe, contre sham"},{"nct":"NCT07798960","title":"Effects of Transcutaneous Photobiomodulation on Diabetic Foot Ulcers.","acronym":null,"status":"RECRUITING","phases":["PHASE2"],"n":20,"start":"2026-05-12","end":"2026-12","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Diabetes Mellitus","Foot Ulcer"],"interventions":[{"type":"RADIATION","name":"PBM - Photobiomodulation"},{"type":"RADIATION","name":"Placebo PBM"},{"type":"OTHER","name":"Standard Treatment"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Rebeca Boltes Cecatto","title":"Professor M.D. Ph.D.","affiliation":"University of Nove de Julho"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"Universidade Estadual do Piaui","city":"Teresina","country":"Brazil"}],"n_sites":1,"outcome":"Size of wound area","summary":"Foot ulcers in people with diabetes mellitus represent one of the most serious chronic complications of the disease, being associated with persistent inflammation, high oxidative stress, microvascular dysfunction and systemic hemorheological changes that compromise the progression of the healing process. Given the pathophysiological complexity of these injuries, therapeutic strategies capable of acting simultaneously on the local wound microenvironment and the systemic biological environment become relevant for optimizing tissue repair. This study aims to evaluate the effects of the association between transcutaneous vascular photobiomodulation (FBMVT) and topical photobiomodulation (FBMT) in people with diabetes and foot ulcers. This is a randomized, controlled and prospective phase II clinical trial, with a sample of 20 participants allocated to experimental groups that will receive a ","updated":"2026-09-04","first_posted":"2026-09-02","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM transcutanée dans l'ulcère du pied diabétique"},{"nct":"NCT07307885","title":"The Effect of Photobiomodulation on Pressure Ulcers","acronym":"Pressure Ulcer","status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":46,"start":"2026-05-01","end":"2027-03-20","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Pressure Ulcer (PU)"],"interventions":[{"type":"DEVICE","name":"photobiomodulation"}],"sponsor":"Ankara Medipol University","sponsor_class":"OTHER","collaborators":["Fenerbahce University","Dr. Lutfi Kirdar Kartal Training and Research Hospital"],"responsible":{"name":"Hülya Elmalı Şimşek","title":"Asst Prof","affiliation":"Ankara Medipol University"},"officials":[],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Lütfi Kırdar Şehir Hastanesi","city":"Istanbul","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"The healing of pressure sores in the patients in the experimental group will be faster and more effective than in the control group.","summary":"Photobiomodulation Group (Intervention Group):\n\nBefore the intervention, the patient's skin sensitivity to light will be tested by applying light for 3 minutes to one-fourth of the forearm skin. If redness occurs and persists for more than 2 hours, this indicates photosensitivity, and the intervention will not be performed.\n\nThe Patient Information Form will be completed during the first meeting with the patients included in the study. Subsequently, blood values will be determined, the Patient Assessment Form will be filled out, vital signs will be measured, and then the intervention will begin. After routine wound care/cleaning procedures in the intensive care unit, without applying any medication, cream, or lotion to the wound area, red light (660 nm wavelength) will be applied to the wound area for 5 minutes at a distance of 55 cm during the first 3 days, and for 10 minutes at the sam","updated":"2026-09-21","first_posted":"2025-12-29","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM dans les escarres"},{"nct":"NCT07810504","title":"Dual Modality Treatment of Androgenic Alopecia With KeraFactor® Solution and Revian® LED Light Therapy","acronym":"KDKR26","status":"RECRUITING","phases":["NA"],"n":40,"start":"2026-03-17","end":"2026-12-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Androgenic Alopecia","Female Pattern Hair Loss","Hair Loss"],"interventions":[{"type":"OTHER","name":"Scalp Stimulating Serum"},{"type":"DEVICE","name":"Red Light Hair Growth Cap"},{"type":"OTHER","name":"Placebo scalp-stimulating serum"}],"sponsor":"K. Kay Durairaj, MD, FACS, A Medical Corporation","sponsor_class":"OTHER","collaborators":["KeraFactor by SkinQRI","REVIAN, Inc."],"responsible":{"name":"Kalpna Kay Durairaj, MD, FACS","title":"Principal Investigator","affiliation":"K. Kay Durairaj, MD, FACS, A Medical Corporation"},"officials":[],"countries":["United States"],"sites":[{"facility":"K. Kay Durairaj, M.D., A Medical Corp.","city":"Pasadena","country":"United States"}],"n_sites":1,"outcome":"Hair Density","summary":"This single-center, prospective, randomized, placebo-controlled interventional study will evaluate the safety and efficacy of KeraFactor scalp-stimulating solution and the Revian Red wireless smart cap, alone and in combination, for the treatment of female androgenic alopecia. Forty female subjects aged 35 to 55 with clinically diagnosed androgenic alopecia will be randomized into four treatment arms and followed for 24 weeks. The primary objective is to determine whether combination therapy produces greater improvement in hair growth from baseline to 6 months compared with solution alone, device alone, or placebo. Secondary outcomes include changes in hair density, hair fiber diameter, interfollicular distance, terminal-to-vellus hair ratio, patient satisfaction, and safety/tolerability.","updated":"2026-09-09","first_posted":"2026-09-09","type":"INTERVENTIONAL","ctx":"alopécie","titre":"Sérum KeraFactor et casque LED Revian dans l'alopécie androgénétique"},{"nct":"NCT07588243","title":"A Clinical Study to Evaluate the Efficacy and Safety of Ultra in Promoting Hair Regrowth","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":44,"start":"2026-02-19","end":"2026-12","allocation":"NA","masking":"NONE","conditions":["Androgenic Alopecia"],"interventions":[{"type":"DEVICE","name":"Low Level Laser Therapy"}],"sponsor":"CynosureLutronic","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"Dy Dermatology","city":"Glenview","country":"United States"},{"facility":"Cynosure Lutronic","city":"Westford","country":"United States"}],"n_sites":2,"outcome":"Difference in the Change in Hair Density from Baseline vs 90-day Follow-up","summary":"The goal of this clinical study is to evaluate the efficacy and safety of the Ultra device for the treatment of hair regrowth by assessing the improvement of hair density and hair shaft diameter.","updated":"2026-09-02","first_posted":"2026-05-14","type":"INTERVENTIONAL","ctx":"alopécie","titre":"Laser basse énergie (dispositif Ultra) et repousse des cheveux"},{"nct":"NCT07311889","title":"Patient Satisfaction and Recovery Outcomes Associated With Perioperative ELIXIR MD Use","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":[],"n":300,"start":"2026-01-19","end":"2027-06-01","allocation":null,"masking":null,"conditions":["Postoperative Pain","Postoperative Edema","Postoperative Ecchymosis","Surgical Wound Healing","Postsurgical Recovery"],"interventions":[{"type":"OTHER","name":"Perioperative photobiomodulation light therapy"}],"sponsor":"Elixir MD Inc","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"ELIXIR MD Inc","city":"Irvine","country":"United States"}],"n_sites":1,"outcome":"Patient-reported satisfaction with postoperative recovery","summary":"The goal of this observational registry study is to characterize postoperative recovery outcomes in adult patients receiving standard-of-care perioperative light therapy using an FDA-cleared photobiomodulation device as part of routine clinical practice. The study aims to describe changes in patient-reported and clinician-assessed recovery measures following elective surgical procedures.\n\nThe main questions this registry aims to answer are:\n\n1. How do patient-reported recovery outcomes, including pain, satisfaction, and perceived improvement, change over the postoperative period?\n2. How do clinician-assessed indicators of recovery, such as swelling and bruising, change over time following surgery?\n\nThis study does not include a randomized comparison group. Outcomes will be described longitudinally within participants based on data collected during routine care.\n\nParticipants will:\n\n1. Re","updated":"2026-08-24","first_posted":"2025-12-31","type":"OBSERVATIONAL","ctx":"plaies","titre":"Registre de la PBM périopératoire (ELIXIR MD) : douleur, œdème, ecchymoses, cicatrisation"},{"nct":"NCT07043868","title":"Effects and Feasibility of Photobiomodulation at 830nm Nanometers in the Treatment of Diabetic Ulcers","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":136,"start":"2026-01-10","end":"2027-01-10","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Diabete Type 2","Diabetic Foot Ulcer","Photobiomodulation","Low Level Laser Therapy"],"interventions":[{"type":"DEVICE","name":"Low Level Laser Therapy"}],"sponsor":"Federal University of Piaui","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Vinicius Saura Cardoso","title":"Principal Investigator","affiliation":"Federal University of Piaui"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Ulcer area reduction rate","summary":"Diabetic foot ulcers (DFU) are among the late complications of DFU, defined as skin lesions that involve the dermis to deeper structures, such as muscles and bones. Although preclinical studies have demonstrated the effects of GaAs 830 nm in diabetic wounds, no clinical studies have been performed, revealing the need for more in-depth analyses to identify the effects and ideal parameterization of PBM with GaAs 830 nm wavelength in the treatment of diabetic ulcers, improving quality of life, as well as to understand the therapeutic feasibility, time required for healing and recurrence rates of these lesions. Experimental, randomized, controlled, double-blind study, with blinding applied to the evaluator and participants. A total of 136 volunteers will be recruited for the research, carried out at the Integrated Center of Medical Specialties (CIEM) - Polyclinic. LLLT GaAs 830nm will be use","updated":"2025-07-10","first_posted":"2025-06-29","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM 830 nm dans les ulcères diabétiques : faisabilité et efficacité"},{"nct":"NCT07453927","title":"Blue Light for Donor Site Healing in Burn Patients","acronym":"CGU01_BL","status":"RECRUITING","phases":["NA"],"n":25,"start":"2025-09-29","end":"2026-07-31","allocation":"NON_RANDOMIZED","masking":"NONE","conditions":["Donor Site Complication","Burn","Photobiomodulation Therapy","Blue Light"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation with blue light"}],"sponsor":"AUSL Romagna Rimini","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Italy"],"sites":[{"facility":"U.O. Centro Grandi Ustionati - Osp. Maurizio Bufalini","city":"Cesena","country":"Italy"}],"n_sites":1,"outcome":"Donor Site Healing Time","summary":"The goal of this clinical trial is to learn whether blue light (BL) photobiomodulation can improve the healing of donor site (DS) wounds in patients with burn injuries who are treated surgically. This study will investigate whether adding BL therapy to the usual treatment can improve healing and patient outcomes in adult patients with intermediate and deep burns.\n\nThe main questions it aims to answer are:\n\n* Does the use of BL therapy combined with standard treatment reduce the healing time of DS compared with standard treatment alone?\n* Does BL therapy improve wound conditions, reduce pain, and decrease signs of infection during the healing process?\n* Is BL therapy safe and well tolerated when applied to DS?\n* Does the treatment improve the long-term quality of the scar after healing?\n\nResearchers will compare DS areas treated with standard care alone to DS areas treated with standard c","updated":"2026-04-06","first_posted":"2026-03-06","type":"INTERVENTIONAL","ctx":"cicatrices","titre":"Lumière bleue et cicatrisation des sites donneurs chez le brûlé"},{"nct":"NCT07155356","title":"Effect of Red and Blue Light Irradiation on Postoperative Wound Healing in Perianal Absces","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":222,"start":"2025-09-15","end":"2026-08-14","allocation":"RANDOMIZED","masking":"NONE","conditions":["Perianal Abscess"],"interventions":[{"type":"DEVICE","name":"Red light exposure"},{"type":"DEVICE","name":"Red-blue light exposure"}],"sponsor":"The Affiliated Hospital of Putian University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["China"],"sites":[{"facility":"Affiliated Hospital of Putian University","city":"Putian","country":"China"}],"n_sites":1,"outcome":"Wound healing time","summary":"This study aims to investigate whether specialized red-blue light irradiation facilitates faster postoperative recovery and reduces complication rates in patients following perianal abscess surgery. A total of 222 eligible patients were randomly allocated equally into three groups (74 per group):①Routine Care Group: Standard wound care including cleansing and dressing changes；②Red Light Therapy Group: Routine care plus red light phototherapy；③Combined Red-Blue Light Therapy Group: Routine care plus concurrent red and blue light phototherapy.Wound healing time and incidence of complications were compared to assess postoperative recovery across interventions. The primary hypothesis posits that adjunctive phototherapy-particularly combined red-blue light irradiation-will significantly enhance wound healing, reduce edema and pain, and decrease complication rates (e.g.bleeding, urinary retent","updated":"2025-09-04","first_posted":"2025-09-04","type":"INTERVENTIONAL","ctx":"plaies","titre":"Lumière rouge ou rouge-bleue après chirurgie d'abcès périanal"},{"nct":"NCT07121686","title":"Effect of Red and Blue Light Irradiation on Wound Healing After Hemorrhoid Surgery","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":315,"start":"2025-08-15","end":"2026-07-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Hemorrhoids"],"interventions":[{"type":"DEVICE","name":"Red light exposure"},{"type":"DEVICE","name":"Red-blue light exposure"}],"sponsor":"The Affiliated Hospital of Putian University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["China"],"sites":[{"facility":"Affiliated Hospital of Putian University","city":"Putian","country":"China"}],"n_sites":1,"outcome":"Wound healing time","summary":"The subjects of this study were patients who took mixed haemorrhoidectomy during the period of December 2024 - December 2025 . The haemorrhoidectomy patients were randomly divided into routine group, red light group and red and blue light group, and were given different ways of trauma care, and the number of cases in each group was 105 , with a total of 305 cases. Observe the difference between red and blue light irradiation and routine care on the healing time of postoperative trauma and postoperative complications after haemorrhoidectomy, and evaluate the patients' quality of life and satisfaction with treatment under both red light irradiation and routine care.","updated":"2025-08-13","first_posted":"2025-08-13","type":"INTERVENTIONAL","ctx":"plaies","titre":"Lumière rouge ou rouge-bleue après chirurgie hémorroïdaire"},{"nct":"NCT06990165","title":"Photobiomodulation in Radiodermatitis in People With Breast Cancer","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":148,"start":"2025-05","end":"2026-07","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Breast Cancer","Radio Dermatitis"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"OTHER","name":"Sham Control"}],"sponsor":"Instituto Nacional de Cancer, Brazil","sponsor_class":"OTHER_GOV","collaborators":["Conselho Nacional de Desenvolvimento Científico e Tecnológico"],"responsible":{"name":"Anke Bergmann","title":"Principal Investigator","affiliation":"Instituto Nacional de Cancer, Brazil"},"officials":[{"name":"Anke Bergmann, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"National Cancer Institute (INCA-BRAZIL)"}],"countries":["Brazil"],"sites":[{"facility":"National Cancer Institute (INCA-BRAZIL)","city":"Rio de Janeiro","country":"Brazil"},{"facility":"National Cancer Institute / Cancer Hospital III - Brazil","city":"Rio de Janeiro","country":"Brazil"}],"n_sites":2,"outcome":"Incidence and severity of radiodermatitis as assessed by the Radiation Therapy Oncology Group / European Organisation for Research and Treatment of Cancer (RTOG/EORTC) Classification System over 5 months after the start of adjuvant radiotherapy.","summary":"Most breast cancer patients undergoing radiotherapy develop radiodermatitis, making it one of the most prevalent adverse events during cancer treatment. The severity of radiodermatitis can pose a life-threatening risk to patients, lead to functional limitations, delay treatment (pauses for tissue recovery), reduce the radiation dose, and negatively impact health-related quality of life. There is no consensus on the ideal strategy for preventing radiodermatitis.\n\nPhotobiomodulation is a non-invasive strategythat may stimulate skin regeneration and minimize radiodermatitis without interfering with cancer treatment, with minimal risk (it may cause rare allergic-type complications or discomfort due to material contact) and low cost for both the patient and the healthcare system, making this approach highly relevant.\n\nReducing the use of pharmaceuticals, the duration of radiotherapy treatment","updated":"2025-05-25","first_posted":"2025-05-25","type":"INTERVENTIONAL","ctx":"radiodermite","titre":"PBM contre sham dans la radiodermite du cancer du sein"},{"nct":"NCT07048626","title":"Impact of Low-Level Laser Therapy on Hair Regrowth Post PRP Treatment","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":22,"start":"2025-03-17","end":"2025-09-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Baldness"],"interventions":[{"type":"COMBINATION_PRODUCT","name":"PRP treatment"},{"type":"COMBINATION_PRODUCT","name":"low level laser therapy post prp treatment"}],"sponsor":"Superior University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Muhammad Naveed Babur","title":"Principal Investigator","affiliation":"Superior University"},"officials":[],"countries":["Pakistan"],"sites":[{"facility":"Reshape Clinic","city":"Lahore","country":"Pakistan"}],"n_sites":1,"outcome":"Physician's Global Assessment (PGA) scale","summary":"Low-level laser stimulates cells in the hair follicles, which promotes hair growth. The patient's own blood platelets are used in platelet-rich plasma treatment to encourage hair growth. Combining low-level laser treatment with platelet-rich plasma will promote hair growth in patients.","updated":"2025-07-02","first_posted":"2025-07-02","type":"INTERVENTIONAL","ctx":"alopécie","titre":"Laser basse énergie après PRP dans la repousse des cheveux"},{"nct":"NCT06819033","title":"Effects of Photobiomodulation (PBM) on Pain After Presentation of Aphthous Ulcers in Pediatric Dental Patients","acronym":null,"status":"RECRUITING","phases":["PHASE4"],"n":30,"start":"2025-03-10","end":"2026-02-27","allocation":"RANDOMIZED","masking":"NONE","conditions":["Aphthous Ulcer"],"interventions":[{"type":"DEVICE","name":"PBM Therapy"},{"type":"DRUG","name":"Maalox plus Benadryl"}],"sponsor":"The University of Texas Health Science Center, Houston","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Brett Thomas Chiquet","title":"Associate Professor","affiliation":"The University of Texas Health Science Center, Houston"},"officials":[{"name":"Brett Chiquet, DDS, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"The University of Texas Health Science Center, Houston"}],"countries":["United States"],"sites":[{"facility":"The University of Texas Health Science Center at Houston","city":"Houston","country":"United States"}],"n_sites":1,"outcome":"Change in Quality of life as assessed by questionnaire (Likert scale)","summary":"The purpose of this study is to compare the efficacy of laser photobiomodulation and \"Magic Mouthwash\" for treatment of pain in pediatric patients with aphthous ulcers , to assess how photobiomodulation influences the rate of healing of aphthous ulcers in pediatric patients and to measure changes in pain levels reported by pediatric patients undergoing photobiomodulation treatment for aphthous ulcers.","updated":"2025-03-25","first_posted":"2025-02-11","type":"INTERVENTIONAL","ctx":"inflammatoire","titre":"PBM contre la douleur des aphtes chez l'enfant"},{"nct":"NCT06708754","title":"Impact of Photobiomodulation (PBM) on Biomarkers of Radiation Lymphedema and Fibrosis in Head and Neck Cancer Patients","acronym":"PBM-LEF","status":"RECRUITING","phases":["NA"],"n":60,"start":"2025-02-13","end":"2028-02-13","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Radiation Lymphedema","Radiation Fibrosis","Head and Neck Cancer"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation (PBM) Therapy"},{"type":"DEVICE","name":"Sham PBM"}],"sponsor":"NYU Langone Health","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Kenneth Hu","role":"PRINCIPAL_INVESTIGATOR","affiliation":"NYU Langone Health"}],"countries":["United States"],"sites":[{"facility":"NYU Langone Health","city":"New York","country":"United States"}],"n_sites":1,"outcome":"Soft tissue thickness (STT) at Nodal Level II - Right Side","summary":"Radiation fibrosis syndrome (RFS) is a general side effect of radiation therapy (RT) which can adversely impact patients chronically over years typically triggered by an acute inflammatory state that evolves into chronic inflammation and tissue remodeling causing lymphedema, fibrosis, pain, atrophy and organ dysfunction. Some of the side effects that encompass RFS in the head and neck (HNC) population include decreased ability to fully open the mouth (trismus), neck pain and tightness (cervical dystonia), lymphedema (swelling), difficult with speech and swallowing and salivary hypofunction. Although there is Level I evidence demonstrating the benefit of Photobiomodulation (PBM) therapy to prevent acute mucositis in HNC patients treated with RT, there is only limited data regarding its impact.\n\nThis is a clinical trial to compare active treatment (PBM-therapy) with sham control (Sham- the","updated":"2026-03-30","first_posted":"2024-11-27","type":"INTERVENTIONAL","ctx":"radiodermite","titre":"PBM, lymphœdème et fibrose radio-induits des cancers ORL : biomarqueurs"},{"nct":"NCT06803472","title":"Pulsed High Intensity Laser Versus Extracorporeal Shockwave Therapy on Hypertrophic Scar Post Burn","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2025-01-26","end":"2025-02-10","allocation":"RANDOMIZED","masking":"NONE","conditions":["Hypertrophic Scar"],"interventions":[{"type":"DEVICE","name":"pulsed high intensity laser therapy"},{"type":"DEVICE","name":"Extracorporeal shockwave therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Amira Fayed Ali Ibrahim","title":"physiotherapist","affiliation":"Cairo University"},"officials":[{"name":"Haidy Nady Ashem, professor","role":"STUDY_DIRECTOR","affiliation":"faculty of physical therapy"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Modified Vancouver burn Scar assessment scale","summary":"The goal of this clinical trial stydy : is to compare between the effect of pulsed high intensity laser and extracorporeal shockwave therapy on hypertrophic scar on post burned patients.\n\nThe main questions is it aims to answer is :\n\n* Which is more effective on hypertrophic scar post burn Extracorporeal shockwave therapy or pulsed high intensity laser therapy?\n* Participants will receive the treatment for 6 weeks.\n* Assesment will be don before and after treatment.","updated":"2025-01-31","first_posted":"2025-01-31","type":"INTERVENTIONAL","ctx":"cicatrices","titre":"Laser haute intensité pulsé ou ondes de choc sur les cicatrices hypertrophiques de brûlure"},{"nct":"NCT07680309","title":"Evaluation Skin Stiffness Gradient on Skin After LLLT","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":20,"start":"2025-01-10","end":"2025-06-15","allocation":"RANDOMIZED","masking":"NONE","conditions":["Skin Stiffness","Skin Thickness","DFU","Wound and Injuries"],"interventions":[{"type":"OTHER","name":"LLLT intervention on skin biomechanical properties in different duration and wavelength"},{"type":"OTHER","name":"LLLT intervention on skin biomechanical properties in different duty cycle and applied frequency"}],"sponsor":"Asia University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Gilang Titah Ramadhan","title":"Optimization of Low-Level Laser Therapy via Biomechanical Properties Analysis Using Optical Coherence Tomography on Skin","affiliation":"Asia University"},"officials":[],"countries":["Taiwan"],"sites":[{"facility":"Asia University","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"Measurements skin stiffness gradient","summary":"This study evaluates the effects of Low-Level Laser Therapy (LLLT) on skin elasticity by measuring a 3x3 stiffness gradient across 9 points spaced 1 cm apart. Using an air-pressure pump integrated with an Optical Coherence Tomography (OCT) system, a deep learning model is utilized to automatically segment and track micro-scale skin movement during deformation.","updated":"2026-07-02","first_posted":"2026-07-02","type":"INTERVENTIONAL","ctx":"plaies","titre":"Gradient de rigidité cutanée après laser basse énergie"},{"nct":"NCT06756386","title":"Shock Wave Versus Low Level Laser on Chronic Venous Ulcer","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":45,"start":"2025-01-01","end":"2025-06-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Venous Ulcer"],"interventions":[{"type":"DEVICE","name":"extra corporeal shock wave therapy (ESWT )"},{"type":"DEVICE","name":"Low Level Laser Therapy"},{"type":"OTHER","name":"conservative treatments"}],"sponsor":"Beni-Suef University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mahmoud Awad Ramadan Elkholy","title":"Lecturer of Physical Therapy for Integumentary System and burn disorders, Faculty of Physical Therapy ,Beni-Suef University","affiliation":"Beni-Suef University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"ulcer size","summary":"To find out the difference in the effect of shock wave therapy and low level laser therapy on venous ulcer patient As regards the following outcomes;\n\n1. medical state of patient no ( diabetes, hypertension,obesity,cancer , rheumatoid)\n2. The degree of ulcer\n3. recurrence of ulcer\n4. The degree of pain and disabilities\n5. inflammatory marker","updated":"2025-01-03","first_posted":"2025-01-03","type":"INTERVENTIONAL","ctx":"plaies","titre":"Ondes de choc ou laser basse énergie dans l'ulcère veineux chronique"},{"nct":"NCT06708975","title":"Effect of Insulin Therapy by Ultrasonography in Wound Healing of Chronic Diabetic Patients","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":40,"start":"2024-12","end":"2025-02","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Diabetes Mellitus"],"interventions":[{"type":"OTHER","name":"Insulin therapy phonophoresis"},{"type":"OTHER","name":"Hyperpolarized light therapy and Standard wound cleaning and dressing."}],"sponsor":"MTI University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Radwa Fayek Hammam","title":"Lecturer at Basic Science Department, Faculty of Physical Therapy Modern University for Technology and Information","affiliation":"MTI University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"DMIST scale which is a valid and reliable scale for measuring depth, maceration, inflammation/infection, size, tissue type of the wound bed, type of wound edge, and tunneling/undermining.","summary":"The main aim of the study is to determine the effect of transdermal application of insulin therapy by phonophoresis in wound healing in diabetic patients the main question of the study: is insulin phonophoresis is effective in accelerating healing in patients with diabetes mellites? 40 patients will be randomly assigned to two groups group A will receive insulin phonophoresis plus hyper polarized laser therapy and standard wound cleaning and dressing three times weekly over four weeks.\n\nGroup B will receive hyper polarized laser therapy and standard wound cleaning and dressing three times weekly over four weeks.","updated":"2024-11-29","first_posted":"2024-11-29","type":"INTERVENTIONAL","ctx":"plaies","titre":"Lumière polarisée et phonophorèse d'insuline dans les plaies diabétiques"},{"nct":"NCT06703762","title":"Efficacy of Photobiomodulation on Wound Healing and Il-6 in Neuropathic Foot Ulcer","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":68,"start":"2024-11-26","end":"2025-01-26","allocation":"RANDOMIZED","masking":"NONE","conditions":["Neuropathic Foot Ulcer"],"interventions":[{"type":"OTHER","name":"He-Ne low level laser (LLL)"},{"type":"OTHER","name":"Conventional traditional treatment"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Fatma Mahmoud Abd Allah Abd Alsadek","title":"Principal Investigator","affiliation":"Cairo University"},"officials":[{"name":"Amal Mohamed Abd El-baky, PhD","role":"STUDY_CHAIR","affiliation":"Professor, Cairo university"}],"countries":["Egypt"],"sites":[{"facility":"Cairo University","city":"Giza","country":"Egypt"}],"n_sites":1,"outcome":"Measurement of Ulcer Length","summary":"The aim of this study is to detect the effect of Laser Photobiomodualation on the wound healing and Il-6 in neuropathic foot ulcer.","updated":"2024-11-25","first_posted":"2024-11-25","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM He-Ne, cicatrisation et IL-6 dans l'ulcère neuropathique du pied"},{"nct":"NCT07523204","title":"Photobiomodulation Therapy for Scar Quality After Facial Wound Closure","acronym":"PBMT-SCAR","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":36,"start":"2024-10-17","end":"2026-10-07","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Traumatic Facial Wounds"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation Therapy (PBMT)"},{"type":"DEVICE","name":"Sham Photobiomodulation Therapy"}],"sponsor":"Hani M. Al-Kufi","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Hani M. Al-Kufi","title":"Assistant Lecturer, College of Dentistry, Islamic University","affiliation":"Islamic University of Najaf"},"officials":[],"countries":["Iraq"],"sites":[{"facility":"Department of Oral and Maxillofacial Surgery, College of Dentistry, The Islamic University, Najaf, Iraq","city":"Kufa","country":"Iraq"}],"n_sites":1,"outcome":"Scar Quality Assessed by POSAS","summary":"This study is a prospective pilot randomized controlled trial designed to evaluate the effect of photobiomodulation therapy (PBMT) on scar quality following traumatic facial wound closure. Traumatic facial wounds often result in aesthetically and functionally significant scars, which may negatively affect patients' quality of life. PBMT has been proposed as a non-invasive adjunctive therapy that may enhance tissue repair, reduce inflammation, and improve scar outcomes.\n\nIn this study, patients with traumatic facial wounds undergoing primary closure will be randomly assigned to receive either PBMT or sham treatment following suture removal. Scar quality will be assessed using validated clinical scales over a defined follow-up period. The findings of this study aim to provide clinical evidence regarding the effectiveness of PBMT in improving scar appearance and overall healing outcomes.","updated":"2026-04-15","first_posted":"2026-04-13","type":"INTERVENTIONAL","ctx":"cicatrices","titre":"PBM contre sham et qualité de la cicatrice après suture d'une plaie du visage"},{"nct":"NCT07177274","title":"Evaluation of Skin Stiffness Changes in Wounds Before and After Low-Level Laser Therapy","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":20,"start":"2024-09-19","end":"2025-07-24","allocation":"RANDOMIZED","masking":"NONE","conditions":["Wound - in Medical Care"],"interventions":[{"type":"RADIATION","name":"Low Level Laser Therapy"}],"sponsor":"Asia University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Taiwan"],"sites":[{"facility":"Asia University","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"To evaluate changes in skin stiffness of wound tissue before and after LLLT using OCT and MyotonPRO.","summary":"Chronic wounds and impaired healing remain a major clinical challenge, particularly in patients with diabetes, vascular disease, or age-related skin fragility. Low-level laser therapy (LLLT) at 660 nm has been reported to enhance tissue repair, reduce inflammation, and promote angiogenesis. However, the biomechanical properties of wound tissue following LLLT remain poorly understood.\n\nOptical Coherence Tomography (OCT) provides a non-invasive, high-resolution method to assess skin microstructure and elasticity, while the MyotonPRO offers quantitative stiffness measurements at the tissue surface. Combining these two complementary modalities may provide a more comprehensive assessment of wound healing progression and treatment response.\n\nThis study aims to evaluate changes in wound stiffness before and after 660 nm LLLT and to compare them against contralateral normal skin, thereby providi","updated":"2025-09-16","first_posted":"2025-09-16","type":"INTERVENTIONAL","ctx":"plaies","titre":"Rigidité cutanée des plaies avant et après laser basse énergie"},{"nct":"NCT05177289","title":"Photobiomodulation Therapy in the Prevention and Management of Chemotherapy-Induced Alopecia","acronym":"HairLight","status":"RECRUITING","phases":["NA"],"n":72,"start":"2022-02-28","end":"2025-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Chemotherapy-induced Alopecia"],"interventions":[{"type":"DEVICE","name":"Theradome® LH80 pro"},{"type":"DEVICE","name":"Scalp cooling"}],"sponsor":"Jessa Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Jeroen Mebis, Prof. Dr.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Jessa Hospital"}],"countries":["Belgium"],"sites":[{"facility":"Jessa Hospital","city":"Hasselt","country":"Belgium"}],"n_sites":1,"outcome":"Hair thickness measurement","summary":"This study aims to investigate the effectiveness of photobiomodulation therapy (PBM) in the prevention and management of chemotherapy-induced alopecia (CIA). Therefore, we hypothesize that PBMT can reduce the severity of CIA in gynecological and breast cancer patients, increasing the patient's QoL.","updated":"2023-09-29","first_posted":"2022-01-04","type":"INTERVENTIONAL","ctx":"alopécie","titre":"PBM (casque Theradome) et casque réfrigérant contre l'alopécie chimio-induite"},{"nct":"NCT04764331","title":"A Pilot Study of Revian Red All LED Cap as a Novel Treatment for Central Centrifugal Cicatricial Alopecia","acronym":null,"status":"RECRUITING","phases":["NA"],"n":5,"start":"2021-07-06","end":"2026-12","allocation":"NA","masking":"NONE","conditions":["Central Centrifugal Cicatricial Alopecia"],"interventions":[{"type":"DEVICE","name":"Revian Red All LED cap"}],"sponsor":"Wake Forest University Health Sciences","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Amy McMichael, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Wake Forest University Health Sciences"}],"countries":["United States"],"sites":[{"facility":"Wake Forest School of Medicine - Dermatology Clinic","city":"Winston-Salem","country":"United States"}],"n_sites":1,"outcome":"hairline stabilization","summary":"Central centrifugal cicatricial alopecia (CCCA) is form of scarring hair loss that predominately affects middle-aged women of African descent.1 . Clinically, the natural progression of CCCA starts at the crown as roughly circular scarred patches, which evolve into scarred areas increasing in size circumferentially. Characteristically, the scar is often smooth and shiny, and the hair density in the affected area is frequently decreased. The hair remaining in the scarred areas is more brittle and shorter than the hair in unaffected areas. Since CCCA is a scarring disorder, it can cause permanent hair loss, dyesthesias, and psychological distress which can affect overall quality of life. Affected individuals may complain of pruritus, pain, or tenderness.2\n\nThe management of CCCA is challenging due to limited current treatments and a lack of randomized controlled trails. Management focuses o","updated":"2026-09-09","first_posted":"2021-02-21","type":"INTERVENTIONAL","ctx":"alopécie","titre":"Casque LED Revian dans l'alopécie cicatricielle centrale centrifuge (pilote)"},{"nct":"NCT07520825","title":"Laser Photobiomodulation for Hard-to-heal Ulcers in Frail Older Adults","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":1290,"start":"2020-09-01","end":"2023-05-30","allocation":"NON_RANDOMIZED","masking":"NONE","conditions":["Hard-to-heal Wounds","Venous Leg Ulcer (VLU)","Arterial Leg Ulcer","Pressure Ulcer (PU)"],"interventions":[{"type":"PROCEDURE","name":"Photobiomodulation"},{"type":"PROCEDURE","name":"Standard-of-care ulcer dressing"}],"sponsor":"Umeå University","sponsor_class":"OTHER","collaborators":["Karolinska Institutet","Luleå University of Technology","Skellefteå Municipality"],"responsible":null,"officials":[{"name":"Åsa Audulv, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Department of Nursing, Umeå University, Sweden"}],"countries":["Sweden"],"sites":[{"facility":"Skellefteå municipality","city":"Skellefteå","country":"Sweden"}],"n_sites":1,"outcome":"Healing time: Time in days from initiation of PBM/(baseline registration) until healing.","summary":"The aim of this quasi-experimental prospective study is to evaluate the effectiveness of photobiomodulation treatment on hard-to-heal ulcers of various diagnosed aetiologies in frail older adults, admitted to municipal home healthcare. The study also include evaluation of cost-effectiveness, and healthcare providers experiences of treating frail older adults hard-to-heal ulcers with photobiomodulation treatment in home healthcare.","updated":"2026-04-09","first_posted":"2026-04-09","type":"INTERVENTIONAL","ctx":"plaies","titre":"PBM laser des ulcères difficiles à cicatriser chez le sujet âgé fragile (Suède, 1 290 patients)"},{"nct":"NCT03716167","title":"Randomized Controlled Trial for Treatment of Pain and Assessment of Wound Healing in Chronic Venous Leg Ulcers Using Near Infrared Laser Therapy","acronym":null,"status":"RECRUITING","phases":["NA"],"n":20,"start":"2018-07-27","end":"2027-10","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Venous Leg Ulcer"],"interventions":[{"type":"DEVICE","name":"Summus Laser"},{"type":"DEVICE","name":"Summus Laser Sham"}],"sponsor":"Wake Forest University Health Sciences","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Joseph Molnar, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"WFUHS"}],"countries":["United States"],"sites":[{"facility":"Wake Forest University Health Sciences","city":"Winston-Salem","country":"United States"}],"n_sites":1,"outcome":"Pain measured by survey","summary":"The laser emits an infrared light that heats the skin and underlying tissues with the purpose of temporary relief of minor muscle and joint pain, as well as stiffness associated with arthritis. The laser also causes a temporary increase in blood flow. The purpose of this study is to evaluate whether laser therapy can provide pain relief and speed the healing of venous leg ulcers.","updated":"2026-07-29","first_posted":"2018-10-23","type":"INTERVENTIONAL","ctx":"plaies","titre":"Laser Summus contre sham : douleur et cicatrisation des ulcères veineux"}],"neurologie":[{"nct":"NCT05855694","title":"Photobiomodulation for Cancer-Related Cognitive Impairment","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":30,"start":"2027-01","end":"2029-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Cancer-related Cognitive Impairment"],"interventions":[{"type":"DEVICE","name":"THOR LED Photobiomodulation Helmet - Therapeutic"},{"type":"DEVICE","name":"THOR LED Photobiomodulation Helmet - Control"}],"sponsor":"Arash Asher, MD","sponsor_class":"OTHER","collaborators":["Thor"],"responsible":{"name":"Arash Asher, MD","title":"Director, Cancer Survivorship and Rehabilitation, Patient and Family Support Program","affiliation":"Cedars-Sinai Medical Center"},"officials":[{"name":"Arash Asher, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Cedars-Sinai Medical Center"}],"countries":["United States"],"sites":[{"facility":"Clinical Trial Recruitment Navigator","city":"Los Angeles","country":"United States"}],"n_sites":1,"outcome":"Cognitive Symptoms","summary":"This is a single site, pilot randomized, double blinded control trial designed to assess changes in cognitive symptoms in cancer survivors with cancer-related cognitive impairment. Patients will be randomized into one of two Arms: Intervention or Control.\n\n* Arm A: Intervention Group: Use of the THOR LED Photobiomodulation helmet 3x per week for 6 weeks. Helmet will be in 'therapeutic setting', 35mW/cm2 = 42J/cm2\n* Arm B: Control Group: Use of the THOR LED Photobiomodulation helmet 3x per week for 6 weeks. Helmet will be in 'placebo setting', 0mW/cm2 = 0J/cm2\n\nThis study has been designed to assess the hypothesis that Photobiomodulation can have a positive impact on cognitive symptoms in cancer survivors with cancer-related cognitive impairment.\n\n30 participants will be recruited for this study, 15 per group. Self-report questionnaires assessing cognitive concerns, cognitive abilities, q","updated":"2026-11-04","first_posted":"2023-05-11","type":"INTERVENTIONAL","ctx":"démences","titre":"Casque LED THOR dans les troubles cognitifs liés au cancer"},{"nct":"NCT07520383","title":"Nanopulse Laser Therapy","acronym":null,"status":"NOT_YET_RECRUITING","phases":["PHASE1"],"n":30,"start":"2026-12-01","end":"2027-05","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["TBI (Traumatic Brain Injury)"],"interventions":[{"type":"DEVICE","name":"Nano-Pulsed Laser Therapy (NPLT)"}],"sponsor":"The University of Texas Medical Branch, Galveston","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Patrick Karas, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Texas Medial Branch"}],"countries":["United States"],"sites":[{"facility":"University of Texas Medical Branch","city":"Galveston","country":"United States"}],"n_sites":1,"outcome":"Feasibility of Nano-pulsed laser therapy (NPLT) Administration Following Moderate to Severe Traumatic Brain Injury","summary":"The purpose of this study is to evaluate the safety and effectiveness of a novel noninvasive therapy, Nanopulse Laser Therapy (NPLT), to improve recovery following traumatic brain injury (TBI).","updated":"2026-11-06","first_posted":"2026-04-09","type":"INTERVENTIONAL","ctx":"TC","titre":"Laser nanopulsé (NPLT) dans la récupération après traumatisme crânien"},{"nct":"NCT07807176","title":"Neuromodulation Combined With Dual FES Cycling and Cognitive Training After Stroke","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":150,"start":"2026-12-01","end":"2028-10-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Stroke"],"interventions":[{"type":"DEVICE","name":"Functional Electrical Stimulation Cycling"},{"type":"BEHAVIORAL","name":"Cognitive Task Training"},{"type":"DEVICE","name":"Transcutaneous Auricular Photobiomodulation"},{"type":"DEVICE","name":"Transcutaneous Forehead Photobiomodulation"},{"type":"DEVICE","name":"Sham Functional Electrical Stimulation Cycling"},{"type":"DEVICE","name":"Sham Photobiomodulation"}],"sponsor":"Chang Gung Memorial Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Chia-Ling Chen","role":"STUDY_DIRECTOR","affiliation":"Chang Gung Memorial Hospital"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Trail Making Test-Part B (TMT-B)","summary":"This study will evaluate the effects of functional electrical stimulation (FES) cycling, cognitive task training, and non-invasive photobiomodulation on cognitive and upper-limb motor performance in adults after stroke. The study includes three stages to identify favorable FES cycling and neuromodulation approaches and to evaluate their combined effects. Participants will complete 10 intervention sessions over 2 weeks. Cognitive and motor outcomes will be assessed before treatment, immediately after treatment, and at 3-month follow-up. Feasibility, tolerance, and adverse events will also be evaluated.","updated":"2026-11-05","first_posted":"2026-09-08","type":"INTERVENTIONAL","ctx":"AVC","titre":"Neuromodulation dont PBM auriculaire, vélo FES et entraînement cognitif après AVC"},{"nct":"NCT07891585","title":"Laser Acupuncture for Chronic Migraine: Clinical Response, Traditional Chinese Medicine Syndrome Patterns, and Brain Function","acronym":"PRISM-CM","status":"NOT_YET_RECRUITING","phases":["NA"],"n":300,"start":"2026-11-01","end":"2030-12-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Chronic Migraine Headache"],"interventions":[{"type":"DEVICE","name":"810 nm laser acupuncture"},{"type":"DEVICE","name":"Sham Laser Acupuncture"}],"sponsor":"Taichung Veterans General Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Huan-Yun Wu","title":"MD","affiliation":"Taichung Veterans General Hospital"},"officials":[],"countries":["Taiwan"],"sites":[{"facility":"Taichung Veterans General Hospital Copy","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"Change From Baseline in Monthly Migraine Days (MMD) at Week 12","summary":"The PRISM-CM study will test whether 810-nanometer laser acupuncture reduces migraine days and related symptoms in adults with chronic migraine. Laser acupuncture uses low-level laser light at acupuncture points without inserting needles. The study will also assess safety and explore whether clinical features, traditional Chinese medicine syndrome patterns, and brain function are associated with differences in treatment response.\n\nThis study will enroll 135 participants at Taichung Veterans General Hospital: 90 patients with chronic migraine and 45 healthy volunteers. After keeping a headache diary for 4 weeks before treatment, patients will be assigned by chance to active laser acupuncture or sham laser acupuncture, with 45 patients in each group. Sham treatment uses the same acupuncture points and procedures but does not deliver therapeutic laser energy. Healthy volunteers will not be ","updated":"2026-10-23","first_posted":"2026-10-23","type":"INTERVENTIONAL","ctx":"autres","titre":"Laser-acupuncture 810 nm dans la migraine chronique : réponse clinique et imagerie"},{"nct":"NCT07602296","title":"Evaluating How Red-light Therapy Applied to the Head Affects Symptoms, Daily Life, and Brain Activity in People With Dementia With Lewy Bodies","acronym":"LewyLIGHT","status":"RECRUITING","phases":["NA"],"n":40,"start":"2026-09-16","end":"2029-05","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Photobiomodulation","Dementia With Lewy Bodies"],"interventions":[{"type":"DEVICE","name":"LUCIOLE CAP"},{"type":"DEVICE","name":"LUCIOLE CAP (sham version)"}],"sponsor":"University Hospital, Strasbourg, France","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["France"],"sites":[{"facility":"Hôpitaux Universitaires de Strasbourg","city":"Strasbourg","country":"France"}],"n_sites":1,"outcome":"Repeatable Battery for the Assessment of Neuropsychological Status (RBANS)","summary":"Dementia with Lewy bodies (DLB) is a neurodegenerative disease diagnosed primarily based on the presence of cognitive decline, which may include difficulties with memory, attention, and more. Additionally, at least two of the following symptoms are needed for a probable diagnosis of DLB, and at least one for a possible DLB diagnosis (McKeith et al. 2017 and 2020):\n\n* Fluctuations in cognition, attention, and/or alertness\n* Visual hallucinations\n* Spontaneous parkinsonism\n* REM sleep behavior disorder\n\nPatients with DLB can experience cognitive deficits that can fluctuate and can vary for each patient. These may include deficits in memory, executive functions (planning and organizing), attention, visual processing, and language.\n\nThis study aims to evaluate the effect of red-light therapy, delivered using a helmet that contains small LED lights, in patients with DLB.\n\nParticipants' cognit","updated":"2026-10-27","first_posted":"2026-05-22","type":"INTERVENTIONAL","ctx":"démences","titre":"Casque LUCIOLE de lumière rouge contre sham dans la démence (France)"},{"nct":"NCT07224607","title":"Transcranial Photobiomodulation (tPBM) in Alzheimer's Disease Study","acronym":null,"status":"RECRUITING","phases":["NA"],"n":45,"start":"2026-09-01","end":"2027-11-28","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Alzheimer's Disease"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"Cedars-Sinai Medical Center","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Golnaz Yadollahikhales","title":"Principal Investigator","affiliation":"Cedars-Sinai Medical Center"},"officials":[{"name":"Golnaz Yadollahikhales, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Cedars Siinai Medical Center Department of Neurology"}],"countries":["United States"],"sites":[{"facility":"CSMC","city":"Los Angeles","country":"United States"}],"n_sites":1,"outcome":"NIH Toolbox","summary":"The purpose of this study is to see if a special light treatment, called photobiomodulation, can help people with memory problems such as Mild Cognitive Impairment or Mild Dementia due to Alzheimer's disease. The light is given to the forehead using an FDA-cleared medical device. This device is cleared to provide topical heating to elevate tissue temperature for temporary relief of muscle and joint pain, muscle spasm and stiffness associated with arthritis. It also increases blood circulation and relaxes muscle tissue. This device is being used \"off-label,\" meaning it will be used in a way that is different than its cleared use.\n\nWe want to learn whether this light treatment can improve executive function, and whether it changes certain inflammatory and neurodegeneration related signals in the blood. To do this, we will apply the photobiomodulation device to your forehead. We will also a","updated":"2026-10-13","first_posted":"2025-11-04","type":"INTERVENTIONAL","ctx":"démences","titre":"PBM transcrânienne dans la maladie d'Alzheimer"},{"nct":"NCT07790094","title":"Segmental Laser Acupuncture for Constipation and Sleep in Patients With Parkinson's Disease","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-09-01","end":"2027-08-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Parkinson's Disease"],"interventions":[{"type":"DEVICE","name":"TI-816-3E3 Portable Laser Phototherapy Device"},{"type":"DEVICE","name":"TI-816-3E3 Portable Laser Phototherapy Device - Sham (0 J/cm²)"}],"sponsor":"China Medical University Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yu-Chen Lee","title":"Director, Department of Acupuncture","affiliation":"China Medical University Hospital"},"officials":[],"countries":["Taiwan"],"sites":[{"facility":"China Medical University Hospital","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"Change in Constipation Scoring System (CSS; Agachan score)","summary":"Parkinson's disease (PD) is characterized not only by motor symptoms but also by common and clinically significant non-motor symptoms, including constipation and sleep disturbances, which can substantially impair quality of life. The concept of the \"gut-brain axis\" describes bidirectional communication among the central nervous system, autonomic nervous system, enteric nervous system, and gut microbiota. Increasing evidence from animal models suggests that the gut-brain axis may play an important role in the pathophysiology and progression of PD.\n\nGiven the central role of autonomic nervous system regulation in the gut-brain axis, this study will use laser acupuncture as a safe, non-invasive form of photobiomodulation (PBM) with potential neuromodulatory effects. Based on the concept of segmental neuromodulation, laser stimulation will be applied to the thoracolumbar paraspinal regions (","updated":"2026-08-27","first_posted":"2026-08-27","type":"INTERVENTIONAL","ctx":"parkinson","titre":"Laser-acupuncture segmentaire contre la constipation et les troubles du sommeil du Parkinson"},{"nct":"NCT07784231","title":"The Use of Photobiomodulation in the Treatment of Spasticity After Stroke.","acronym":"DarbarIllora","status":"RECRUITING","phases":["PHASE1","PHASE2"],"n":42,"start":"2026-08-28","end":"2027-04-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Stroke","Spasticity","Photobiomodulation","NIRS"],"interventions":[{"type":"RADIATION","name":"Photobiomodulation Therapy"},{"type":"RADIATION","name":"Placebo PBM"},{"type":"OTHER","name":"Standard Multidisciplinary Rehabilitation Program for Spasticity"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Rebeca Boltes Cecatto","title":"Professor M.D. Ph.D. Rebeca Boltes Cecatto","affiliation":"University of Nove de Julho"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"CER II Guarulhos","city":"São Paulo","country":"Brazil"}],"n_sites":1,"outcome":"Spasticity Grade","summary":"Stroke is a non-progressive and permanent syndrome in adults, with approximately 60% of patients presenting with spastic hemiparesis. Spasticity leads to changes in the physiological pattern of muscle tissue contraction and hemodynamics, and, when left untreated, negatively impacts functionality. Photobiomodulation (PBM) has demonstrated positive effects on tissue regeneration, muscle relaxation, reduction of inflammation, fatigue, and pain relief in various muscular and neurological disorders. Methods: This blinded, randomized, controlled clinical trial aims to evaluate the effects of PBM on triceps surae muscle spasticity in adults with stroke. Forty-two participants with spastic hemiparesis post-stroke will be randomized into two groups: active PBM (850 nm, 200 mW, 4 J/point in the gastrocnemius, 12 points, weekly for 8 weeks) or placebo PBM (same protocol, device switched off). Both ","updated":"2026-09-01","first_posted":"2026-08-25","type":"INTERVENTIONAL","ctx":"AVC","titre":"PBM contre placebo dans la spasticité après AVC"},{"nct":"NCT07547423","title":"Auricular Laser Acupuncture for Improving Sleep in Breast Cancer Patients","acronym":null,"status":"RECRUITING","phases":["NA"],"n":70,"start":"2026-08-26","end":"2027-06-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Breast Cancer Females","Insomnia"],"interventions":[{"type":"DEVICE","name":"auricular laser acupuncture"},{"type":"DEVICE","name":"sham auricular laser acupuncture"}],"sponsor":"CHING-RONG HUANG","sponsor_class":"OTHER","collaborators":["Chung Shan Medical University"],"responsible":{"name":"CHING-RONG HUANG","title":"Attending Physican","affiliation":"Chung Shan Medical University"},"officials":[],"countries":["Taiwan"],"sites":[{"facility":"Chung Shan Medical University Hospital","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"Pittsburgh Sleep Quality Index (PSQI)","summary":"The goal of this clinical trial is to learn if auricular laser acupuncture can improve sleep quality and alleviate related symptoms in female breast cancer patients aged 18 to 75 with insomnia. The main questions it aims to answer are:\n\n1. Does active auricular laser acupuncture improve sleep quality and reduce the severity of insomnia?\n2. Does it help lower levels of cancer-related fatigue, anxiety, and depression?\n\nResearchers will compare an active auricular laser acupuncture group to a sham control group (receiving no therapeutic laser energy) to see if active laser acupuncture is effective for symptom relief.\n\nParticipants will:\n\n1. Receive 10 sessions of laser treatment (active or sham) twice a week for 5 weeks, while wearing protective goggles to ensure blinding.\n2. Wear an actigraphy wristband and keep a sleep diary to monitor sleep patterns, and undergo heart rate variability (H","updated":"2026-10-07","first_posted":"2026-04-23","type":"INTERVENTIONAL","ctx":"humeur","titre":"Laser-acupuncture auriculaire et sommeil après cancer du sein"},{"nct":"NCT07764107","title":"Photobiomodulation for Reducing Sedative-Hypnotic Use:Clinical Trial of a Light-Therapy Device","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-08-01","end":"2027-05-05","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Insomnia"],"interventions":[{"type":"DEVICE","name":"PBM intervention"},{"type":"DEVICE","name":"Inactive sham control"}],"sponsor":"National Health Research Institutes, Taiwan","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Sleep quality","summary":"Background: Insomnia is a prevalent and growing public health issue, with one in three adults affected globally and one in five Taiwanese adults reporting significant sleep disturbances. Long-term use of sedative-hypnotic medications remains common in Taiwan despite clinical guidelines recommending short-term use only, contributing to adverse outcomes such as impaired sleep architecture, cognitive deficits, and elevated dementia risk. Non-pharmacological interventions-particularly light-based therapies-offer promising alternatives but existing bright-light therapy is limited by melatonin suppression and the need for precise daytime timing. Recent advances in photobiomodulation (PBM) suggest that red and near-infrared light, which do not suppress melatonin, may enhance sleep quality and support glymphatic clearance when applied during sleep. Preliminary findings from our prior NSTC-funded","updated":"2026-08-21","first_posted":"2026-08-13","type":"INTERVENTIONAL","ctx":"humeur","titre":"PBM pour réduire la consommation d'hypnotiques"},{"nct":"NCT07510646","title":"Transcranial Photobiomodulation for Bipolar Depression","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":40,"start":"2026-07-01","end":"2027-07-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Bipolar","Bipolar Disorder (BD)","Bipolar Disorder Depression"],"interventions":[{"type":"DEVICE","name":"Vielight Neuro Rx Gamma"},{"type":"DEVICE","name":"Sham Device"}],"sponsor":"Vielight Inc.","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[],"countries":["Canada"],"sites":[{"facility":"Providence Care Hospital","city":"Kingston","country":"Canada"}],"n_sites":1,"outcome":"Montgomery-Asberg Depression Rating Scale (MADRS)","summary":"This study the effectiveness and safety of light therapy device targeted at the brain using a wearable device, the Vielight RX Gamma as a treatment for bipolar depression. Up to forty patients with bipolar disorder will be enrolled into the study and will either receive active treatment with the Vielight RX Gamma or sham (inactive device). They will be administered the devices in clinic 5days/week for 6 weeks. Changes in disease symptoms, cognitive function, pain, quality of life and rest EEG changes will be assessed.","updated":"2026-04-03","first_posted":"2026-04-03","type":"INTERVENTIONAL","ctx":"humeur","titre":"PBM transcrânienne (Vielight) dans la dépression bipolaire"},{"nct":"NCT07546539","title":"Photobiomodulation in Chronic Fatigue Syndrome","acronym":null,"status":"RECRUITING","phases":["NA"],"n":40,"start":"2026-06-15","end":"2026-12-15","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Chronic Fatigue Syndrome (CFS)","Quality of Life"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation (Low-Level Laser Therapy)"},{"type":"DEVICE","name":"sham Photobiomodulation (LLLT)"}],"sponsor":"University of Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Aadil Ameer Ali","title":"Prof","affiliation":"University of Lahore"},"officials":[],"countries":["Pakistan"],"sites":[{"facility":"The larkana General hospital , larkana","city":"Larkana","country":"Pakistan"}],"n_sites":1,"outcome":"Fatigue Improvement","summary":"The goal of this clinical trial is to evaluate whether photobiomodulation therapy (low-level laser therapy) can reduce fatigue and improve quality of life in patients with chronic fatigue syndrome (CFS). The study will include adults aged 18-60 years diagnosed with chronic fatigue syndrome.\n\nThe main questions it aims to answer are:\n\nDoes photobiomodulation therapy significantly reduce fatigue levels as measured by the Fatigue Severity Scale (FSS) and Multidimensional Fatigue Inventory (MFI-20)? Does photobiomodulation therapy improve pain, functional capacity, sleep quality, and psychological well-being in patients with chronic fatigue syndrome?\n\nResearchers will compare the low-level laser therapy group with a placebo (sham laser) group to determine whether photobiomodulation therapy leads to greater improvements in fatigue, pain, and overall quality of life.\n\nParticipants will:\n\nRecei","updated":"2026-10-08","first_posted":"2026-04-22","type":"INTERVENTIONAL","ctx":"fatigue","titre":"PBM contre sham dans le syndrome de fatigue chronique"},{"nct":"NCT07445945","title":"Physiological Effect of Non-invasive Photobiomodulation on Cognition and Mood in Older Adults With Subjective Cognitive Impairment","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":80,"start":"2026-06","end":"2028-07","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Subjective Cognitive Decline (SCD)","Subjective Cognitive Impairment"],"interventions":[{"type":"OTHER","name":"Photobiomodulation"},{"type":"OTHER","name":"Sham (No Treatment)"}],"sponsor":"Baycrest","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Jean Chen","title":"Senior Scientist","affiliation":"Baycrest"},"officials":[],"countries":["Canada"],"sites":[{"facility":"Rotman Research Institute","city":"Toronto","country":"Canada"}],"n_sites":1,"outcome":"Geriatric Depression Scale (Short Form)","summary":"Subjective cognitive impairment (SCI) is a non-clinical condition manifesting as a self-reported decline in cognitive function without objective clinical evidence, and is prevalent among older adults and strongly associated with declining mood. This study explores the potential of photobiomodulation (PBM) as a therapeutic intervention for SCI. PBM, using near-infrared light, is a non-invasive neuromodulation approach that has shown promise in improving neuronal function, blood flow, and reducing inflammation in both healthy adults and patients with neurological conditions, including dementia and depression. This study proposes investigating the potential of forehead (tPBM), intranasal (iPBM) and vagal (vPBM) PBM to enhance mood and cognitive function in individuals with SCI as a proof of concept for the future use of PBM as therapy for cognitive decline in general.\n\nThis study will recru","updated":"2026-03-03","first_posted":"2026-03-03","type":"INTERVENTIONAL","ctx":"démences","titre":"PBM, cognition et humeur du sujet âgé avec plainte cognitive"},{"nct":"NCT07232472","title":"Wearable-Based Study of Depression and Sleep in Older Adults","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":162,"start":"2026-04-23","end":"2028-12-31","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Elderly Depression","Sleep Disturbance"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"DEVICE","name":"Sham (No Treatment)"}],"sponsor":"China Medical University Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Ta-wei Guu","title":"Consultant Psychiatrist","affiliation":"China Medical University Hospital"},"officials":[],"countries":["United Kingdom"],"sites":[{"facility":"China Medical University Beigang Hospital","city":"London","country":"United Kingdom"}],"n_sites":1,"outcome":"Sleep and Circadian Rhythm","summary":"This 4-year study aims to develop a safe and effective management model for late-life depression using wearable technologies. The research will recruit older adults (aged 60 and above) with major depressive disorder, confirmed by DSM-5 criteria.\n\nIn the first phase, participants will wear a research-grade actigraphy device (Geneactiv) for at least four weeks to assess its usability and accuracy compared with traditional questionnaires. In later phases, a double-blind randomized clinical trial will evaluate the efficacy of a photobiomodulation (PBM) headband in improving depressive and sleep symptoms.\n\nThe project will also establish Taiwan's first longitudinal database integrating wearable data, clinical symptoms, and biological markers, aiming to identify digital phenotypes and predictive biomarkers for elderly depression. The study is expected to advance precision psychiatry and digita","updated":"2026-06-17","first_posted":"2025-11-18","type":"INTERVENTIONAL","ctx":"humeur","titre":"PBM, dépression et sommeil du sujet âgé suivis par objets connectés"},{"nct":"NCT07542899","title":"Photobiomodulation on Core Symptoms of Autism","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":30,"start":"2026-04-10","end":"2026-07-10","allocation":"RANDOMIZED","masking":"NONE","conditions":["Autism"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"Suez University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Aya salah el din fouad rostom","title":"Lecturer of physical therapy for general surgery, Burn and skin, Suez university, Suez ,Egypt","affiliation":"Suez University"},"officials":[{"name":"Alaa Mohammed Naguib, Lecturer","role":"STUDY_DIRECTOR","affiliation":"Cairo University"},{"name":"Mahmoud Usama Mahmoud, Lecturer","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Cairo University"},{"name":"Ahmed Mamdouh Tawfik, Lecturer","role":"STUDY_CHAIR","affiliation":"Cairo University"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Improvement in core symptoms of autism","summary":"This study aims to evaluate the effectiveness of photobiomodulation therapy on core symptoms in children with autism spectrum disorder. Participants will receive designed physical therapy, occupational therapy and speech program in addition to Photobiomodulation over a defined period. Out comes will be assessed using standardized clinical scales to determine improvements in social interactions, communication and behavior.","updated":"2026-04-21","first_posted":"2026-04-21","type":"INTERVENTIONAL","ctx":"neurodev","titre":"PBM sur les symptômes centraux de l'autisme"},{"nct":"NCT07543328","title":"Transcranial Photobiomodulation (tPBM) for Somatic Symptoms in Treatment-Resistant Depression","acronym":null,"status":"RECRUITING","phases":["NA"],"n":40,"start":"2026-01-06","end":"2026-12-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Treatment-resistant Depression (TRD)","Major Depression Disorder"],"interventions":[{"type":"DEVICE","name":"transcranial photobiomodulation"}],"sponsor":"Taipei Veterans General Hospital, Taiwan","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":null,"officials":[],"countries":["Taiwan"],"sites":[{"facility":"Taipei Veterans General Hospital","city":"Taipei","country":"Taiwan"}],"n_sites":1,"outcome":"Change in the 17-item Hamilton Depression Rating Scale (HDRS-17) Total Score","summary":"The primary objective of this study is to evaluate the clinical efficacy of moderate-dose transcranial photobiomodulation (t-PBM) at different frequencies (10 Hz and 40 Hz) in patients with treatment-resistant depression (TRD). It further aims to explore the differential efficacy across various symptom subtypes, with a particular focus on the somatic symptom-dominant subtype. Additionally, this study will collect paired-pulse neurophysiological parameters (e.g., the ratio of cortical inhibition to excitation) to preliminarily explore the neural mechanisms underlying the modulation of cortical excitability by t-PBM intervention, and to analyze their correlation with the magnitude of clinical symptom improvement.\n\nThe specific aims of this study are as follows:\n\nTo evaluate the differential efficacy of t-PBM at varying frequencies (10 Hz vs. 40 Hz) in improving clinical depressive symptoms","updated":"2026-04-30","first_posted":"2026-04-21","type":"INTERVENTIONAL","ctx":"humeur","titre":"PBM transcrânienne et symptômes somatiques de la dépression résistante"},{"nct":"NCT07323823","title":"The Effect of PBM on the Electrical Activity of the Brain in Stroke Patients","acronym":"PBM","status":"NOT_YET_RECRUITING","phases":["NA"],"n":66,"start":"2025-12-31","end":"2026-12-31","allocation":"RANDOMIZED","masking":"NONE","conditions":["Post-stroke Aphasia"],"interventions":[{"type":"DEVICE","name":"photobiomodulation (PBM)"},{"type":"OTHER","name":"control group-receive speech therapy"}],"sponsor":"Pusan National University Yangsan Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yong-il Shin","title":"PhD","affiliation":"Pusan National University Yangsan Hospital"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"electroencephalography (EEG)","summary":"The Effect of Low-Level Light Therapy on the Electrical Activity of the Brain in Stroke Patients","updated":"2026-01-07","first_posted":"2026-01-07","type":"INTERVENTIONAL","ctx":"AVC","titre":"PBM et activité électrique cérébrale après AVC (aphasie)"},{"nct":"NCT06956404","title":"tPBM in Older Adults With Traumatic Brain Injury","acronym":null,"status":"RECRUITING","phases":["NA"],"n":70,"start":"2025-12-29","end":"2028-07","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Traumatic Brain Injury"],"interventions":[{"type":"DEVICE","name":"Transcranial photobiomodulator (tPBM)"},{"type":"DEVICE","name":"Transcranial photobiomodulator (tPBM) in sham mode"}],"sponsor":"NYU Langone Health","sponsor_class":"OTHER","collaborators":["United States Department of Defense"],"responsible":null,"officials":[{"name":"Tamara Bushnik, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"NYU Langone Health"}],"countries":["United States"],"sites":[{"facility":"NYU Langone Health","city":"New York","country":"United States"}],"n_sites":1,"outcome":"Change in prefrontal Cerebral Blood Flow (CBF)","summary":"The purpose of this study is to evaluate the effect of transcranial photobiomodulation (tPBM) in older patients with chronic traumatic brain injury (TBI). The study aims to examine the effect of tPBM on prefrontal cerebral blood flow (CBF) and executive function (EF)","updated":"2026-01-15","first_posted":"2025-05-04","type":"INTERVENTIONAL","ctx":"TC","titre":"PBM transcrânienne chez le sujet âgé après traumatisme crânien"},{"nct":"NCT07308080","title":"Combined Effects of Near-Infrared Light and Vibration on Diabetic Patients With Restless Leg Syndrome","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":42,"start":"2025-12-14","end":"2026-05","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Restless Leg Syndrome (RLS)"],"interventions":[{"type":"OTHER","name":"Near-Infrared Light Therapy"},{"type":"OTHER","name":"Vibration"},{"type":"BEHAVIORAL","name":"Conventional Physical Therapy"}],"sponsor":"Lahore University of Biological and Applied Sciences","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"International Restless Legs Syndrome Rating Scale (IRLS)","summary":"This Randomized Clinical Trial, titled \"Combined Effects of Near-Infrared Light and Vibration on Pain, Sleep Quality and Symptom Severity in Diabetic Patients with Restless Leg Syndrome,\" aims to evaluate a non-pharmacological treatment for Restless Leg Syndrome (RLS) in diabetic patients. RLS is a neurological disorder causing an irresistible urge to move the legs, and its co-occurrence with diabetes significantly worsens symptoms, pain, and sleep quality. While both Near-Infrared (NIR) light therapy and vibration therapy have individually shown benefits, this study will investigate the potential synergistic effects of combining them. 42 diabetic patients with RLS (aged 50-65) will be randomly assigned to one of three groups for four weeks (3 sessions/week): Group A (Vibration + Conventional Stretching), Group B (NIR Light + Conventional Stretching), and Group C (Combined Vibration and ","updated":"2025-12-29","first_posted":"2025-12-29","type":"INTERVENTIONAL","ctx":"autres","titre":"Lumière proche infrarouge et vibrations dans le syndrome des jambes sans repos du diabétique"},{"nct":"NCT07262645","title":"Near-infrared Light Therapy Device for Mild-Moderate Alzheimer's Disease (NirsCure-03A)","acronym":null,"status":"RECRUITING","phases":["PHASE3"],"n":320,"start":"2025-12-10","end":"2027-07-22","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Alzheimer s Disease"],"interventions":[{"type":"DEVICE","name":"NirsCure 6000"},{"type":"DEVICE","name":"Sham Device"}],"sponsor":"Danyang Huichuang Medical Equipment Co., Ltd.","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[],"countries":["China"],"sites":[{"facility":"Peking University First Hospital","city":"Beijing","country":"China"},{"facility":"Beijing Friendship Hospital, Capital Medical University","city":"Beijing","country":"China"},{"facility":"Xuanwu Hospital, Capital Medical University","city":"Beijing","country":"China"},{"facility":"Peking University Third Hospital","city":"Beijing","country":"China"},{"facility":"Peking Union Medical College Hospital, Chinese Academy of Medical Sciences","city":"Beijing","country":"China"},{"facility":"Shijiazhuang People's Hospital","city":"Shijiazhuang","country":"China"},{"facility":"Baotou Central Hospital","city":"Baotou","country":"China"},{"facility":"The Second Affiliated Hospital of Soochow University","city":"Suzhou","country":"China"}],"n_sites":23,"outcome":"Alzheimer's Disease Assessment Scale, cognitive subscale 13 (ADAS-Cog13)","summary":"This study is a multicenter, randomized, double-blind, sham-device-controlled clinical trial.\n\nA total of 320 patients with mild to moderate Alzheimer's disease (AD) are planned to be enrolled. Central stratified block randomization will be applied, with stratification based on disease severity (mild vs. moderate) and Aβ-PET subgroup center status (yes vs. no). Participants will be randomly assigned to either the treatment group or control group in a 1:1 ratio. After enrollment, participants will complete the treatment at home during a 52-week double-blind period. The treatment group will receive therapy using a near-infrared light therapy device, while the control group will use sham device. Both investigators and participants will remain blinded to treatment allocation throughout the double-blind period. Participants who complete the 52-week double-blind treatment period may choose to ","updated":"2026-09-22","first_posted":"2025-12-03","type":"INTERVENTIONAL","ctx":"démences","titre":"NirsCure-03A : dispositif proche infrarouge contre sham dans l'Alzheimer léger à modéré"},{"nct":"NCT06443242","title":"Efficacy and Safety of Low-dose Laser Acupuncture on Treating Insomnia Associated With Major Depressive Disorder","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":120,"start":"2025-12-01","end":"2027-08-31","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Major Depressive Disorder","Insomnia"],"interventions":[{"type":"DEVICE","name":"Low-Dose Laser Acupuncture (LLA)"},{"type":"DEVICE","name":"Sham Laser Acupuncture (SLA)"}],"sponsor":"Mohammad Farris Iman Leong Bin Abdullah","sponsor_class":"OTHER","collaborators":["Henan Medical University"],"responsible":{"name":"Mohammad Farris Iman Leong Bin Abdullah","title":"Principal investigator","affiliation":"Universiti Sains Malaysia"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Change in sleep quality from pre-treatment assessed by the Pittsburgh Sleep Quality Index (PSQI) score at immediately post-treatment and 12 weeks post-treatment","summary":"The goal of this randomized controlled trial is to assess the efficacy and safety of low-dose laser acupuncture (LLA) in alleviating insomnia symptoms among patients suffering from major depressive disorder.\n\nThe study seeks to answer the following questions:\n\n1. How effective is LLA in alleviating insomnia symptoms as compare with SLA and control subjects among patients with major depressive disorder across pre-treatment, mid-treatment and post-treatment assessment?\n2. How effective is LLA in alleviating depression symptoms as compare with SLA and control subjects among patients with major depressive disorder across pre-treatment, post-treatment and follow-up assessment?\n3. What role do CORT and 5-HT play in the co-occurrence and progression of insomnia and major depressive disorder, and how does LLA act on these mechanisms to provide relief?\n4. How does the safety and acceptability of ","updated":"2025-09-10","first_posted":"2024-06-05","type":"INTERVENTIONAL","ctx":"humeur","titre":"Laser-acupuncture à faible dose dans l'insomnie de la dépression"},{"nct":"NCT07292506","title":"The Impact of Acupuncture on Biomarkers of Brain Injury and Inflammatory Response in Migraine","acronym":"ACUPMIGRAINE","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":75,"start":"2025-11-03","end":"2026-03-15","allocation":"RANDOMIZED","masking":"NONE","conditions":["Migraine","Migraine Headache","Migraine Headache, With or Without Aura","Migraine in Adults"],"interventions":[{"type":"OTHER","name":"Standard acupuncture"},{"type":"OTHER","name":"Electroacupuncture"},{"type":"OTHER","name":"Laser Acupuncture"}],"sponsor":"University Medical Centre Ljubljana","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Lea Rupert, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Clinical department of anaesthesiology and surgical intensive therapy University Medical Centre Ljubljana"},{"name":"Jasmina Markovic Bozic, MD, Phd, Asist. Prof.","role":"STUDY_CHAIR","affiliation":"Clinical department of anaesthesiology and surgical intensive therapy University Medical Centre Ljubljana"}],"countries":["Slovenia"],"sites":[{"facility":"Clinical department of anaesthesiology and surgical intensive therapy University Medical Centre Ljubljana","city":"Ljubljana","country":"Slovenia"}],"n_sites":1,"outcome":"NRS 3","summary":"Migraine is more than just a headache-it can involve changes in the brain and inflammation. Recent research suggests that acupuncture may help by calming pain signals and reducing inflammation in the body. Scientists are studying whether acupuncture can also lower certain markers in the blood that show brain stress or inflammation. While more research is needed, acupuncture is considered safe and may reduce the number and severity of migraine attacks for many people. Acupuncture has been used for over 40 years in our practice to manage acute and chronic pain, including migraines. When performed by trained physicians, it is safe and typically reduces headache frequency and intensity, as well as nausea and vomiting, lowering the need for pain medication.\n\nInvestigators are exploring three different ways to help manage migraine headaches using gentle stimulation techniques. These include la","updated":"2025-12-18","first_posted":"2025-12-18","type":"INTERVENTIONAL","ctx":"autres","titre":"Acupuncture, électroacupuncture ou laser-acupuncture dans la migraine : biomarqueurs"},{"nct":"NCT06836180","title":"An Exploratory Study of Near-infrared Light Therapy for Mild to Moderate Alzheimer's Disease","acronym":null,"status":"NOT_YET_RECRUITING","phases":["EARLY_PHASE1"],"n":40,"start":"2025-10-30","end":"2030-01-01","allocation":"NA","masking":"NONE","conditions":["Alzheimer Disease"],"interventions":[{"type":"DEVICE","name":"Near infrared light therapy"}],"sponsor":"Xuanwu Hospital, Beijing","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["China"],"sites":[{"facility":"Xuanwu Hospital, Capital Medical University","city":"Beijing","country":"China"}],"n_sites":1,"outcome":"Alzheimer's disease assessment scale-cognitive section(ADAS-Cog)","summary":"This is an exploratory clinical study to evaluate the efficacy and safety of near-infrared light therapeutics in the treatment of mild to moderate Alzheimer's disease.","updated":"2025-09-15","first_posted":"2025-02-20","type":"INTERVENTIONAL","ctx":"démences","titre":"Lumière proche infrarouge dans l'Alzheimer léger à modéré (exploratoire)"},{"nct":"NCT07651787","title":"Using Light Therapy for Mild Cognitive Impairment","acronym":"LTMC","status":"RECRUITING","phases":["NA"],"n":40,"start":"2025-10-01","end":"2026-12-31","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Mild Cognitive Impairment (MCI)","Amyloid Pathology"],"interventions":[{"type":"DEVICE","name":"Active Vielight Neuro RX-Duo device -Active transcranial photobiomodulation"},{"type":"DEVICE","name":"Sham Vielight Neuro RX-Duo device -Sham transcranial photobiomodulation"}],"sponsor":"University of Oklahoma","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Peter Mukli, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Department of Neurosurgery, University of Oklahoma Health Campus, Oklahoma, USA"}],"countries":["United States"],"sites":[{"facility":"University of Oklahoma Health Campus","city":"Oklahoma City","country":"United States"}],"n_sites":1,"outcome":"Change in cortical neurovascular coupling","summary":"The goal of this clinical trial is to test whether transcranial photobiomodulation (tPBM), a non-invasive brain stimulation technique using near-infrared light, can improve brain blood flow regulation (neurovascular coupling) and cognitive function in people with mild cognitive impairment (MCI). The main questions it aims to answer are:\n\n* Does tPBM enhance cognitive function and cerebral hemodynamic responses during memory and finger tapping tasks?\n* Does tPBM reduce oxidative stress, inflammation, and mitigate brain cell damage?\n* Is cognitive improvement linked to amyloid status, greater cerebral hemodynamic response, and lower levels of brain inflammation and oxidative stress? Researchers will compare an active tPBM treatment arm to a sham treatment arm to see if tPBM leads to measurable improvements in brain activity and cognitive function compared to no active stimulation.\n\nPartici","updated":"2026-06-16","first_posted":"2026-06-16","type":"INTERVENTIONAL","ctx":"démences","titre":"Vielight Neuro RX-Duo contre sham dans le trouble cognitif léger"},{"nct":"NCT07204145","title":"Laser Acupuncture for Behavioral and Psychological Symptoms of Dementia","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2025-10-01","end":"2026-01-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Behavioral and Psychological Symptoms of Dementia (BPSD)","Dementia"],"interventions":[{"type":"DEVICE","name":"Laser Acupuncture (808 nm laser pen)"},{"type":"DEVICE","name":"Sham Laser Acupuncture"}],"sponsor":"China Medical University Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yu-Chen Lee","title":"Professor","affiliation":"China Medical University Hospital"},"officials":[{"name":"Yuchen Lee, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Principal Investigator, Department of Acupuncture"}],"countries":["Taiwan"],"sites":[{"facility":"Taoyuan Veteran's Home","city":"Taoyuan City","country":"Taiwan"},{"facility":"China Medical University Hospital","city":"Taichung","country":"Taiwan"}],"n_sites":2,"outcome":"Neuropsychiatric Inventory (NPI) total score","summary":"This study uses a laser acupuncture pen to stimulate specific acupoints, aiming to evaluate its effectiveness in improving behavioral and psychological symptoms of dementia (BPSD).","updated":"2025-10-02","first_posted":"2025-10-02","type":"INTERVENTIONAL","ctx":"démences","titre":"Laser-acupuncture 808 nm contre les symptômes comportementaux de la démence"},{"nct":"NCT07171788","title":"Effects of Low Level Laser Therapy on Wrist Flexors Spasticity and Hand Functions in Patients With Stroke","acronym":"LLL","status":"NOT_YET_RECRUITING","phases":["NA"],"n":40,"start":"2025-09-15","end":"2025-12-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Stroke"],"interventions":[{"type":"OTHER","name":"low level laser therapy"},{"type":"OTHER","name":"selected physical therapy program"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Heba Hassan Amin Mohamed","title":"principle investigator : heba hassan amin mohamed","affiliation":"Cairo University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"spasticity","summary":"this study will be conducted to investigate the effect of low level laser therapy (LLLT) on wrist flexors spasticity and hand functions in patient with stroke","updated":"2025-09-15","first_posted":"2025-09-15","type":"INTERVENTIONAL","ctx":"AVC","titre":"Laser basse énergie, spasticité des fléchisseurs du poignet et main après AVC"},{"nct":"NCT07133893","title":"Transcranial Photobiomodulation in Anxiety Disorders","acronym":null,"status":"RECRUITING","phases":["NA"],"n":280,"start":"2025-09-01","end":"2027-09","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Symptoms of Anxiety"],"interventions":[{"type":"BEHAVIORAL","name":"Attention bias assessment and modification"},{"type":"DEVICE","name":"Transcranial photobiomodulation"}],"sponsor":"Francisco Gonzalez-Lima, PhD","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Francisco Gonzalez-Lima, PhD","title":"Professor; Director, Texas Consortium in Behavioral Neuroscience","affiliation":"University of Texas at Austin"},"officials":[],"countries":["United States"],"sites":[{"facility":"The University of Texas at Austin","city":"Austin","country":"United States"}],"n_sites":1,"outcome":"Composite cognitive score in the dot-probe task","summary":"The investigators have previously shown that safe, non-invasive methods of brain stimulation such as the administration of transcranial infrared light can result in improvements to cognition and emotion. The investigators hypothesize that transcranial photobiomodulation (tPBM) can be used in conjunction with attention bias assessment and modification to reduce anxiety symptoms in individuals with sub-clinical anxiety.","updated":"2026-05-14","first_posted":"2025-08-21","type":"INTERVENTIONAL","ctx":"humeur","titre":"PBM transcrânienne et modification des biais attentionnels dans les troubles anxieux"},{"nct":"NCT06995443","title":"Breast Cancer and Chemobrain : Effects of Photobiomodulation on the Improvement of Perceived Cognitive Impairment","acronym":"REGAIN","status":"RECRUITING","phases":["NA"],"n":200,"start":"2025-06-13","end":"2027-12","allocation":"RANDOMIZED","masking":"NONE","conditions":["Oncology","Support Care","Cognitive Disorders"],"interventions":[{"type":"OTHER","name":"Photobiomodulation"}],"sponsor":"Centre Hospitalier de Valenciennes","sponsor_class":"NETWORK","collaborators":[],"responsible":null,"officials":[],"countries":["France"],"sites":[{"facility":"Centre Hospitalier de Valenciennes","city":"Valenciennes","country":"France"}],"n_sites":1,"outcome":"To compare, among women aged 18 and over who had undergone chemotherapy for breast cancer and had subjective cognitive impairment post-chemotherapy, the rate of those showing improvement in cognitive impairment with or without photobiomodulation (cortica","summary":"Breast cancer is one of the most common cancers in metropolitan France, with over 60,000 new cases in 2023. Mostly a female cancer, it can affect a young population, with around 20% of breast cancers occurring in women under 50. Treatment is mainly based on surgery, chemotherapy, radiotherapy, targeted therapies and hormone therapy. Although chemotherapy is not systematically used, it remains a frequent treatment option. While chemotherapy makes a major contribution to curing cancer, it is also a source of potentially disabling side effects for survivors.\n\nChemotherapy can interfere with the normal functioning of the central nervous system, leading to cognitive impairment. The number of people potentially affected by chemobrain is estimated at several tens of millions worldwide. There is no recommended treatment for people with chemobrain. Several avenues have been explored, with very li","updated":"2026-01-30","first_posted":"2025-05-29","type":"INTERVENTIONAL","ctx":"démences","titre":"Cancer du sein et « chemobrain » : PBM et troubles cognitifs perçus (France)"},{"nct":"NCT06992804","title":"Near-Infrared Light Therapy Combined With Lecanemab for Mild Alzheimer's Disease","acronym":null,"status":"RECRUITING","phases":["EARLY_PHASE1"],"n":20,"start":"2025-05-28","end":"2025-10-15","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Alzheimer Disease"],"interventions":[{"type":"OTHER","name":"NirsCure with Lecanemab"},{"type":"OTHER","name":"sham NirsCure with Lecanemab"},{"type":"OTHER","name":"NirsCure with Lecanemab"}],"sponsor":"Xuanwu Hospital, Beijing","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Yi Tang, MD, PhD","role":"STUDY_CHAIR","affiliation":"Xuanwu Hospital, Beijing"}],"countries":["China"],"sites":[{"facility":"Xuanwu Hospital, Capital Medical University","city":"Beijing","country":"China"}],"n_sites":1,"outcome":"The change from baseline in the Alzheimer's Disease Assessment Scale-Cognitive (ADAS-cog).","summary":"The goal of this study is to explore the efficacy and safety of near-infrared light combined with lecanemab in patients with mild Alzheimer's disease (AD).\n\nThis study will employ a randomized, double-blind, sham-controlled method with an open-label extension phase. This trial contains the core phase and an extension phase. During the core phase, eligible subjects were selected and randomized (experimental group: control group = 1:1). The subjects who entered the experimental group received treatment with a near-infrared light therapy device combined with lecanemab for 16 weeks. The subjects who entered the control group received treatment with a near-infrared light therapy device simulator (sham stimulation) combined with lecanemab for 16 weeks. After completing the core phase, patients from both groups of the core phase are eligible to enter the extension phase. In the extension phase,","updated":"2025-09-09","first_posted":"2025-05-28","type":"INTERVENTIONAL","ctx":"démences","titre":"Lumière proche infrarouge associée au lécanémab dans l'Alzheimer léger"},{"nct":"NCT06584409","title":"Migraines Accepted Laser Acupuncture Compared in Blood Test of MMP2 and CGRP","acronym":null,"status":"RECRUITING","phases":["NA"],"n":60,"start":"2025-04-07","end":"2027-11-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Headache, Migraine"],"interventions":[{"type":"DEVICE","name":"Laser Pen"},{"type":"OTHER","name":"Observation"}],"sponsor":"Taichung Veterans General Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Chi-Hsiang Chou, M.D.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Taichung Veterans General Hospital"},{"name":"Chi Sheng Wang, M.D.","role":"STUDY_DIRECTOR","affiliation":"Taichung Veterans General Hospital"},{"name":"Huan Yun Wu, M.D.","role":"STUDY_DIRECTOR","affiliation":"Taichung Veterans General Hospital"}],"countries":["Taiwan"],"sites":[{"facility":"Taichung Veterans General Hospital","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"cGRP","summary":"Aims:\n\nTo investigate the efficacy of laser-acupuncture for the severity of primary headache and comorbidities, and the Lab data examination.\n\nMethods:\n\nIn this hospital-based prospective single blind randomized sham-controlled study, patients over 18 years old with primary headache will be randomly divided into two treatment arms including laser-acupuncture and sham-controlled group. The expected laser-acupuncture protocol will be bilateral BL2, GB20, EX-HN5, GB8, LI4, LR3 and midline EX-HN3 in totally eight sessions at the first month. In the sham-laser-acupuncture group, patients will receive eight sessions of laser-acupuncture for free after unblinding. We expected to track patients for at least half year. The diagnosis and classification of headache was evaluated using the ICHD-3 criteria. The severity of headache was evaluated using Migraine Disability Assessment (MIDAS) and headac","updated":"2026-09-30","first_posted":"2024-09-04","type":"INTERVENTIONAL","ctx":"autres","titre":"Laser-acupuncture dans la migraine : MMP2 et CGRP"},{"nct":"NCT06916260","title":"Light Therapy Intervention in Individuals With Parkinson's Disease","acronym":null,"status":"RECRUITING","phases":["NA"],"n":20,"start":"2025-04-04","end":"2026-01-29","allocation":"NON_RANDOMIZED","masking":"DOUBLE","conditions":["Parkinson Disease"],"interventions":[{"type":"DEVICE","name":"Red Light (PDT)"},{"type":"DEVICE","name":"Placebo"}],"sponsor":"University of Delaware","sponsor_class":"OTHER","collaborators":["NeuroThera"],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"University of Delaware STAR Tower","city":"Newark","country":"United States"}],"n_sites":1,"outcome":"cognitive symptom improvement","summary":"The study looks to investigate the effects that light therapy delivered to the frontal cortex could have on Parkinson's disease related symptoms ( both cognitive and motor). The therapy is a non invasive technique that deliverers low level wavelength light to the front part of the head for 12 minutes. for this study the therapy will be done 3 times a week for 6 weeks. To measure the potential effects on the therapy in Parkinson symptoms, we will do a set of cognitive and motor test before and after the intervention to measure any changes as well as control for any potential markers such as age, sex, disease level, medication and exercise.","updated":"2025-04-08","first_posted":"2025-04-08","type":"INTERVENTIONAL","ctx":"parkinson","titre":"Lumière rouge frontale dans les symptômes du Parkinson"},{"nct":"NCT07271927","title":"Whole-Body Photobiomodulation for Motor and Cognitive Changes in Parkinson's Disease","acronym":"PBM","status":"RECRUITING","phases":["NA"],"n":15,"start":"2025-02-12","end":"2025-11-30","allocation":"NA","masking":"NONE","conditions":["PARKINSON DISEASE (Disorder)"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"Pusan National University Yangsan Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yong-il Shin","title":"Professor","affiliation":"Pusan National University Yangsan Hospital"},"officials":[],"countries":["South Korea"],"sites":[{"facility":"Pusan National University Yangsan Hospital","city":"Yangsan","country":"South Korea"}],"n_sites":1,"outcome":"UPDRS","summary":"This study aims to exploratorily evaluate the extent of motor and cognitive changes, as well as the safety, resulting from approximately 10 weeks of whole-body photobiomodulation (PBM) therapy (about three sessions per week, once daily, 20 minutes per session) in patients with Parkinson's disease.","updated":"2025-12-09","first_posted":"2025-12-09","type":"INTERVENTIONAL","ctx":"parkinson","titre":"PBM corps entier, troubles moteurs et cognitifs du Parkinson"},{"nct":"NCT06203938","title":"Autism Research Project With Non-Invasive Near-Infrared Light Stimulation","acronym":null,"status":"RECRUITING","phases":["NA"],"n":280,"start":"2025-01-13","end":"2027-12","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Autism Spectrum Disorder"],"interventions":[{"type":"DEVICE","name":"Transcranial infrared light stimulation"},{"type":"DEVICE","name":"Sham"}],"sponsor":"Francisco Gonzalez-Lima, PhD","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Francisco Gonzalez-Lima, PhD","title":"Professor","affiliation":"University of Texas at Austin"},"officials":[{"name":"Sarah W Diaz, PhD","role":"STUDY_DIRECTOR","affiliation":"University of Texas at Austin"}],"countries":["United States"],"sites":[{"facility":"Seay Psychology Building, Room 3.304","city":"Austin","country":"United States"}],"n_sites":1,"outcome":"Autism spectrum questionnaires","summary":"The investigators have previously shown that the administration of low-level infrared light is a safe and non-invasive procedure which improves cognition and emotion, as well as enhances brain metabolic activity. Based on previous studies, the investigators hypothesize that this methodology, called low-level light therapy or photobiomodulation, could be used to improve behavioral symptoms in individuals with autism spectrum disorder (ASD).","updated":"2026-06-22","first_posted":"2024-01-12","type":"INTERVENTIONAL","ctx":"neurodev","titre":"Stimulation transcrânienne proche infrarouge contre sham dans l'autisme"},{"nct":"NCT06618807","title":"Infrared Light for Memory Loss in Mild Cognitive Impairment (MCI)","acronym":"PBMCI-Prime","status":"RECRUITING","phases":["NA"],"n":60,"start":"2025-01-10","end":"2027-08-01","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Mild Cognitive Impairment (MCI) Due to Alzheimer's Disease"],"interventions":[{"type":"DEVICE","name":"Active tPBM device"},{"type":"DEVICE","name":"Sham device"}],"sponsor":"Unity Health Toronto","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Corinne Fischer","title":"staff psychiatrist","affiliation":"Unity Health Toronto"},"officials":[],"countries":["Canada"],"sites":[{"facility":"St. Michael's Hospital, Unity Health Toronto","city":"Toronto","country":"Canada"}],"n_sites":1,"outcome":"Cognition","summary":"Mild cognitive impairment (MCI) is a transitional risk state that occurs between the normal aging process and Alzheimer's dementia (AD). On average 32% of patients with MCI will progress to dementia, 62% will stay stable, and about 6% will return to normal cognition at subsequent visits.\n\nCurrent treatment for MCI includes cholinesterase inhibitors (donepezil, galantamine and rivastigmine), and NMDA receptor antagonists (memantine) which delay or slow the worsening of symptoms and treat cognitive symptoms (memory loss, confusion, and problems with thinking and reasoning). Despite currently ongoing drug studies and modest clinical benefits of currently approved drug treatments, there continues to remain a need for treatments for long term symptomatic improvement of MCI with fewer and less severe side effects.\n\nPhotobiomodulation (PBM) therapy also called low-level laser (or light) therapy","updated":"2025-12-05","first_posted":"2024-10-01","type":"INTERVENTIONAL","ctx":"démences","titre":"Lumière infrarouge contre la perte de mémoire du trouble cognitif léger"},{"nct":"NCT07835399","title":"Efficacy and Safety of Photobiomodulation Therapy in Patients With Mild Cognitive Impairment and Mild Alzheimer's Disease","acronym":"PBMT in MCI","status":"RECRUITING","phases":["NA"],"n":20,"start":"2024-06-15","end":"2026-12-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Mild Cognitive Impairment (MCI)","Mild Alzheimer Disease","Dementia"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"Jun Xu","sponsor_class":"OTHER","collaborators":["Shanghai Jinze Biotechnology Co. Ltd."],"responsible":{"name":"Jun Xu","title":"Chief Physician, Professor, Department of Cognitive Disorders","affiliation":"Beijing Tiantan Hospital"},"officials":[],"countries":["China"],"sites":[{"facility":"Department of Cognitive Disorders, Beijing Tiantan Hospital, Capital Medical University","city":"Beijing","country":"China"}],"n_sites":1,"outcome":"Mini-Mental State Examination","summary":"The goal of this clinical trial is to learn if photobiomodulation therapy (PBMT) can help treat mild cognitive impairment and mild Alzheimer's disease in adults aged 50 to 85 years. It will also learn about the safety of PBMT. The main questions it aims to answer are:\n\nDoes PBMT improve cognitive function in adults with mild cognitive impairment or mild Alzheimer's disease? What medical problems do participants have when using PBMT? Researchers will compare an active PBMT device to a sham (look-alike) device that delivers no active light therapy to see if PBMT improves cognitive function.\n\nParticipants will:\n\nUse a transcranial near-infrared light therapy device (or a matching sham device) once a day for 20 minutes, 5 days a week, for 6 months Visit the clinic for cognitive, mood, sleep, and daily-function assessments at the start of the study, at Month 3, and at Month 6 Have brain MRI s","updated":"2026-09-22","first_posted":"2026-09-22","type":"INTERVENTIONAL","ctx":"démences","titre":"PBM dans le trouble cognitif léger et l'Alzheimer léger : efficacité et sécurité"},{"nct":"NCT06239818","title":"Assessing the Effects of Photobiomodulation on Clinical Recovery From Concussion in Adolescents","acronym":null,"status":"RECRUITING","phases":["NA"],"n":30,"start":"2024-04-17","end":"2026-04-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Sports-related Concussion"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation therapy (PBMt)"},{"type":"OTHER","name":"Standard of Care"}],"sponsor":"The University of Texas Health Science Center, Houston","sponsor_class":"OTHER","collaborators":["TIRR/Mission Connect"],"responsible":{"name":"Summer Ott, Psy.D.","title":"Associate Professor","affiliation":"The University of Texas Health Science Center, Houston"},"officials":[{"name":"Summer Ott, PsyD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"The University of Texas Health Science Center, Houston"}],"countries":["United States"],"sites":[{"facility":"The University of Texas Health Science Center at Houston","city":"Houston","country":"United States"}],"n_sites":1,"outcome":"Change in depression as assessed by the Neuro-QoL Short Form v1.1 - Pediatric Depression scale","summary":"The purpose of this study is to compare effects of Photobiomodulation therapy (PBMt) to standard of care in adolescent athletes at risk for delayed recovery from subacute sports concussion, to substantiate the impact of subacute PBMt over time on functional and structural connectivity of the brain using advanced MRI sequences and to correlate the psychological and behavioral outcomes to neuroimaging findings","updated":"2025-07-20","first_posted":"2024-02-02","type":"INTERVENTIONAL","ctx":"TC","titre":"PBM et récupération après commotion cérébrale de l'adolescent"},{"nct":"NCT07287527","title":"Effects of Photobiomodularion on Brain Connectivity and Cognitive Function in Cognitive Impairment","acronym":"PBM-CogConnect","status":"RECRUITING","phases":["NA"],"n":60,"start":"2024-03-30","end":"2025-12-31","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["AMCI - Amnestic Mild Cognitive Impairment"],"interventions":[{"type":"DEVICE","name":"Active transcranial Photobiomodulation"},{"type":"DEVICE","name":"sham transcranial Photobiomodulation"},{"type":"BEHAVIORAL","name":"Cognitive Rehabilitation"}],"sponsor":"Uskudar University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Baris Metin","title":"Prof. Dr.","affiliation":"Uskudar University"},"officials":[{"name":"Baris Metin, Prof. Dr.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Uskudar University"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"NPIstanbul Brain Hospital","city":"Istanbul","country":"Turkey (Türkiye)"},{"facility":"Uskudar University, Faculty of Medicine","city":"Istnabul","country":"Turkey (Türkiye)"}],"n_sites":2,"outcome":"Change in Default Mode Network (DMN) Functional Connectivity Measured by Resting-State fMRI","summary":"The goal of this clinical trial is to learn if transcranial photobiomodulation (t-PBM), a light-based brain therapy, can help improve memory and cognitive skills in older adults with amnestic mild cognitive impairment (aMCI). This condition involves memory problems that are greater than normal aging and may increase the chance of developing Alzheimer's disease.\n\nThe main questions this study aims to answer are:\n\n1. Does t-PBM, when used together with cognitive training, improve memory and cognitive skills?\n2. Does t-PBM change how certain brain areas communicate with each other, especially in the default mode network (DMN)?\n\nResearchers will compare:\n\nt-PBM plus cognitive training to sham (inactive) t-PBM plus the same cognitive training to see if the active light treatment leads to better cognitive improvement and healthier brain activity.\n\nParticipants will:\n\n* Provide a blood sample s","updated":"2025-12-17","first_posted":"2025-12-17","type":"INTERVENTIONAL","ctx":"démences","titre":"PBM transcrânienne, connectivité cérébrale et cognition"},{"nct":"NCT06160908","title":"Transcranial Near-infrared Light Therapy for Mild-Moderate Alzheimer's Disease (NIR4AD)","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":38,"start":"2023-12-12","end":"2024-08-25","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Alzheimer Disease"],"interventions":[{"type":"DEVICE","name":"NirsCure"},{"type":"DEVICE","name":"sham NirsCure"},{"type":"DEVICE","name":"NirsCure"}],"sponsor":"Xuanwu Hospital, Beijing","sponsor_class":"OTHER","collaborators":["Danyang Huichuang Medical Equipment Co., Ltd."],"responsible":null,"officials":[{"name":"Yi Tang, MD., PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Xuanwu Hospital, Beijing"}],"countries":["China"],"sites":[{"facility":"Xuanwu Hospital, Capital Medical University","city":"Beijing","country":"China"}],"n_sites":1,"outcome":"change from baseline on the Alzheimer's disease assessment scale-cognitive section(ADAS-Cog)","summary":"The goal of this study is to explore the efficacy and safety of Near-infrared light Photobiomodulation in patients with mild-moderate Alzheimer's disease(AD).\n\nThis study will employ a randomized, double-blind, sham-controlled approach. This trial contains core phase and extension phase. In the core phase, qualified subjects were selected and randomized (experimental group: control group=1:1). The subjects who entered the experimental group received 30 minutes of near-infrared light therapy once a day, 6 times a week, for 16 weeks of continuous treatment. The subjects who entered the control group received 30 minutes of non-near-infrared light irradiation once a day (false treatment), 6 times a week, for 16 weeks. After finishing the core phase, patients from both groups of the core phase are eligible to enter the extension phase. In the extension phase, all the participants receive acti","updated":"2026-04-13","first_posted":"2023-12-07","type":"INTERVENTIONAL","ctx":"démences","titre":"NIR4AD : lumière proche infrarouge transcrânienne dans l'Alzheimer léger à modéré"},{"nct":"NCT06006637","title":"Integrated Platform for Measuring and Reducing Symptoms of Autism Spectrum Disorder","acronym":"IPMR ASD","status":"RECRUITING","phases":["NA"],"n":80,"start":"2023-10-17","end":"2026-08-15","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Autism Spectrum Disorder"],"interventions":[{"type":"DEVICE","name":"Cognilum TM: Light Treatment Condition"}],"sponsor":"State University of New York - Upstate Medical University","sponsor_class":"OTHER","collaborators":["JelikaLite LLC","Mt. Sinai School of Medicine, New York, New York","MetroEHS"],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"Mt. Sinai Medical Center","city":"New York","country":"United States"},{"facility":"Golisano Center for Special Needs","city":"Syracuse","country":"United States"}],"n_sites":2,"outcome":"Childhood Autism Rating Scale, Second edition","summary":"This study will consist of a randomized, double-blind, sham-controlled clinical trial at SUNY Upstate Medical University and Mt. Sinai Medical Center with 80 autistic children evaluating the effects of transcranial photobiomodulation (tPBM) on multiple clinically validated scales.","updated":"2025-10-14","first_posted":"2023-08-23","type":"INTERVENTIONAL","ctx":"neurodev","titre":"PBM transcrânienne contre sham chez l'enfant autiste"},{"nct":"NCT05926011","title":"Efficacy of RGn600 in Patients With Mild-to-moderate Alzheimer's Disease","acronym":"LIGHT4LIFE","status":"RECRUITING","phases":["NA"],"n":108,"start":"2023-07-24","end":"2027-06","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Alzheimer Disease"],"interventions":[{"type":"DEVICE","name":"RGn600"},{"type":"DEVICE","name":"RGn600 Sham"}],"sponsor":"REGEnLIFE SAS","sponsor_class":"INDUSTRY","collaborators":["RCTs","University Hospital, Toulouse"],"responsible":null,"officials":[{"name":"Guillaume BLIVET","role":"STUDY_DIRECTOR","affiliation":"REGEnLIFE SAS"},{"name":"Jacques TOUCHON","role":"STUDY_CHAIR","affiliation":"Montpellier University"},{"name":"Julien DELRIEU","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Toulouse University Hospital Gerontopole"}],"countries":["France"],"sites":[{"facility":"CHIC Castres Mazamet Site Autan","city":"Castres","country":"France"},{"facility":"CH Lavaur","city":"Lavaur","country":"France"},{"facility":"Hôpital Lariboisière","city":"Paris","country":"France"},{"facility":"Hôpital Broca","city":"Paris","country":"France"},{"facility":"Biofortis","city":"Saint-Herblain","country":"France"},{"facility":"Toulouse University Hospital Gerontopole","city":"Toulouse","country":"France"},{"facility":"Hôpital des Charpennes - HCL","city":"Villeurbanne","country":"France"}],"n_sites":7,"outcome":"Evolution of patient's cognition between Day 0 and Week 26 as measured with the AD Assessment Scale-cognitive subscale (ADAS-cog) score","summary":"This is a controlled investigation, with randomization of the patients, which aims at demonstrating the efficacy of device RGn600 in treating patients with mild-to-moderate Alzheimer's disease (AD). RGn600 is a non-invasive medical device which is applied on the head (helmet) and on the abdomen (abdominal belt). It combines 2 technologies:\n\n* PhotoBioModulation (PBM), which involves exposure to light from the red to near-infrared wavelengths using lasers and Light Emitting Diodes (LEDs)\n* Static Magnetic Stimulation (SMS), which consists in the application of a static magnetic field.\n\nConsidering previous investigations, this innovative technology could reduce inflammation on the brain-gut axis, implicated in the development of Alzheimer's disease.","updated":"2026-08-21","first_posted":"2023-07-03","type":"INTERVENTIONAL","ctx":"démences","titre":"RGn600 contre sham dans l'Alzheimer léger à modéré (France)"},{"nct":"NCT05573074","title":"Transcranial Near Infrared Radiation and Cerebral Blood Flow in Depression - R33","acronym":"TRIADE-R33","status":"RECRUITING","phases":["NA"],"n":120,"start":"2023-04-01","end":"2026-04-30","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Major Depressive Disorder"],"interventions":[{"type":"DEVICE","name":"Transcranial Photobiomodulator"},{"type":"DEVICE","name":"Sham"}],"sponsor":"NYU Langone Health","sponsor_class":"OTHER","collaborators":["National Institutes of Health (NIH)"],"responsible":null,"officials":[{"name":"Dan Iosifescu, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"NYU Langone Health"}],"countries":["United States"],"sites":[{"facility":"Harvard Medical School","city":"Boston","country":"United States"},{"facility":"NYU Langone Health","city":"New York","country":"United States"},{"facility":"Nathan Kline Institute for Psychiatric Research","city":"Orangeburg","country":"United States"}],"n_sites":3,"outcome":"Percent change of cerebral blood flow (CBF)","summary":"The purpose of this research study is to determine if application of near infrared energy to the forehead can change blood flow in the brains of people with depression. Near infrared energy is like light but is not visible to the human eye.","updated":"2026-02-05","first_posted":"2022-10-10","type":"INTERVENTIONAL","ctx":"humeur","titre":"Lumière proche infrarouge transcrânienne et débit sanguin cérébral dans la dépression"},{"nct":"NCT05802680","title":"Neurocognitive Effects of Non-Invasive Near-Infrared Light Stimulation","acronym":null,"status":"RECRUITING","phases":["NA"],"n":500,"start":"2022-02-09","end":"2026-12-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Attention Deficit Hyperactivity Disorder","Attention Difficulties","Attention Deficit","Cognitive Deficit","Wellness"],"interventions":[{"type":"DEVICE","name":"Transcranial photobiomodulation"},{"type":"DEVICE","name":"Sham transcranial photobiomodulation"}],"sponsor":"Francisco Gonzalez-Lima, PhD","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Francisco Gonzalez-Lima, PhD","title":"Professor","affiliation":"University of Texas at Austin"},"officials":[{"name":"Douglas W Barrett, Ph.D.","role":"STUDY_DIRECTOR","affiliation":"University of Texas at Austin"}],"countries":["United States"],"sites":[{"facility":"The University of Texas at Austin","city":"Austin","country":"United States"}],"n_sites":1,"outcome":"Continuous Performance Task","summary":"Inattentiveness and impulsivity in healthy adults and individuals with attention deficit hyperactivity disorder (ADHD) diminish these individuals' quality of life. Cortical hypometabolism has been hypothesized to contribute to inattentiveness in ADHD. Transcranial photobiomodulation (tPBM) is a safe and non-invasive modality for activation of the prefrontal cortex. tPBM in healthy adults has been shown to augment brain oxygenation, cognition, and mood. The cognition-enhancing effect of tPBM on sustained attention in adults with ADHD remains unstudied. The investigators will evaluate whether tPBM administration to adults with and without ADHD can improve their attention. Each participant will be screened for eighteen criteria based on the Diagnostic and Statistical Manual (DSM-IV, text revised), using the validated instrument Adult ADHD Self-Report Scale (ASRS-v1.1). Blinded participants ","updated":"2026-06-22","first_posted":"2023-04-06","type":"INTERVENTIONAL","ctx":"démences","titre":"Effets neurocognitifs de la stimulation proche infrarouge transcrânienne"},{"nct":"NCT06219694","title":"Laser Acupuncture for Chronic Migraine","acronym":"LAFCM","status":"RECRUITING","phases":["NA"],"n":60,"start":"2022-01-01","end":"2022-05-04","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Chronic Migraine"],"interventions":[{"type":"DEVICE","name":"Laser Acupuncture"},{"type":"DEVICE","name":"Sham"}],"sponsor":"Taichung Veterans General Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Yuan-Chen Liu, M.D","role":"STUDY_DIRECTOR","affiliation":"Taichung Veterans General Hospital"},{"name":"Ching-Chun Chung, M.D","role":"STUDY_DIRECTOR","affiliation":"Taichung Veterans General Hospital"}],"countries":["Taiwan"],"sites":[{"facility":"Taichung Veterans General Hospital","city":"Taichung","country":"Taiwan"}],"n_sites":1,"outcome":"monthly migraine days","summary":"A single-blind randomized controlled trial was conducted from October 2024 to May 2025. Chronic migraine patients were randomly assigned in a 1:1 ratio to receive either Laser acupuncture or sham treatment. The co-primary outcomes were changes in monthly migraine days (MMD) and acute headache medications usage days per month from baseline, and Hospital Anxiety and Depression Scale (HADS), and Beck's Depression Inventory(BDI) evaluation. Evaluations were taken at baseline and each follow-up point.\n\nAfter \\>6 months follow up as washing out time, the sham group received complementary laser acupuncture treatment and follow up for another 3 months, compared the Headache related parameters (onset, duration, pain scale, current medication for headache, menstrual cycle).","updated":"2025-11-20","first_posted":"2024-01-23","type":"INTERVENTIONAL","ctx":"autres","titre":"Laser-acupuncture contre sham dans la migraine chronique"},{"nct":"NCT04261569","title":"Clinical Trial for Near Infrared Endoventricular Illumination for Neuroprotection in Very Early Cases of Parkinson's Disease (Ev-NIRT)","acronym":"Ev-NIRT","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":14,"start":"2020-12-14","end":"2029-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Very Early Stage of Parkinson's Disease"],"interventions":[{"type":"DEVICE","name":"Ev-NIRT"}],"sponsor":"University Hospital, Grenoble","sponsor_class":"OTHER","collaborators":["Commissariat A L'energie Atomique"],"responsible":null,"officials":[{"name":"Stephan CHABARDES, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University Hospital, Grenoble"}],"countries":["France"],"sites":[{"facility":"CLINATEC","city":"Grenoble","country":"France"}],"n_sites":1,"outcome":"Incidence of Ev-NIRT Treatment on Emergent Adverse Events (Tolerance) after surgical intervention and NIR illumination following the implantation of the Ev-NIRT medical device","summary":"Parkinson's disease has only pharmacological (essentially dopaminergic) and surgical treatment (essentially high-frequency deep brain stimulation), that are symptomatically effective. none of them is curative, and has the ability to slow down the disease and to protect dopaminergic neurons from death by neurodegeneration. Experimental results, based on preclinical studies, suggest that brain illumination in the Near-InfraRed (NIR) range is likely to slow down this neurodegenerative process.\n\nThus, a medical device system (called Ev-NIRT) has been developed for 670 nm intracerebral illumination of the substantia nigra pars compacta (SNpc), and is planned to be tested for the treatment of Parkinson's disease.\n\nIn this pilot study the investigators will evaluate the feasibility and tolerance of surgery and brain illumination thanks to the Ev-NIRT medical device, in a group of 7 de novo Park","updated":"2025-04-01","first_posted":"2020-02-10","type":"INTERVENTIONAL","ctx":"parkinson","titre":"Illumination proche infrarouge intraventriculaire pour la neuroprotection du Parkinson débutant (France)"},{"nct":"NCT03750409","title":"Assessing Feasibility of Prolonged Repetitive Near Infrared Light Stimulation in Early to Mid-Stage Dementia","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":100,"start":"2018-10-15","end":"2019-08-27","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Mild to Moderate Dementia"],"interventions":[{"type":"DEVICE","name":"Helmet"}],"sponsor":"Baylor Research Institute","sponsor_class":"OTHER","collaborators":["Quietmind Foundation"],"responsible":null,"officials":[{"name":"Jason H Huang, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Baylor Scott and White Healthcare"},{"name":"Marvin H Berman, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Quiet Mind Foundation"}],"countries":["United States"],"sites":[{"facility":"Quietmind Foundation","city":"Elkins Park","country":"United States"},{"facility":"Baylor Scott and White Medical Center, Temple","city":"Temple","country":"United States"}],"n_sites":2,"outcome":"Memory Score","summary":"This study will gather data to see if infrared and near infrared light frequency can increase the activity of brain cells and provide support for the cell's ability to repair and protect themselves against further damage.","updated":"2026-02-11","first_posted":"2018-11-23","type":"INTERVENTIONAL","ctx":"démences","titre":"Casque proche infrarouge prolongé dans la démence débutante à modérée"}],"musculo-squelettique":[{"nct":"NCT07895862","title":"Acute Effects of High-Intensity Laser Therapy on Pain, Muscle Stiffness, and Grip Strength in Healthy Adults","acronym":"HILT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":30,"start":"2026-12-01","end":"2027-02-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Exercise-Induced Muscle Fatigue","Fatigue Recovery","Health Adult Subjects","Healthy Adult"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT) and sham HILT"}],"sponsor":"University of Primorska","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Matej Voglar","title":"Associate Professor","affiliation":"University of Primorska"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Handgrip Strength","summary":"The goal of this clinical trial is to learn whether high-intensity laser therapy applied before exercise reduces the loss of handgrip strength, muscle stiffness, and pain after a tiring forearm exercise in healthy adults. This therapy delivers laser light through the skin to the underlying tissues.\n\nThe main questions this study aims to answer are:\n\nDoes laser therapy reduce the loss of handgrip strength after exercise compared with placebo treatment?\n\nDoes laser therapy reduce the increase in forearm muscle stiffness after exercise?\n\nDoes laser therapy reduce pain after exercise?\n\nResearchers will compare active laser therapy with placebo laser treatment to assess whether the active treatment affects the muscles' response to exercise. Each participant will receive both treatments on separate visits. The order of treatments will be assigned by chance.\n\nParticipants will attend two labora","updated":"2026-11-05","first_posted":"2026-10-26","type":"INTERVENTIONAL","ctx":"muscle","titre":"Effets aigus du laser haute intensité sur la douleur, la raideur et la force chez le sujet sain"},{"nct":"NCT07918157","title":"Laser Therapy Versus Transcutaneous Electical Nerve Stimulation at Hemiplegic Shoulder Pain","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-11-15","end":"2028-09-15","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Hemiplegic Shoulder Pain"],"interventions":[{"type":"OTHER","name":"Laser therapy"},{"type":"OTHER","name":"Transcutaneus electirical nerve stimulation"},{"type":"OTHER","name":"control"}],"sponsor":"Hitit University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Onur Öksüz","title":"Principal Investigator","affiliation":"Hitit University"},"officials":[{"name":"Pınar Ö Başaran","role":"STUDY_CHAIR","affiliation":"Hitit Univercity"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Hitit Univercity","city":"Çorum","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Pain Level","summary":"This study aimed to investigate whether laser and Transcutaneous Electirical Nerve Stimulationapplied in addition to conventional physical therapy exercises in hemiplegic shoulder pain seen in patients with stroke provides an additional contribution to pain, range of motion, spasticity, upper extremity functions and whether the two treatment types are superior to each other.","updated":"2026-11-05","first_posted":"2026-11-05","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser ou TENS dans l'épaule douloureuse de l'hémiplégique"},{"nct":"NCT07903142","title":"Comparison of High-Intensity and Conventional Physical Therapy in Musculoskeletal Disorders","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-10-15","end":"2027-06-30","allocation":"RANDOMIZED","masking":"NONE","conditions":["Low Back Pain","Radicular Syndrome","Sacroiliac Joint Dysfunction","Shoulder Impingement Syndrome","Rotator Cuff Tendinopathy","Shoulder Osteoarthritis"],"interventions":[{"type":"DEVICE","name":"Repetitive Peripheral Magnetic Stimulation (rPMS)"},{"type":"DEVICE","name":"High-Intensity Laser Therapy (HIL)"},{"type":"DEVICE","name":"Extracorporeal Shockwave Therapy (ESWT)"},{"type":"DEVICE","name":"Pulsed Electromagnetic Field Therapy (PEMF)"},{"type":"DEVICE","name":"Therapeutic Ultrasound (USN)"},{"type":"DEVICE","name":"Electrotherapy (Medium-Frequency Currents)"}],"sponsor":"BTL Industries Ltd.","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[],"countries":["Czechia"],"sites":[{"facility":"Faculty of Physical Education and Sport, Charles University","city":"Prague","country":"Czechia"}],"n_sites":1,"outcome":"Change in Pain Intensity (VAS)","summary":"This pilot randomized controlled trial aims to compare the clinical effectiveness of advanced high-intensity physical therapy modalities with conventional physical therapy in patients suffering from musculoskeletal disorders. The study focuses on three anatomical areas: lower back, shoulder, and knee. Participants will be randomized into two arms and will undergo 5 therapeutic sessions.","updated":"2026-10-29","first_posted":"2026-10-29","type":"INTERVENTIONAL","ctx":"tendon","titre":"Laser haute intensité, stimulation magnétique et ondes de choc dans les troubles musculo-squelettiques"},{"nct":"NCT07771296","title":"Machine Learning for Evaluating and Diagnosing Temporomandibular Disorders","acronym":null,"status":"RECRUITING","phases":["NA"],"n":180,"start":"2026-10-09","end":"2027-07-25","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Temporomandibular Disorders (TMD)","TMJ Disorder","TMJ Pain"],"interventions":[{"type":"DEVICE","name":"Low-Level Laser Acupuncture"},{"type":"BEHAVIORAL","name":"Proprioceptive Training"},{"type":"DEVICE","name":"Stabilization Splint Treatment"}],"sponsor":"En Chu Kong Hospital","sponsor_class":"OTHER","collaborators":["National Yang Ming Chiao Tung University"],"responsible":{"name":"Ting-Yu Huang, D.D.S.","title":"Attending Physician, Department of Oral and Maxillofacial Surgery","affiliation":"En Chu Kong Hospital"},"officials":[{"name":"Ching-Po Lin, PhD","role":"STUDY_DIRECTOR","affiliation":"Institute of Neuroscience, Brain Research Center, National Yang Ming Chiao Tung University, Taipei, Taiwan. Department of Education and Research, Taipei City Hospital, Taipei, Taiwan."},{"name":"Ching-Mao Chang, MD, PhD","role":"STUDY_DIRECTOR","affiliation":"Center for Traditional Medicine, Taipei Veterans General Hospital, Taipei, Taiwan. Institute of Traditional Medicine, and Schools of Chinese Medicine, College of Medicine, National Yang Ming Chiao Tung University, Taipei, Taiwan."}],"countries":["Taiwan"],"sites":[{"facility":"En Chu Kong Hospital","city":"New Taipei City","country":"Taiwan"}],"n_sites":1,"outcome":"Tenderness of Masticatory Muscles and Periarticular Temporomandibular Joint Pain","summary":"This study aims to improve clinical efficiency and effectiveness in treating Temporomandibular Disorders (TMD). The researchers will integrate machine learning technology with clinical examination data, CBCT, and MRI to identify the core underlying issues of each patient. Based on this precise, AI-assisted diagnosis, the study will implement a tailored treatment framework. The final goal is to develop predictive algorithms that can determine MRI necessity while ensuring that clinical interventions are highly targeted, efficient, and successful.","updated":"2026-10-13","first_posted":"2026-08-18","type":"INTERVENTIONAL","ctx":"ATM","titre":"Laser-acupuncture, proprioception ou gouttière dans les DTM (apprentissage automatique)"},{"nct":"NCT07826117","title":"Laser Acupuncture Versus Traditional Acupuncture for Chronic Low Back Pain","acronym":"LATLBP","status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-09-15","end":"2027-09-15","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Non-specific Low Back Pain","Acupuncture","Laser Acupuncture"],"interventions":[{"type":"DEVICE","name":"Laser Acupuncture"},{"type":"OTHER","name":"Traditional Acupuncture"}],"sponsor":"China Medical University Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yu-Chen Lee","title":"Director of Division of Acupunture","affiliation":"China Medical University Hospital"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Fingertip-to-floor distance","summary":"Chronic nonspecific low back pain is a common condition that may cause persistent pain and limitations in daily activities. This study aims to compare the therapeutic effects of traditional acupuncture and laser acupuncture in patients with chronic nonspecific low back pain, focusing on pain, functional disability, and flexibility.\n\nApproximately 60 participants aged 20-60 years with low back pain between the 12th rib and gluteal fold lasting at least three months will be recruited. Participants must have a Numeric Pain Rating Scale (NPRS) score of at least 4 and meet the study eligibility criteria. Individuals with conditions such as sciatica, neurological disease, spinal tumor, osteoporosis, lumbar spinal stenosis, lumbar spondylolisthesis, ankylosing spondylitis, piriformis syndrome, recent vertebral fracture or lumbar surgery, spinal infection, coagulation disorders, anticoagulant us","updated":"2026-09-23","first_posted":"2026-09-17","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser-acupuncture ou acupuncture traditionnelle dans la lombalgie chronique"},{"nct":"NCT07461363","title":"Efficacy of Low-Dose Laser Acupuncture for Low Back Pain","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":80,"start":"2026-09-01","end":"2028-02-15","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Chronic Low Back Pain"],"interventions":[{"type":"DEVICE","name":"Low-Dose Laser Acupuncture"},{"type":"DEVICE","name":"Sham Laser Acupuncture"}],"sponsor":"Mun Fei Yam","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mun Fei Yam","title":"Principal Investigator","affiliation":"Universiti Sains Malaysia"},"officials":[],"countries":["China"],"sites":[{"facility":"The First Affiliated Hospital of Xinxiang Medical University","city":"Xinxiang","country":"China"}],"n_sites":1,"outcome":"Pain intensity (VAS)","summary":"This study will evaluate whether low-dose laser acupuncture can reduce pain and improve daily function in adults with chronic low back pain. The trial is a double-blinded, randomized, two-arm, parallel, multi-centred study.","updated":"2026-08-11","first_posted":"2026-03-10","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser-acupuncture à faible dose contre sham dans la lombalgie"},{"nct":"NCT07568288","title":"The Effectiveness of High-intensity Laser Therapy After Arthroscopic Shoulder Rotator Cuff Repair.","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":46,"start":"2026-09","end":"2028-11","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Rotator Cuff Tears"],"interventions":[{"type":"DEVICE","name":"High intensity laser therapy"},{"type":"OTHER","name":"Sham laser therapy"}],"sponsor":"Istituto Ortopedico Rizzoli","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Italy"],"sites":[{"facility":"Istituto Ortopedico Rizzoli","city":"Bologna","country":"Italy"}],"n_sites":1,"outcome":"Visual Analogue Scale","summary":"This randomized controlled trial aims to evaluate the effectiveness of high-intensity laser therapy (HILT) as an adjunct to conventional rehabilitation in patients undergoing arthroscopic rotator cuff repair.\n\nDespite surgical repair, patients frequently experience postoperative pain, limited range of motion, and delayed functional recovery. Conventional physiotherapy represents the standard of care; however, additional strategies may be needed to optimize outcomes. High-intensity laser therapy has been proposed as a non-invasive intervention with potential analgesic and anti-inflammatory effects, but its effectiveness in the postoperative setting remains unclear.\n\nParticipants will be randomly allocated to one of two groups: an experimental group receiving HILT in addition to conventional physiotherapy, and a control group receiving sham laser therapy combined with the same rehabilitati","updated":"2026-05-05","first_posted":"2026-05-05","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser haute intensité après réparation arthroscopique de la coiffe des rotateurs"},{"nct":"NCT07079969","title":"Effects of Photobiomodulation on Inflammation and Chronic Pain in Knee Osteoarthritis (EPIC-KO)","acronym":"EPIC-KO","status":"NOT_YET_RECRUITING","phases":["NA"],"n":30,"start":"2026-09","end":"2027-09","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Chronic Knee Pain"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation therapy (PBM) device"},{"type":"DEVICE","name":"Sham PBM device"}],"sponsor":"University of Florida","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"University of Florida","city":"Gainesville","country":"United States"}],"n_sites":1,"outcome":"Change in Knee Pain Intensity (Numeric Rating Scale)","summary":"This study aims to determine analgesic and anti-inflammatory effects of dual-wavelength PBM in people with symptomatic knee OA.","updated":"2026-08-20","first_posted":"2025-07-23","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Essai EPIC-KO : PBM, inflammation et douleur chronique dans la gonarthrose"},{"nct":"NCT07800338","title":"Evaluation Of The Effect Of Low-Level Laser Therapy On Masseter Muscle Versus Therapeutic Ultrasound On Patients With Myofascial Pain Disorder : A Randomized Clinical Trial","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":36,"start":"2026-09","end":"2027-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["TMJ"],"interventions":[{"type":"DEVICE","name":"Evaluation Of The Effect Of Low-Level Laser Therapy On Masseter Muscle Versus therapeutic Ultrasound On Patients With Myofascial Pain Disorder"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"mohamed mostafa","title":"dentist","affiliation":"Cairo University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"pain","summary":"Myofascial pain dysfunction (MPD) is one of the most common causes of chronic orofacial pain, primarily affecting the masticatory muscles such as the masseter and temporalis. It leads to facial pain, muscle tenderness, and restricted mouth opening, significantly impacting patients' quality of life and daily function.\n\nDespite the wide range of conservative treatment modalities-such as medications, splint therapy, and physiotherapy-there is still no universally accepted approach that provides consistent and long-lasting relief.\n\nLow-level laser therapy (LLLT) and therapeutic ultrasound (US) are two non-invasive physical modalities frequently used in dentistry for pain control and tissue healing. Each has shown promising outcomes individually.\n\nAzizi et al. (2007) demonstrated that LLLT at 780 nm can significantly reduce pain and tenderness for up to three months, while Khairy (2018) repor","updated":"2026-09-02","first_posted":"2026-09-02","type":"INTERVENTIONAL","ctx":"ATM","titre":"Laser basse énergie sur le masséter ou ultrasons dans la douleur myofasciale"},{"nct":"NCT07832422","title":"Ischemic Compression and Low-Level Laser Therapy for Myofascial Low Back Pain","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":45,"start":"2026-09","end":"2027-03","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Low Back Pain","Myofascial Pain Syndromes"],"interventions":[{"type":"OTHER","name":"Ischemic Compression"},{"type":"DEVICE","name":"Low-Level Laser Therapy"},{"type":"OTHER","name":"Exercise Program"},{"type":"DEVICE","name":"Sham Low-Level Laser Therapy"}],"sponsor":"Nova Southeastern University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Alicia Fernandez-Fernandez, PT, DPT, PhD","role":"STUDY_CHAIR","affiliation":"Nova Southeastern University"}],"countries":["United States"],"sites":[{"facility":"Attia Rehabilitation Pt Pc","city":"Brooklyn","country":"United States"}],"n_sites":1,"outcome":"Pain Intensity Measured by Visual Analog Scale (VAS)","summary":"This randomized controlled study will compare the effects of ischemic compression combined with exercise, low-level laser therapy combined with exercise, and sham low-level laser therapy combined with exercise in adults with subacute or chronic myofascial low back pain. Participants will be assigned to one of three treatment groups. Outcomes will include pain intensity measured using the Visual Analog Scale (VAS), pressure pain threshold (PPT), and disability measured using the Oswestry Disability Index (ODI). Outcomes will be assessed at baseline, 3 weeks, 6 weeks, and at a 1-month follow-up.","updated":"2026-09-22","first_posted":"2026-09-22","type":"INTERVENTIONAL","ctx":"rachis","titre":"Compression ischémique et laser basse énergie dans la lombalgie myofasciale"},{"nct":"NCT07099352","title":"Efficacy of of Acupuncture Laser Therapy on Hemodialysis Patients","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-08-03","end":"2027-08-01","allocation":"NA","masking":"NONE","conditions":["Hemodialysis"],"interventions":[{"type":"DEVICE","name":"Acupuncture Laser Therapy"}],"sponsor":"Sinai University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Amany Gomaa Atiaa","title":"Academic researcher","affiliation":"Sinai University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Cairo university- Faculity of physical therapy","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"change in pain scales","summary":"This expected prospective randomized control trial study will involve 60 haemodialysis patients with neck pain. The patients in the experimental group (E) will subject, medical treatment besides acupuncture laser therapy. Medical treatment will be used in the control group (C). Pain and quality of life assessment will be used in the assessment of outcome.","updated":"2026-08-04","first_posted":"2025-08-01","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser-acupuncture contre la cervicalgie des patients hémodialysés"},{"nct":"NCT07654790","title":"ESWT vs HILT in Chronic Lateral Epicondylitis","acronym":"ESWT vs HILT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":72,"start":"2026-08-01","end":"2026-10-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Chronic Lateral Epicondylitis"],"interventions":[{"type":"DEVICE","name":"Extracorporeal shock wave therapy"},{"type":"OTHER","name":"Conventional Physical Therapy"},{"type":"DEVICE","name":"High-power intinsty laser"}],"sponsor":"Kafrelsheikh University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mohammed Ali Saleh Alghamdi","title":"Principal Investigator","affiliation":"Kafrelsheikh University"},"officials":[{"name":"MAHMOUD MOHAMMED EWIDA, PHD","role":"STUDY_CHAIR","affiliation":"Professor of Basic Sciences for Physical Therapy Department of Basic Sciences for Physical Therapy Faculty of Physical Therapy Kafrelsheikh University"},{"name":"MOHAMMED FATHY ABDEL-GALIL","role":"STUDY_DIRECTOR","affiliation":"Lecturer of Basic Sciences for Physical Therapy Department of Basic Sciences for Physical Therapy Faculty of Physical Therapy Kafrelsheikh University"},{"name":"HOSSAM MOHAMMED GAD, PHD","role":"STUDY_DIRECTOR","affiliation":"Professor of Orthopaedic Surgery Department of Orthopaedic Surgery Faculty of medicine Kafrelsheikh University"}],"countries":[],"sites":[],"n_sites":0,"outcome":"1. Pain intensity measured using Visual Analogue Scale (VAS).","summary":"This randomized controlled trial aims to compare the effectiveness of Extracorporeal Shock Wave Therapy (ESWT) and High-Intensity Laser Therapy (HILT) in patients with chronic lateral epicondylitis.","updated":"2026-06-17","first_posted":"2026-06-17","type":"INTERVENTIONAL","ctx":"tendon","titre":"Ondes de choc ou laser haute intensité dans l'épicondylite chronique"},{"nct":"NCT07666061","title":"Laser vs Lontophoresis in KOA","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":66,"start":"2026-08-01","end":"2026-10-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Knee Arthritis Osteoarthritis"],"interventions":[{"type":"DEVICE","name":"Low-Level Laser Therapy"},{"type":"DEVICE","name":"Iontophoresis"},{"type":"OTHER","name":"Conventional Physical Therapy Only"}],"sponsor":"Kafrelsheikh University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Abdulaziz Fahad Ahmed Alsulaimani","title":"Princpal Investigator","affiliation":"Kafrelsheikh University"},"officials":[{"name":"hane mohamed hamed, PHD","role":"STUDY_CHAIR","affiliation":"professor of orthopedic surgery depaetment of orthopedic surgery faculty of medicine kafrelsheikh university"},{"name":"mahmoud mohamed ewida, PHD","role":"STUDY_CHAIR","affiliation":"professor of basic sciences for physical therapy department of basic sciences for physical therapy faculty oh physical therapy kafrelsheikh university"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Pain intensity measured using Visual Analogue Scale (VAS)","summary":"This randomized controlled trial aims to compare the effectiveness of laser therapy and iontophoresis in patients with knee osteoarthritis. The study will evaluate pain reduction, functional improvement, and knee joint mobility following","updated":"2026-06-24","first_posted":"2026-06-24","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser ou ionophorèse dans la gonarthrose"},{"nct":"NCT07750392","title":"Dry Needling and Low-Level Laser Microcurrent Electrical Stimulation for Myofascial Pain Syndrome","acronym":null,"status":"RECRUITING","phases":["NA"],"n":80,"start":"2026-07-30","end":"2026-11-30","allocation":"RANDOMIZED","masking":"NONE","conditions":["Myofacial Pain Syndrome"],"interventions":[{"type":"DEVICE","name":"Dry Needle"},{"type":"DEVICE","name":"Low-Level Laser Microcurrent Electrical Stimulation"},{"type":"DEVICE","name":"Sham Dry Needle"}],"sponsor":"Udayana University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"I Putu Eka Widyadharma, MD, MSc, PhD","title":"Head of Neurology Study Program, Principal Investigator, Associate Professor","affiliation":"Udayana University"},"officials":[],"countries":["Indonesia"],"sites":[{"facility":"Udayana University","city":"Denpasar","country":"Indonesia"}],"n_sites":1,"outcome":"Change in Serum Malondialdehyde (MDA) Concentration","summary":"This study aims to evaluate the effectiveness of dry needling and Low-Level Laser Microcurrent Electrical Stimulation (LL MCES) in patients with acute upper trapezius myofascial pain syndrome (MPS) by assessing both biological and clinical outcomes. Specifically, it investigates whether these interventions reduce serum levels of the inflammatory biomarker tumor necrosis factor-alpha (TNF-α) and the oxidative stress biomarker malondialdehyde (MDA), while also improving pain intensity and neck-related disability. The study seeks to address the current knowledge gap regarding the relationship between changes in inflammatory and oxidative stress biomarkers and clinical improvement following these non-pharmacological treatments. The primary research question is: Do dry needling and LL MCES reduce serum TNF-α and MDA levels and improve clinical outcomes in patients with acute upper trapezius m","updated":"2026-08-10","first_posted":"2026-08-06","type":"INTERVENTIONAL","ctx":"fibro","titre":"Dry needling et laser à microcourants dans le syndrome myofascial"},{"nct":"NCT07734922","title":"High-Intensity Laser Therapy and Physiotherapy for Bone Health in Postmenopausal Women: A Randomized Trial","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":40,"start":"2026-07-27","end":"2027-01-31","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Osteoporosis, Postmenopausal","Osteopenia"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy"},{"type":"DEVICE","name":"Sham Laser"},{"type":"BEHAVIORAL","name":"Standardised Physiotherapy Programme"}],"sponsor":"Iuliu Hatieganu University of Medicine and Pharmacy","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Viorela Mihaela Ciortea","title":"Conf. Dr. Viorela Mihaela Ciortea","affiliation":"Iuliu Hatieganu University of Medicine and Pharmacy"},"officials":[],"countries":["Romania"],"sites":[{"facility":"Clinical Rehabilitation Hospital","city":"Cluj-Napoca","country":"Romania"}],"n_sites":1,"outcome":"Change from baseline in serum procollagen type I N-terminal propeptide (P1NP)","summary":"The goal of this clinical trial is to learn if adding high-intensity laser therapy (HILT) to a physiotherapy programme helps bone health in women after menopause who have low bone density (osteopenia or osteoporosis). It also looks at safety and quality of life.\n\nThe main questions it aims to answer are:\n\nDoes adding high-intensity laser therapy change a blood marker of bone formation called P1NP? Does adding high-intensity laser therapy improve participants' quality of life? Researchers will compare a group that gets physiotherapy plus real laser therapy with a group that gets physiotherapy plus a sham laser (a look-alike treatment that gives no real laser energy). This shows if the laser itself makes a difference.\n\nParticipants will:\n\nDo the same physiotherapy programme, 3 times a week for 4 weeks Get either real or sham laser therapy at each session Give blood samples before and after","updated":"2026-07-29","first_posted":"2026-07-29","type":"INTERVENTIONAL","ctx":"os","titre":"Laser haute intensité et kinésithérapie pour la santé osseuse après la ménopause"},{"nct":"NCT07865325","title":"Photobiomodultion in Anterior Knee Pain","acronym":"PBM","status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":104,"start":"2026-07-16","end":"2026-10","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Anterior Knee Pain","Photobiomodulation (PBM)","Laser Therapy"],"interventions":[{"type":"DEVICE","name":"Photobiomodultion with Laser scanning"},{"type":"OTHER","name":"patellar mobilization with exercise therapy"}],"sponsor":"New Ismailia National University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Jordan"],"sites":[{"facility":"Mohamed Abo El Ros","city":"Amman","country":"Jordan"}],"n_sites":1,"outcome":"knee pain","summary":"The goal of this clinical trial is to assess the augmented recovery in the adolescent females with patellar tendinopathy using Phot- Biomodulation","updated":"2026-10-08","first_posted":"2026-10-08","type":"INTERVENTIONAL","ctx":"arthrose","titre":"PBM par laser à balayage dans le syndrome fémoro-patellaire"},{"nct":"NCT07661407","title":"High-Intensity Laser Therapy (HILT) in Patients With Knee Osteoarthritis","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":72,"start":"2026-07-03","end":"2027-02-28","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Knee Osteoarthritis (Knee OA)"],"interventions":[{"type":"BEHAVIORAL","name":"Conventional Physiotherapy"},{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT)"},{"type":"DEVICE","name":"Sham High-Intensity Laser Therapy"}],"sponsor":"University of Rzeszow","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Paweł Nalborczyk","title":"Principal Investigator","affiliation":"University of Rzeszow"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Change in Knee Injury and Osteoarthritis Outcome Score (KOOS) Pain Subscale Score","summary":"This randomized placebo-controlled trial aims to evaluate the effectiveness of High-Intensity Laser Therapy (HILT) as an adjunct to standard outpatient physiotherapy in patients with knee osteoarthritis. Seventy-two participants will be randomly assigned to receive either conventional physiotherapy combined with active HILT or conventional physiotherapy combined with sham HILT. Outcomes related to pain, knee function, physical performance, muscle strength, range of motion, psychosocial factors, quality of life and body composition will be assessed at baseline, after the intervention, and at 8-week follow-up.","updated":"2026-06-29","first_posted":"2026-06-22","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser haute intensité contre sham dans la gonarthrose"},{"nct":"NCT07615920","title":"HILT vs ESWT in Supraspinatus Tendinitis","acronym":null,"status":"RECRUITING","phases":["NA"],"n":90,"start":"2026-07-01","end":"2026-12-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Supraspinatus Tendinitis"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy"},{"type":"DEVICE","name":"Extracorporeal Shock Wave Therapy"},{"type":"OTHER","name":"Conventional Physical Therapy"}],"sponsor":"Kafrelsheikh University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"sami abdu akkur","title":"Princpal Investigator","affiliation":"Kafrelsheikh University"},"officials":[{"name":"Yasmin Mohamed Mahmoud","role":"STUDY_DIRECTOR","affiliation":"Kafrelsheikh University Faculty of Physical Therapy Department of Basic Sciences for Physical Therapy"},{"name":"Mahmoud Mohamed Ewida, PHD","role":"STUDY_CHAIR","affiliation":"Kafrelsheikh University Faculty of Physical Therapy Department of Basic Sciences for Physical Therapy"},{"name":"Shaimaa Ramadan Eldeab, PHD","role":"STUDY_DIRECTOR","affiliation":"Lecturer of orthopedic physical therapy Department of physical therapy for musculoskeletal disorders and it's surgery"},{"name":"Sami ABDU Akkur, MASTER DEGREE STUDENT","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Kafrelsheikh University Faculty of Physical Therapy Department of Basic Sciences for Physical Therapy"}],"countries":["Saudi Arabia"],"sites":[{"facility":"King Faisal Medical Complex","city":"Ta'if","country":"Saudi Arabia"}],"n_sites":1,"outcome":"Pain intensity measured using Visual Analogue Scale (VAS).","summary":"This randomized controlled trial aims to compare the effectiveness of High-Intensity Laser Therapy (HILT) and Extracorporeal Shock Wave Therapy (ESWT) in patients with supraspinatus tendinitis.","updated":"2026-10-20","first_posted":"2026-05-29","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser haute intensité ou ondes de choc dans la tendinopathie du supra-épineux"},{"nct":"NCT07584603","title":"Effect of High-Intensity Laser Therapy on Femoral Cartilage in Knee Osteoarthritis","acronym":"HILT-KOA","status":"NOT_YET_RECRUITING","phases":["NA"],"n":58,"start":"2026-07-01","end":"2027-01-15","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Osteoarthritis (OA) of the Knee","Osteoarthitis"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT) + Conventional Physiotherapy"},{"type":"OTHER","name":"Conventional Physiotherapy"}],"sponsor":"University of Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Pakistan"],"sites":[{"facility":"London Aesthetics and Rejuvenation Center","city":"Lahore","country":"Pakistan"}],"n_sites":1,"outcome":"Femoral Cartilage Thickness","summary":"This clinical trial will evaluate the effects of High-Intensity Laser Therapy (HILT) on femoral cartilage thickness and other clinical outcomes in people with knee osteoarthritis. Participants aged 40 to 60 years with grade II or III knee osteoarthritis will be randomly assigned to receive either HILT plus conventional physiotherapy or conventional physiotherapy alone. Both groups will receive 12 treatment sessions on alternate days for 4 weeks. The study will assess changes in cartilage thickness using ultrasound, as well as improvements in pain, knee movement, muscle strength, and daily function. Findings from this research may help improve physiotherapy treatment strategies for patients with knee osteoarthritis.","updated":"2026-05-13","first_posted":"2026-05-13","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser haute intensité et cartilage fémoral dans la gonarthrose"},{"nct":"NCT07667998","title":"High-intensity Laser Therapy Versus Extracorporeal Shock Wave on Tendon Thickness and Occupation Ratio In Patients With Chronic Supraspinatus Tendinopathy","acronym":"HILT","status":"RECRUITING","phases":["NA"],"n":69,"start":"2026-06-30","end":"2027-04-25","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Supraspinatus Tendinopathy"],"interventions":[{"type":"OTHER","name":"High-intensity Laser Therapy"},{"type":"OTHER","name":"Extracorporeal Shock Wave"},{"type":"OTHER","name":"conventional therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mahmoud Mamdouh Ahmed Shaaban","title":"principle investigator : mahmoud mamdouh ahmed shaaban","affiliation":"Cairo University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Cairo University - faculty of physical therapy outpatient clinic","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"supraspinatous tendon thickness","summary":"This study will be conducted to investigate the difference between high-intensity laser and extracorporeal shock wave on supraspinatus tendon thickness, subacromial space, occupation ratio, shoulder pain intensity, shoulder range of motion (ROM), hand strength, and functional disability in patients with chronic supraspinatus tendinopathy.","updated":"2026-11-04","first_posted":"2026-06-25","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser haute intensité ou ondes de choc : épaisseur du tendon supra-épineux"},{"nct":"NCT07602933","title":"Photobiomodulation Effects on Fatigue and Muscle Damage Induced by NMES","acronym":null,"status":"RECRUITING","phases":["NA"],"n":36,"start":"2026-06-01","end":"2026-08-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Photobiomodulation","Fatigue","Discomfort","Electrical Stimulation","Muscle Damage"],"interventions":[{"type":"DEVICE","name":"Active Photobiomodulation"},{"type":"DEVICE","name":"Placebo Photobiomodulation"},{"type":"OTHER","name":"NMES-evoked fatigue protocol"}],"sponsor":"Federal University of Rio Grande do Sul","sponsor_class":"OTHER","collaborators":["Conselho Nacional de Desenvolvimento Científico e Tecnológico"],"responsible":{"name":"Marco Aurélio Vaz, PhD","title":"Full Professor","affiliation":"Federal University of Rio Grande do Sul"},"officials":[{"name":"Marco A Vaz, PhD","role":"STUDY_CHAIR","affiliation":"Federal University of Rio Grande do Sul"},{"name":"Marco A Vaz, PhD","role":"STUDY_DIRECTOR","affiliation":"Federal University of Rio Grande do Sul"},{"name":"Marco A Vaz, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Federal University of Rio Grande do Sul"}],"countries":["Brazil"],"sites":[{"facility":"Laboratório de Pesquisa do Exercício","city":"Porto Alegre","country":"Brazil"}],"n_sites":1,"outcome":"Maximal voluntary isometric contraction (MVIC)","summary":"Neuromuscular electrical stimulation (NMES) is widely used to improve muscle strength and mitigate atrophy. However, its clinical efficacy is often limited by early neuromuscular fatigue, muscle damage, and discomfort, which reduce patient tolerance and contraction time. Photobiomodulation (PBM) has emerged as a potential therapy to enhance muscle performance and accelerate recovery by minimizing fatigue and damage. Despite its potential, few studies have investigated the effects of PBM applied specifically before an NMES-evoked fatigue protocol. This randomized, double-blind, placebo-controlled trial aims to evaluate the acute effects of PBM on neuromuscular fatigue, muscle damage, and functional outcomes in healthy young subjects. Participants will receive either active PBM (cluster probe: 5 lasers 810nm/200mW; 4 LEDs 660nm/10mW; Total Energy: 249.6 J per limb) or sham treatment 5 minu","updated":"2026-08-25","first_posted":"2026-05-22","type":"INTERVENTIONAL","ctx":"muscle","titre":"PBM, fatigue et lésions musculaires induites par électrostimulation"},{"nct":"NCT07672327","title":"Efficacy of Short Wave and Laser Therapy in Patients With Plantar Fasciitis","acronym":"Blind assessor","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":60,"start":"2026-06-01","end":"2026-06-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Plantar Fasciitis, Chronic"],"interventions":[{"type":"OTHER","name":"conventional physical therapy"},{"type":"OTHER","name":"Extracorporeal shock wave therapy"},{"type":"OTHER","name":"High-intensity laser therapy"}],"sponsor":"Ibrahim Abuomar Fadulaalhq Alramadhani","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Ibrahim Abuomar Fadulaalhq Alramadhani","title":"M. Sc. in Physical Therapy, Sport Physical Therapy (2021) College of Applied Medical Sciences, Umm Al-Qura University, Kingdom of Saudi Arabia","affiliation":"Umm Al-Qura University"},"officials":[],"countries":["Saudi Arabia"],"sites":[{"facility":"Mecca","city":"Mecca","country":"Saudi Arabia"}],"n_sites":1,"outcome":"Hand held dynamometer","summary":"Plantar fasciitis is a common painful condition. It accounts for 10-15% of all foot painful conditions. Recently, Extracorporeal shock wave therapy (ESWT) was used as an effective method in treatment of different musculoskeletal disorders. High-intensity laser therapy (HILT) is a relatively recent treatment option that has shown benefits in a wide range of musculoskeletal disorders.","updated":"2026-06-26","first_posted":"2026-06-26","type":"INTERVENTIONAL","ctx":"tendon","titre":"Laser haute intensité, ondes courtes et ondes de choc dans la fasciite plantaire"},{"nct":"NCT07637084","title":"Photobiomodulation for Chronic Pain and Fatigue in Hypermobile Ehlers-Danlos Syndrome (PBM-SEDh-01)","acronym":"PBM-SEDh-01","status":"RECRUITING","phases":[],"n":25,"start":"2026-05-26","end":"2027-03-31","allocation":null,"masking":null,"conditions":["Ehlers-Danlos Syndrome, Hypermobile","Chronic Pain","Fatigue Syndrome, Chronic"],"interventions":[],"sponsor":"Centre Medical ISM (Integrative Systemic Medicine)","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["France"],"sites":[{"facility":"Centre Médical ISM","city":"Boulogne-Billancourt","country":"France"}],"n_sites":1,"outcome":"Change in chronic pain intensity","summary":"This study evaluates the effect of photobiomodulation (PBM) therapy using a MLS® class IV laser on chronic pain and fatigue in patients with hypermobile Ehlers-Danlos Syndrome (hEDS). hEDS is a hereditary connective tissue disorder characterized by joint hypermobility, chronic pain, and debilitating fatigue, for which therapeutic options remain limited.\n\nParticipants will receive 10 PBM sessions over 5 weeks (2 sessions per week), using red and near-infrared light (808 nm continuous + 905 nm pulsed) applied to painful areas identified at baseline. Pain (Visual Analogue Scale), multidimensional fatigue (MFI-20), and quality of life (EQ-5D-5L) will be assessed at baseline (T0), end of treatment (week 5), and follow-up (week 10).\n\nThis is a pilot observational study - the first to document the effect of MLS® laser PBM in hEDS. No additional procedures beyond routine care are required.","updated":"2026-06-15","first_posted":"2026-06-09","type":"OBSERVATIONAL","ctx":"EDS","titre":"PBM-SEDh-01 : PBM contre la douleur chronique et la fatigue du syndrome d'Ehlers-Danlos hypermobile"},{"nct":"NCT07564713","title":"Comparison of Extracorporeal Shock Wave Therapy and Low-Level Laser Therapy in Patients With Lateral Epicondylitis","acronym":null,"status":"RECRUITING","phases":["NA"],"n":50,"start":"2026-05-04","end":"2026-09-29","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Lateral Epicondylitis (Tennis Elbow)"],"interventions":[{"type":"BEHAVIORAL","name":"ESWT Group"},{"type":"BEHAVIORAL","name":"LLLT Group"}],"sponsor":"Hitit University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Pınar Özge Başaran","title":"Principal Investigator","affiliation":"Hitit University"},"officials":[{"name":"Pınar Başaran, Dr","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Hitit University"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Hitit University Erol Olçok Research Hospital Physical Medicine and Rehabilitation Clinic","city":"Çorum","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Pain intensity will be measured by the Visual Analog Scale (VAS)","summary":"Background:\n\nLateral epicondylitis is a common musculoskeletal condition characterized by pain and functional impairment of the elbow, often associated with degenerative changes in the common extensor tendon. Extracorporeal shock wave therapy (ESWT) and low-level laser therapy (LLLT) are widely used noninvasive treatment modalities; however, comparative evidence regarding their clinical and structural effects remains limited.\n\nObjective:\n\nThis study aims to compare the effects of ESWT and LLLT on pain intensity, elbow function, quality of life, grip strength, and ultrasonographic characteristics of the extensor tendon (thickness and echogenicity) in patients with lateral epicondylitis.\n\nMethods:\n\nThis prospective, randomized, single-blind, comparative clinical trial will be conducted at the Physical Medicine and Rehabilitation outpatient clinic. Patients aged 18-65 years with clinically ","updated":"2026-06-16","first_posted":"2026-05-04","type":"INTERVENTIONAL","ctx":"tendon","titre":"Ondes de choc ou laser basse énergie dans l'épicondylite latérale"},{"nct":"NCT07531654","title":"Comparative Effectiveness of Standard and Modified Laser Therapy in Myofascial Pain Management.","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":40,"start":"2026-05-01","end":"2026-11-12","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Myofascial Pain Dysfunction Syndrome"],"interventions":[{"type":"DEVICE","name":"High Level Laser Therapy"},{"type":"DEVICE","name":"Low Level Laser Therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Ayman Mohamed Gouda","title":"Assistant professor of Oral and Maxillofacial Surgery","affiliation":"Cairo University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Cairo University","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Pain Assessment","summary":"The goal of this clinical trial is to evaluate and compare the effectiveness of modified laser therapy versus conventional laser therapy in managing pain and mandibular function in patients with chronic myofascial pain syndrome involving the masseter muscles. The main questions it aims to answer are:\n\n1. Does high-intensity laser therapy (HILT) provide a greater reduction in pain intensity on a numerical rating scale (NRS) compared to low-level laser therapy (LLLT)?\n2. Does high-intensity laser therapy (HILT) provide greater improvement in functional outcomes, specifically maximal incisal opening, compared to low-level laser therapy (LLLT)?\n\nComparison Group:\n\nResearchers will compare the experimental group receiving High-Intensity Laser Therapy (HLLT) to a comparator group receiving Low-Level Laser Therapy (LLLT) to see if the modified high-intensity approach provides superior pain reli","updated":"2026-04-15","first_posted":"2026-04-15","type":"INTERVENTIONAL","ctx":"fibro","titre":"Laser standard ou modifié dans la douleur myofasciale"},{"nct":"NCT07313826","title":"Treatment of Chronic Lower Back Pain With a Combination of Electrical Stimulation, LED, and Laser Therapy","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":50,"start":"2026-05-01","end":"2028-01-01","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Chronic Low Back Pain"],"interventions":[{"type":"DEVICE","name":"Active Neurolumen"},{"type":"DEVICE","name":"Inactive Neurolumen"}],"sponsor":"Defense and Veterans Center for Integrative Pain Management","sponsor_class":"OTHER","collaborators":["Neurolumen LLC"],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"Naval Medical Center Portsmouth","city":"Portsmouth","country":"United States"}],"n_sites":1,"outcome":"Pain Intensity","summary":"This study will evaluate the impact of the Neurolumen medical device on chronic low back pain.","updated":"2026-02-13","first_posted":"2026-01-02","type":"INTERVENTIONAL","ctx":"rachis","titre":"Électrostimulation, LED et laser combinés (Neurolumen) dans la lombalgie chronique"},{"nct":"NCT07556926","title":"High-intensity Laser Therapy and Mulligan Mobilization for Patients With Chronic Nonspecific Low Back Pain","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":50,"start":"2026-04-30","end":"2026-05-30","allocation":"RANDOMIZED","masking":"NONE","conditions":["Low Back Pain"],"interventions":[{"type":"DEVICE","name":"High-intensity laser therapy and Mulligan mobilization"},{"type":"OTHER","name":"Mulligan Mobilization"}],"sponsor":"Anas Radi Hassan Alashram","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Anas Radi Hassan Alashram","title":"Associate Professor","affiliation":"Middle East University"},"officials":[],"countries":["Jordan"],"sites":[{"facility":"Middle East University","city":"Amman","country":"Jordan"}],"n_sites":1,"outcome":"Numeric Pain Rating Scale (NPRS)","summary":"The goal of this clinical trial is to evaluate whether combining high-intensity laser therapy with Mulligan mobilization techniques can effectively treat chronic non-specific low back pain in adult patients aged 18-60 years, including both males and females.\n\nThe main questions it aims to answer are:\n\nDoes the combined intervention reduce pain intensity more effectively than standard or single-modality treatment? Does the combined intervention improve functional disability and lumbar range of motion?\n\nResearchers will compare high-intensity laser therapy combined with Mulligan mobilization to \\[control group: Mulligan alone\\] to determine whether the combined approach produces superior clinical outcomes.\n\nParticipants will:\n\nReceive high-intensity laser therapy according to a standardized treatment protocol Undergo Mulligan mobilization techniques administered by a trained therapist Atte","updated":"2026-04-29","first_posted":"2026-04-29","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser haute intensité et mobilisations de Mulligan dans la lombalgie chronique"},{"nct":"NCT07551245","title":"Knee Osteoarthritis Rehab: High-Intensity Laser vs Classical Modalities","acronym":"HILT-CM (KOA)","status":"RECRUITING","phases":["NA"],"n":100,"start":"2026-04-20","end":"2027-01-15","allocation":"RANDOMIZED","masking":"NONE","conditions":["Knee Arthritis Osteoarthritis"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT)"},{"type":"DEVICE","name":"Conventional Physical Therapy Modalities"}],"sponsor":"Erbil Polytechnic University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mahdi Qadir","title":"Lecturer","affiliation":"Erbil Polytechnic University"},"officials":[{"name":"Ahmed Bapir, PhD","role":"STUDY_DIRECTOR","affiliation":"EPU"}],"countries":["Iraq"],"sites":[{"facility":"Aylan Center","city":"Erbil","country":"Iraq"}],"n_sites":1,"outcome":"Change in Pain Intensity (WOMAC Pain Subscale)","summary":"This study aims to compare the effectiveness and safety of High-Intensity Laser Therapy (HILT) with conventional physical therapy treatments in patients with knee osteoarthritis. Knee osteoarthritis is a common condition, especially in older adults, causing pain, stiffness, reduced movement, and difficulty performing daily activities. Current treatments focus on reducing pain and improving joint function.\n\nIn this study, 100 patients with knee osteoarthritis will be divided into two groups. One group will receive HILT combined with therapeutic exercises, while the other group will receive conventional physical therapy modalities along with the same exercises. The treatment outcomes will be evaluated over time.\n\nThe main outcomes include pain reduction (measured by pain scales such as WOMAC and VAS), improvement in joint function, and structural changes in the knee assessed by MRI. In add","updated":"2026-04-24","first_posted":"2026-04-24","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser haute intensité ou agents physiques classiques dans la gonarthrose"},{"nct":"NCT07501416","title":"High-Intensity Laser Therapy in Hemiplegic Shoulder Pain","acronym":null,"status":"RECRUITING","phases":["NA"],"n":60,"start":"2026-04-01","end":"2026-12-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Hemiplegia and/or Hemiparesis Following Stroke"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT)"},{"type":"OTHER","name":"Exercise therapy"},{"type":"DEVICE","name":"Sham Laser Therapy"}],"sponsor":"Kutahya Health Sciences University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Fatima Yaman","title":"Assoc. Prof.","affiliation":"Kutahya Health Sciences University"},"officials":[{"name":"Fatima YAMAN, Assoc. Prof.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Kutahya Health Sciences University"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Kutahya Health Sciences University","city":"Kütahya","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Shoulder Pain and Disability Index (SPADI)","summary":"This randomized, sham-controlled clinical trial aims to evaluate the effectiveness of high-intensity laser therapy (HILT) combined with exercise on pain, functional status, disability, and ultrasonographic findings in patients with hemiplegic shoulder pain following stroke.","updated":"2026-08-27","first_posted":"2026-03-30","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser haute intensité contre sham dans l'épaule douloureuse de l'hémiplégique"},{"nct":"NCT07477678","title":"Red Light Therapy: a Potential Strategy to Reduce Sports Injury Risk?","acronym":"DIAERESIS","status":"NOT_YET_RECRUITING","phases":["NA"],"n":40,"start":"2026-03-23","end":"2026-04-13","allocation":"RANDOMIZED","masking":"NONE","conditions":["Ankle Dorsiflexion"],"interventions":[{"type":"DEVICE","name":"Near-infrared photobiomodulation"},{"type":"OTHER","name":"Cycling Warm-up"}],"sponsor":"Cláudio da Silva Ferreira","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Cláudio da Silva Ferreira","title":"Physical Therapist","affiliation":"Aveiro University"},"officials":[{"name":"Cláudio da Silva Ferreira, Licenciate","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Aveiro"}],"countries":["Portugal"],"sites":[{"facility":"Human Movement Laboratory, Escola Superior de Saúde da Universidade de Aveiro (ESSUA)","city":"Aveiro","country":"Portugal"}],"n_sites":1,"outcome":"Ankle dorsiflexion range of motion","summary":"This study investigates whether near-infrared light therapy can acutely improve ankle dorsiflexion mobility and hamstring flexibility, two factors associated with sports injury risk. Healthy adult students will complete three randomized conditions: a control session, a 10-minute cycling warm-up, and a 10-minute exposure to a red and near-infrared LED panel (MITO LIGHT®). Mobility and flexibility will be assessed before and after each condition using the Knee-to-Wall Test (KWT) and the Active Knee Extension Test (AKET). The study aims to determine whether photobiomodulation may serve as a potential strategy to reduce musculoskeletal injury risk.","updated":"2026-03-19","first_posted":"2026-03-17","type":"INTERVENTIONAL","ctx":"muscle","titre":"PBM proche infrarouge à l'échauffement pour réduire le risque de blessure"},{"nct":"NCT07460895","title":"Effectiveness of Photobiomodulation for Myofascial Pain in Temporomandibular Disorders","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":140,"start":"2026-03-10","end":"2030-10","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Photobiomodulation","Temporomandibular Disorder (TMD)","Myofacial Pain","Pain Management"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation Therapy"},{"type":"BEHAVIORAL","name":"Therapeutic Exercises"},{"type":"DEVICE","name":"Sham Photobiomodulation Therapy"}],"sponsor":"Federal University of Rio Grande do Sul","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Manoela Domingues Martins","title":"Associate Professor","affiliation":"Federal University of Rio Grande do Sul"},"officials":[{"name":"Manoela Domingues Martins, DDS, MSc, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Federal University of Rio Grande do Sul"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Assessment of Myofascial Pain Intensity","summary":"This randomized clinical trial aims to evaluate the effectiveness of photobiomodulation therapy (PBM) alone or combined with therapeutic exercises compared with placebo PBM associated with exercises in patients with myofascial temporomandibular disorders (TMD). Participants will be allocated into three groups: PBM alone, PBM combined with exercises, or placebo PBM combined with exercises. The intervention consists of 12 treatment sessions. Outcomes related to pain intensity, mandibular function, and clinical measures will be assessed over time. The study seeks to investigate whether PBM provides additional benefits in pain reduction and functional improvement in individuals with myofascial TMD.","updated":"2026-03-10","first_posted":"2026-03-10","type":"INTERVENTIONAL","ctx":"ATM","titre":"PBM contre sham dans la douleur myofasciale des DTM"},{"nct":"NCT07352787","title":"High-Intensity Laser Therapy for Trapezius Myofascial Pain (HILT-TRAP Study)","acronym":"HILT-TRAP Stud","status":"NOT_YET_RECRUITING","phases":["NA"],"n":104,"start":"2026-03-10","end":"2026-12-15","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Myofascial Pain Syndrome (MPS)"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy"},{"type":"DEVICE","name":"Sham Laser Therapy"}],"sponsor":"Neveen Abd El Maksoad Kohaf","sponsor_class":"OTHER","collaborators":["Universiti Kebangsaan Malaysia Medical Centre"],"responsible":{"name":"Neveen Abd El Maksoad Kohaf","title":"Clinical Pharmacy Department, Faculty of Pharmacy (Girls), Al-Azhar University, Cairo, Egypt.","affiliation":"Al-Azhar University"},"officials":[],"countries":["Iraq"],"sites":[{"facility":"Al-Hussein Teaching Hospital","city":"Nasiriyah","country":"Iraq"}],"n_sites":1,"outcome":"Pain Intensity","summary":"This study aims to evaluate the effectiveness of optimized High-Intensity Laser Therapy (HILT) compared with sham treatment in patients with trapezius myofascial pain syndrome. Outcomes include pain intensity, cervical range of motion, functional disability, and depressive symptoms measured at baseline, post-intervention, and 16-week follow-up.","updated":"2026-01-20","first_posted":"2026-01-20","type":"INTERVENTIONAL","ctx":"fibro","titre":"Essai HILT-TRAP : laser haute intensité dans la douleur myofasciale du trapèze"},{"nct":"NCT07287046","title":"A Single-Blind Randomized Controlled Study Comparing the Efficacy of High-Intensity Laser Therapy and Focused Extracorporeal Shock Wave Therapy in Patients With Plantar Fasciitis","acronym":"HILT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":28,"start":"2026-02-28","end":"2026-12-25","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Plantar Fasciitis"],"interventions":[{"type":"DEVICE","name":"High power Laser therapy"},{"type":"DEVICE","name":"Focused extracorporeal shock wave therapy"}],"sponsor":"Mahidol University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Visual analog scale (VAS)","summary":"This randomized controlled trial aims to evaluate the efficacy of High-Intensity Laser Therapy (HILT) and Focused Extracorporeal Shock Wave Therapy (fESWT) in reducing pain in patients with plantar fasciitis. The study also examines the effects of HILT and fESWT on health-related outcomes, including VAS-FA, FFI, plantar fascia thickness, and adverse events.\n\nResearchers will compare HILT with fESWT as treatment options for patients with plantar fasciitis.\n\nParticipants will receive either HILT or fESWT along with an exercise program. They will attend follow-up visits to assess outcomes at 1, 2, 3, 6, and 12 weeks after the first treatment.","updated":"2026-03-25","first_posted":"2025-12-16","type":"INTERVENTIONAL","ctx":"tendon","titre":"Laser haute intensité ou ondes de choc focalisées dans la fasciite plantaire"},{"nct":"NCT07342426","title":"High and Low Dose High-intensity Laser Therapy Lateral Epicondylitis","acronym":null,"status":"RECRUITING","phases":["PHASE4"],"n":45,"start":"2026-01-12","end":"2026-02-06","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Lateral Epicondylitis","High Intensity Laser Therapy","Tennis Elbow","High Intensity Laser"],"interventions":[{"type":"DEVICE","name":"High intensity laser therapy"},{"type":"DEVICE","name":"Infarred ray therapy system"},{"type":"DEVICE","name":"Transcutaneous electrical nerve stimulator"}],"sponsor":"Kaohsiung Medical University Chung-Ho Memorial Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Taiwan"],"sites":[{"facility":"TSAI CHENG-TAO Physical Therapy Clinic","city":"Kaohsiung City","country":"Taiwan"}],"n_sites":1,"outcome":"Pain intensity","summary":"High-intensity laser therapy has gained increasing attention in recent years as a therapeutic modality. It is a non-invasive treatment that can reduce pain, increase local blood circulation, and promote tissue repair. The higher energy output of high-intensity laser therapy also have deeper tissue penetration. Several studies have investigated the effects of high-intensity laser therapy on lateral epicondylitis, and the existing literature indicates that, compared with other treatment modalities, high-intensity laser therapy is more effective in improving pain and quality of life in patients with lateral epicondylitis.\n\nHowever, the dosage, duration, and treatment frequency applied in previous studies vary considerably. The therapeutic effects of high-intensity laser therapy may therefore be influenced by treatment dosage. Consequently, the purpose of this study is to compare the effects","updated":"2026-01-21","first_posted":"2026-01-15","type":"INTERVENTIONAL","ctx":"tendon","titre":"Laser haute intensité à faible ou forte dose dans l'épicondylite latérale"},{"nct":"NCT06812611","title":"Effects of High Intensity Laser Therapy in Muscle Injuries","acronym":"THEALinMJ","status":"RECRUITING","phases":["NA"],"n":24,"start":"2025-12-01","end":"2027-01-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Muscle Tear"],"interventions":[{"type":"DEVICE","name":"High Energy Laser Group"},{"type":"OTHER","name":"Exercise"}],"sponsor":"Azienda Ospedaliero-Universitaria Consorziale Policlinico di Bari","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Italy"],"sites":[{"facility":"Policlinico di Bari","city":"Bari","country":"Italy"}],"n_sites":1,"outcome":"recovery of pain","summary":"Muscle injuries are frequent traumatic events in daily life, particularly during sports. In sports, their incidence varies from 10% to 55% of total injuries. According to the Mueller Wohlfart classification, muscle injuries are classified into direct traumatic injuries (contusion-laceration) and indirect traumatic injuries, which are further divided into non-structural injuries (grade I and II) and structural injuries. Structural lesions are further divided into partial muscle lesions (grade III): 3 A, minor partial lesion, i.e. lesion of one or more primary bundles with a secondary bundle; 3 B, moderate partial lesion, i.e. lesion of at least one secondary bundle and with a rupture area \\< 50% of the muscle surface; and (sub)total muscle injury (grade IV).","updated":"2026-05-14","first_posted":"2025-02-06","type":"INTERVENTIONAL","ctx":"muscle","titre":"Laser haute intensité dans les lésions musculaires"},{"nct":"NCT07878247","title":"Clinical and Electromyographic Assessment of Occlusal Splint Therapy","acronym":null,"status":"RECRUITING","phases":["NA"],"n":24,"start":"2025-12-01","end":"2026-12-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Temporomandibular Joint Disorders"],"interventions":[{"type":"PROCEDURE","name":"Low Level Laser Therapy"}],"sponsor":"Future University in Egypt","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Salma Mohamed Ebrahim","title":"Resident of Oral and Maxillofacial Surgery","affiliation":"Future University in Egypt"},"officials":[{"name":"Waleed Fathy Ali Esmael, Professor","role":"STUDY_CHAIR","affiliation":"oral and maxillofacial surgery,Future University in Egypt"}],"countries":["Egypt"],"sites":[{"facility":"Future University in Egypt (FUE)","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Treatment of Tempromandibular joint Pain","summary":"Temporomandibular disorders (TMDs) cause pain and dysfunction in the masticatory system, often managed with occlusal splint therapy. However, splint therapy alone may yield inconsistent results. Low-level laser therapy (LLLT) has been proposed as an adjunctive treatment to enhance pain relief and muscle function through photo biomodulation. Evidence comparing the efficacy of splint therapy alone versus its combination with LLLT remains limited. This study aims to evaluate, clinically and electromyographically.\n\nThe evidence for occlusal splints is mixed: some systematic reviews report possible short-term benefits for muscle pain but overall the evidence is inconclusive and of variable quality. Low-level laser therapy (LLLT) has been studied for TMD and orofacial pain with several systematic reviews and meta-analyses showing potential analgesic and anti-inflammatory effects, though study ","updated":"2026-10-16","first_posted":"2026-10-16","type":"INTERVENTIONAL","ctx":"ATM","titre":"Gouttière occlusale et laser basse énergie : évaluation clinique et EMG"},{"nct":"NCT07566507","title":"High-Energy Laser in the Conservative Treatment of Rhizarthrosis","acronym":"HLEX-TO","status":"RECRUITING","phases":["NA"],"n":42,"start":"2025-11-01","end":"2027-12-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Thumb Osteoarthritis","Hand Injuries","Laser","Exercise"],"interventions":[{"type":"DEVICE","name":"THEAL:Ixyon XP (Mectronic, Bergamo, Italy)"}],"sponsor":"Azienda Ospedaliero-Universitaria Consorziale Policlinico di Bari","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Italy"],"sites":[{"facility":"Angela Notarnicola","city":"Bari","country":"Italy"}],"n_sites":1,"outcome":"recovery of pain","summary":"Osteoarthritis (OA) is a degenerative joint disease that can affect the hands and is particularly debilitating when it involves the trapeziometacarpal joint (rhizarthrosis). It causes pain, deformity, limited movement and strength, joint instability, resulting in significant limitations in daily activities.Many conservative treatments, such as medications, therapeutic exercises, physical therapy, and orthoses, are effective for managing hand OA. For patients who do not respond to conservative treatments, surgical intervention will be necessary.","updated":"2026-05-15","first_posted":"2026-05-05","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser haute énergie dans la rhizarthrose"},{"nct":"NCT07112742","title":"Evaluation of the Effects of High Intensity Laser Therapy and Exercise in Hand Thumb Osteoarthritis","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":48,"start":"2025-11-01","end":"2026-08-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Thumb Osteoarthritis","Hand Osteoarthritis"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy and Exercise"},{"type":"DEVICE","name":"High-Intensity Laser Therapy at a Non-Therapeutic Dose Combined With Exercise"}],"sponsor":"TC Erciyes University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Gizem Cengiz","title":"Associate Professor","affiliation":"TC Erciyes University"},"officials":[],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Erciyes University","city":"Kayseri","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Visual Analog Scale (VAS)","summary":"One of the standard treatment methods in individuals with thumb osteoarthritis (OA) is exercise. Combination therapy options involving these exercises can be applied to patients. It has been demonstrated that high-intensity laser therapy is effective in terms of pain and function in patients with thumb OA.\n\nThe aim of this study is to investigate the effects of an exercise program combined with high-intensity laser therapy on pain, function, and muscle strength in patients with first carpometacarpal (CMC) joint osteoarthritis.","updated":"2025-09-25","first_posted":"2025-08-08","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser haute intensité et exercice dans l'arthrose du pouce"},{"nct":"NCT07161622","title":"Comparing Low-Level Laser and Muscle Energy Techniques in Diabetic Frozen Shoulder","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":36,"start":"2025-10","end":"2026-02","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Frozen Shoulder"],"interventions":[{"type":"OTHER","name":"Low-Level Laser Therapy (LLLT)"},{"type":"OTHER","name":"Muscle Energy Technique (MET)"}],"sponsor":"University of Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Aqsa Majeed","title":"Dr. Aqsa Majeed","affiliation":"University of Lahore"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Shoulder function","summary":"The current study is to evaluate the comparative effects of low-level laser therapy and muscle energy technique on pain, range of motion, and functional results in diabetic patients with frozen shoulder. This research aims to enhance the existing data on managing diabetes-related musculoskeletal issues by assessing the comparative advantages of various therapies, therefore assisting physicians in choosing appropriate, patient-centred rehabilitation procedures.","updated":"2025-09-18","first_posted":"2025-09-08","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser basse énergie ou énergie musculaire dans l'épaule gelée du diabétique"},{"nct":"NCT07426926","title":"Home-Based Photobiomodulation Effects in the Postoperative Period of Distal Radius Fractures","acronym":null,"status":"RECRUITING","phases":["NA"],"n":42,"start":"2025-09-06","end":"2027-07-30","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Distal Radius Fracture"],"interventions":[{"type":"PROCEDURE","name":"Open reduction and internal fixation (ORIF) with locked volar plate"},{"type":"PROCEDURE","name":"Home exercises"},{"type":"DEVICE","name":"Active photobiomodulation"},{"type":"DEVICE","name":"Inactive photobiomodulation"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Kristianne Porta Santos Fernandes","title":"PhD","affiliation":"University of Nove de Julho"},"officials":[{"name":"Kristianne PS Fernandes, PhD","role":"STUDY_DIRECTOR","affiliation":"University of Nove de Julho"}],"countries":["Brazil"],"sites":[{"facility":"ACN Municipal Hospital","city":"São Paulo","country":"Brazil"}],"n_sites":1,"outcome":"Quick-DASH functional scale - 2 weeks","summary":"This double-blind, randomized controlled clinical trial aims to evaluate the adjuvant effect of home-based photobiomodulation (PBM) therapy on the rehabilitation of surgically treated DRFs combined with an unsupervised home exercise program. A total of 42 participants will be randomly allocated into two groups. The Control Group will undergo the standard surgical procedure, perform the prescribed home exercises recommended by the hospital service, and use an inactive LED plate (photobiomodulation device). The PBM Group will follow the same surgical and exercise protocols but will use an active PBM device. Home exercises will begin 24 hours after surgery and should be performed twice daily for a total of 12 weeks. The device will be applied once daily to the wrist for 12 minutes (6 minutes on the dorsal side and 6 minutes on the palmar side). The primary outcome will be functional wrist a","updated":"2026-09-29","first_posted":"2026-02-23","type":"INTERVENTIONAL","ctx":"os","titre":"PBM à domicile après ostéosynthèse d'une fracture du radius distal"},{"nct":"NCT07224646","title":"Whole-Body Photobiomodulation Use in Professional Soccer Players During a State Championship","acronym":"WBPBM-PSC","status":"RECRUITING","phases":["NA"],"n":24,"start":"2025-09-04","end":"2026-08","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Athletic Performance","Muscle Fatigue","Muscle Strength","Sports"],"interventions":[{"type":"RADIATION","name":"Whole-Body Photobiomodulation (PBM) (Active PBM)"},{"type":"RADIATION","name":"Sham PBM"}],"sponsor":"Universidade Federal de Sao Carlos","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Italo Amaral de Oliveira","title":"MSc","affiliation":"Universidade Federal de Sao Carlos"},"officials":[{"name":"Italo A Oliveira, MSc","role":"PRINCIPAL_INVESTIGATOR","affiliation":"UFSCAR"}],"countries":["Brazil"],"sites":[{"facility":"Desportivo Brasil Training Center","city":"Porto Feliz","country":"Brazil"}],"n_sites":1,"outcome":"Delayed Onset Muscle Soreness (DOMS)","summary":"This study aims to investigate the effects of whole-body photobiomodulation on professional soccer players during a state championship. The primary question is whether photobiomodulation improves recovery, reduces muscle fatigue, and enhances performance compared to standard training without photobiomodulation.","updated":"2025-11-24","first_posted":"2025-11-05","type":"INTERVENTIONAL","ctx":"muscle","titre":"PBM corps entier chez des footballeurs professionnels en championnat"},{"nct":"NCT07125404","title":"Low-Level Laser Auriculotherapy in the Treatment of Myogenic Temporomandibular Disorders and Anxiety","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":32,"start":"2025-09-01","end":"2025-12-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Temporomandibular Disorder","Anxiety State"],"interventions":[{"type":"RADIATION","name":"Low-level laser auriculotherapy (LLLT-AT)"},{"type":"OTHER","name":"Sham Low-level laser auriculotherapy (sham LLLT-AT)"},{"type":"OTHER","name":"Myofascial release"}],"sponsor":"Quiropraxia y Equilibrio","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Hernán Andrés de la Barra Ortiz","title":"PhD.","affiliation":"Quiropraxia y Equilibrio"},"officials":[{"name":"Hernán A de la Barra, PhD.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Exercise and Rehabilitation Sciences Institute, School of Physical Therapy, Faculty of Rehabilitation Sciences, Universidad Andres Bello, Santiago 7591538, Chile"}],"countries":["Chile"],"sites":[{"facility":"Universidad Andrés Bello","city":"Santiago","country":"Chile"}],"n_sites":1,"outcome":"Pain pressure thereshold (PPT)","summary":"Summary:\n\nLow-level laser auriculotherapy (LLLT-AT) is a non-invasive technique that has gained attention for managing musculoskeletal pain and anxiety. Given the painful and emotional components of temporomandibular disorders (TMD), LLLT-AT may offer therapeutic benefits by stimulating auricular points associated with pain modulation and anxiety reduction. This randomized, placebo-controlled, two-arm clinical trial with blinded outcome assessors aims to evaluate the effects of LLLT-AT in individuals diagnosed with myogenic TMD (Axis I, Group I of the DC/TMD classification) and anxiety. The study will be conducted at the Physical Agents Laboratory of Universidad Andrés Bello. Eligible participants will include members of the university community with myogenic TMD (Axis I, Group I of the DC/TMD classification) and anxiety. Participants will be stratified by sex and randomly assigned to ei","updated":"2025-08-15","first_posted":"2025-08-15","type":"INTERVENTIONAL","ctx":"ATM","titre":"Laser-auriculothérapie dans la DTM myogène et l'anxiété"},{"nct":"NCT07753460","title":"Low-Level Laser Therapy in the Treatment of Trigger Finger","acronym":null,"status":"RECRUITING","phases":["NA"],"n":91,"start":"2025-08-07","end":"2026-12","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Trigger Finger","Stenosing Tenosynovitis","Trigger Digit"],"interventions":[{"type":"DEVICE","name":"Low Level Laser Therapy"},{"type":"DEVICE","name":"Sham Low Level Laser Therapy"}],"sponsor":"Dokuz Eylul University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Nihan ERDINC GUNDUZ","title":"assistant professor,MD","affiliation":"Dokuz Eylul University"},"officials":[{"name":"Elif Akalın, Prof, MD","role":"STUDY_CHAIR","affiliation":"Dokuz Eylul University"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Dokuz Eylul University","city":"Izmir","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Visual Analog Scale","summary":"Trigger finger, also known as stenosing tenosynovitis, is one of the most common disorders affecting the hand. Its lifetime prevalence is 2-3%. Patients typically present with locking of the affected finger during flexion and painful catching during extension. In mild cases, pain, swelling, and morning stiffness may be present without triggering. In more severe cases, the affected finger may become locked in flexion.\n\nConservative treatment methods, corticosteroid injections, and surgical interventions can be used in the treatment of trigger finger. Conservative treatment options include activity modification, splint immobilization, exercise programs, massage, physical therapy modalities including extracorporeal shock wave therapy and therapeutic ultrasound, and nonsteroidal anti-inflammatory drugs (NSAIDs). Splinting is an inexpensive and effective treatment option for trigger finger.\n\n","updated":"2026-09-30","first_posted":"2026-08-07","type":"INTERVENTIONAL","ctx":"tendon","titre":"Laser basse énergie contre sham dans le doigt à ressaut"},{"nct":"NCT07688915","title":"High-Intensity Laser Therapy Versus Transforaminal Epidural Steroid Injection in Chronic Lumbar Disc Herniation-Related Low Back and Radicular Pain","acronym":null,"status":"RECRUITING","phases":["NA"],"n":24,"start":"2025-08-01","end":"2026-10-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Lumbar Disc Herniation","Chronic Low Back Pain","Radicular Pain","Lumbar Radiculopathy"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy"},{"type":"PROCEDURE","name":"Transforaminal Epidural Steroid Injections"}],"sponsor":"Ankara City Hospital Bilkent","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Esra Ülgen Kıratlıoğlu","title":"MD","affiliation":"Ankara City Hospital Bilkent"},"officials":[],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Ankara Bilkent City Hospital, Physical Medicine and Rehabilitation Hospital","city":"Ankara","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Change in Low Back and Leg Pain Intensity Assessed by Visual Analog Scale","summary":"This prospective, randomized, single-blinded, controlled clinical trial aims to compare the effectiveness of high-intensity laser therapy and fluoroscopy-guided transforaminal epidural steroid injection in patients with chronic low back pain and lumbar radiculopathy. Eligible patients will be randomized into two parallel groups. One group will receive high-intensity laser therapy, and the other group will receive transforaminal epidural steroid injection. All participants will also receive a standardized home-based exercise program. Outcomes will be assessed at baseline, 2 weeks, 6 weeks, and 12 weeks after treatment. The primary outcome will be pain intensity measured by the Visual Analog Scale. Secondary outcomes will include functional disability, neuropathic pain symptoms, quality of life, and functional walking capacity.","updated":"2026-07-07","first_posted":"2026-07-07","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser haute intensité ou infiltration épidurale dans la radiculopathie par hernie lombaire"},{"nct":"NCT07084415","title":"Effect of Laser Acupuncture on Neck and Shoulder Pain in Lactating Women","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":44,"start":"2025-07-25","end":"2025-10-10","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Neck Pain"],"interventions":[{"type":"OTHER","name":"Postural correction exercise"},{"type":"DEVICE","name":"Laser acupuncture"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yara Mokhtar Abd El-Latif","title":"Principal investigator","affiliation":"Cairo University"},"officials":[{"name":"Hossam Hussein, Professor","role":"STUDY_DIRECTOR","affiliation":"Al-Azhar University"},{"name":"Doaa Osman, Professor","role":"STUDY_CHAIR","affiliation":"Cairo University"}],"countries":["Egypt"],"sites":[{"facility":"Yara Mokhtar Abd El-Latif","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Pain intensity","summary":"The purpose of this study is to investigate the effect of laser acupuncture on neck and shoulder pain in lactating women.","updated":"2025-07-24","first_posted":"2025-07-24","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser-acupuncture contre les douleurs de nuque et d'épaule de la femme allaitante"},{"nct":"NCT07078877","title":"Low-Level Laser Therapy in Knee Osteoarthritis: Effects on Clinical Outcomes, Femoral Cartilage Thickness and Regional Sarcopenia","acronym":null,"status":"RECRUITING","phases":["NA"],"n":62,"start":"2025-07-14","end":"2026-07","allocation":"RANDOMIZED","masking":"NONE","conditions":["Knee Osteoarthritis","Low Level Laser Therapy","Regional Sarcopenia","Exercise Theraphy"],"interventions":[{"type":"OTHER","name":"home based exercise"},{"type":"DEVICE","name":"Low Level Laser Therapy"}],"sponsor":"Ankara Etlik City Hospital","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":{"name":"IREM ADIGUZEL","title":"Dr","affiliation":"Ankara Etlik City Hospital"},"officials":[],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Ankara Etlik City Hospital","city":"Ankara","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"The Western Ontario and McMaster Universities Arthritis Index (WOMAC)","summary":"It was designed as a single-center, prospective, randomized controlled study. The study consists of two groups. Both groups of patients will receive a conventional home based exercise program.\n\nIn addition to the conventional exercise program, patients in the first group will also receive low-level laser therapy (LLLT). If the laser group is found to be superior at the end of the study, the patients who only received the exercise program will be recalled and administered LLLT. Patients who meet the inclusion criteria will be enrolled in the study.\n\nSample size calculations were based on data from a previous study by Alghadir et al. Using a mean of 3.25 and a standard deviation of 2.61 for the WOMAC pain subscale, the number of participants was calculated with 95% power and a 5% significance level. As a result, it was determined that at least 29 patients would be included in each group. W","updated":"2025-09-16","first_posted":"2025-07-22","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser basse énergie, cartilage fémoral et sensibilité dans la gonarthrose"},{"nct":"NCT06999239","title":"Evaluation of the Effect of Laser Therapy on Lateral Pterygoid Muscle in Patients With Wilke's Stage I and II Temporomandibular Disorders (TMD): Case Series Study","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":25,"start":"2025-07","end":"2026-07","allocation":"NA","masking":"NONE","conditions":["Laser","Temporomandibular Joint Disorders","Lateral Pterygoid Muscle"],"interventions":[{"type":"PROCEDURE","name":"laser therapy in TMD"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Aliaa ibrahim fathy","title":"doctor","affiliation":"Cairo University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Pain: will be obtained by Visual analogue scale (VAS).","summary":"The purpose of this study will be to evaluate the effect of laser therapy on lateral pterygoid muscle in patients with Wilke's stage I and II temporomandibular disorders (TMD).","updated":"2025-06-13","first_posted":"2025-05-31","type":"INTERVENTIONAL","ctx":"ATM","titre":"Laser sur le ptérygoïdien latéral dans les DTM de stade Wilkes I–II"},{"nct":"NCT07026617","title":"Low Level Laser Therapy and Rocabado's Approach for Myogenic TMJ Disorders","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":42,"start":"2025-06-20","end":"2025-09-20","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Myogenic Temporomandibular Joint Disorders"],"interventions":[{"type":"OTHER","name":"Rocabado's approach in addition to LLLT"},{"type":"OTHER","name":"control group"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Marwa Shafiek Mustafa Saleh","title":"assistance professor doctor","affiliation":"Cairo University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Assessment of Pain pressure threshold of masticatory muscles","summary":"Rocabado's 6x6 exercises are designed to improve muscular co-ordination, relax tense muscles, increase temporomandibular joint (TMJ) ROM, alter the jaw closure pattern and muscle strength. These exercises have been found to be beneficial in reducing pain and increasing masticatory muscle function, as well as restoring restricted joint mobility, muscle length limitation, and postural and functional limitations. In addition, low level laser therapy (LLLT) has been reported to reduce inflammation and pain in patients with TMJ dysfunction. Although that to the best of the authors' knowledge the combined effect of Rocabado's approach with LLLT has not been studied. So, the current study is the first double-blind placebo-controlled clinical trial that investigating the effect of adding LLLT to Rocabado's approach for TMJ myogenic disorders.","updated":"2025-06-18","first_posted":"2025-06-18","type":"INTERVENTIONAL","ctx":"ATM","titre":"Laser basse énergie et approche de Rocabado dans les DTM myogènes"},{"nct":"NCT04445545","title":"High Intensity Laser Therapy (HILT) on Myofascial Trigger Points.","acronym":"HILT","status":"RECRUITING","phases":["NA"],"n":24,"start":"2025-05-01","end":"2025-09-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Myofascial Trigger Point Pain (MTrP)"],"interventions":[{"type":"DEVICE","name":"High intensity laser therapy (HILT)"},{"type":"DEVICE","name":"Therapeutic Ultrasound (US)"},{"type":"PROCEDURE","name":"Stretching exercise"}],"sponsor":"Quiropraxia y Equilibrio","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Hernán A de la Barra Ortiz, Mg","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Universidad Nacional Andres Bello"}],"countries":["Chile"],"sites":[{"facility":"Universidad Andrés Bello","city":"Santiago","country":"Chile"},{"facility":"Universidad Andrés Bello","city":"Santiago","country":"Chile"}],"n_sites":2,"outcome":"Pain pressure thereshold (PPT)","summary":"The aim of the study is to evaluate the effects of HILT on cervical flexibility and pain reduction in myofascial trigger points. The research will be carried out in the Physiotherapy laboratory of Andrés Bello University. The participants will be civil servants and volunteer university students with the presence of latent MTrPs of the upper trapezius muscle. Participants will be randomized and divided into 3 study groups: group 1 (HILT and stretching exercises), group 2 (sham HILT and stretching exercises), and group 3 (the conventional US and stretching exercises). The treatments will be carried out twice a week for 4 weeks accompanied by 2 evaluations during the treatment and 1 post-treatment follow-up. The main result will be considered the differences in pain intensity (ΔPI), pain pressure threshold (ΔPPT), cervical spine range (ΔCROM), and cervical disability (ΔND) between the evalu","updated":"2025-08-07","first_posted":"2020-06-24","type":"INTERVENTIONAL","ctx":"fibro","titre":"Laser haute intensité sur les points gâchettes myofasciaux"},{"nct":"NCT06916650","title":"Comparing HILT, Steroid Injection, and Manual Therapy for Frozen Shoulder","acronym":null,"status":"RECRUITING","phases":["NA"],"n":180,"start":"2025-04-25","end":"2027-05-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Frozen Shoulder"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT)"},{"type":"DRUG","name":"Ultrasound-Guided Intra-articular Corticosteroid Injection"},{"type":"BEHAVIORAL","name":"Manual Therapy"},{"type":"BEHAVIORAL","name":"Standard Exercise Program"}],"sponsor":"Al Hayah University In Cairo","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Egypt"],"sites":[{"facility":"Faculty of Physical Therapy, Al Hayah University","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Change in Shoulder Pain Intensity","summary":"This study compares three common treatments for frozen shoulder when added to a standard exercise program: High-Intensity Laser Therapy (HILT), a corticosteroid (steroid) injection into the shoulder joint, and hands-on manual therapy by a physical therapist. A fourth group will receive only the standard exercise program. The goal is to see which combination works best to reduce shoulder pain and improve shoulder function over 6 months. The main outcomes are changes in pain (VAS scale) and shoulder disability (SPADI questionnaire) at 12 weeks.","updated":"2025-04-08","first_posted":"2025-04-08","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser haute intensité, infiltration ou thérapie manuelle dans l'épaule gelée"},{"nct":"NCT06916676","title":"HILT Dose Optimization for Knee Osteoarthritis Pain","acronym":null,"status":"RECRUITING","phases":["NA"],"n":140,"start":"2025-04-23","end":"2027-03-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Knee Osteoarthritis"],"interventions":[{"type":"DEVICE","name":"Low-Dose High-Intensity Laser Therapy (10 J/cm²)"},{"type":"DEVICE","name":"Medium-Dose High-Intensity Laser Therapy (15 J/cm²)"},{"type":"DEVICE","name":"High-Dose High-Intensity Laser Therapy (20 J/cm²)"},{"type":"DEVICE","name":"Sham High-Intensity Laser Therapy"}],"sponsor":"Al Hayah University In Cairo","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Egypt"],"sites":[{"facility":"Faculty of Physical Therapy, Al Hayah University","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Change in Knee Pain Intensity","summary":"This study aims to find the best settings (dose) for High-Intensity Laser Therapy (HILT) to reduce pain and improve function in people with moderate knee osteoarthritis. Participants will be randomly assigned to receive one of three different doses of HILT (low, medium, or high) or a sham (placebo) laser treatment, three times a week for four weeks. The main outcomes measured will be changes in knee pain (using a pain scale) and knee function (using a questionnaire) from the beginning to the end of the 4-week treatment period.","updated":"2025-04-08","first_posted":"2025-04-08","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Optimisation de la dose de laser haute intensité dans la gonarthrose"},{"nct":"NCT07196800","title":"Effect of Dose Variations of High-Power Laser Therapy on Patients With Nonspecific Cervical Pain","acronym":null,"status":"RECRUITING","phases":["NA"],"n":60,"start":"2025-03-10","end":"2025-11-10","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Neck Pain"],"interventions":[{"type":"RADIATION","name":"High intensity laser therapy (low dose) combined with conventional physiotherapy program"},{"type":"PROCEDURE","name":"High intensity laser therapy (High dose) combined with conventional physiotherapy program"}],"sponsor":"Deraya University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Egypt"],"sites":[{"facility":"Deraya university physiotherapy clinic","city":"Minya","country":"Egypt"}],"n_sites":1,"outcome":"Pain assessment","summary":"Nonspecific neck pain, defined as pain without a specific underlying pathology, is a common musculoskeletal disorder that affects a significant proportion of the global population. Neck pain often results in considerable discomfort and functional limitations, impacting individuals' quality of life and ability to perform daily tasks. Estimates suggest that up to 30% of adults experience neck pain annually. The condition ranks among the top causes of disability worldwide, contributing to substantial personal and societal burdens, including lost work productivity and increased healthcare costs.","updated":"2025-09-29","first_posted":"2025-09-29","type":"INTERVENTIONAL","ctx":"rachis","titre":"Dose de laser haute puissance dans la cervicalgie non spécifique"},{"nct":"NCT06790667","title":"Comparison of Low-Level Laser Therapy and Transcutaneous Electrical Nerve Stimulation for Myofascial Pain in Temporomandibular Disorders","acronym":null,"status":"NOT_YET_RECRUITING","phases":["PHASE2"],"n":40,"start":"2025-02-01","end":"2025-05-30","allocation":"RANDOMIZED","masking":"NONE","conditions":["Myofascial Temporomandibular Disorders"],"interventions":[{"type":"DEVICE","name":"Low Level Laser Therapy"},{"type":"DEVICE","name":"Transcutaneous Pulsed Electrical Stimulation (Device: Nu Eyne M02)"}],"sponsor":"University of Health Sciences Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"ARHUM BUTT","title":"Postgraduate Resident","affiliation":"University of Health Sciences Lahore"},"officials":[{"name":"Arhum Butt, Bachelor of Dental Surgery","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Health Sciences Lahore"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Pain Intensity (VAS Score)","summary":"Myofascial pain is the most common form of temporomandibular disorder (TMD) encountered in maxillofacial practice. Treatment options range from conservative management to open surgical procedures, with physical therapies identified as the safest and most effective. Among these, transcutaneous electrical nerve stimulation (TENS) is a widely used technique, while low-level laser therapy (LLLT) is a recent therapeutic advancement. This study is designed to compare the efficacy of these two therapies, aiming to identify the more effective option.","updated":"2025-01-24","first_posted":"2025-01-24","type":"INTERVENTIONAL","ctx":"ATM","titre":"Laser basse énergie ou TENS dans la douleur myofasciale des DTM"},{"nct":"NCT06773676","title":"Evaluating the Effectiveness of Using a Home Laser Device to Treat Patients With Knee Osteoarthritis","acronym":null,"status":"RECRUITING","phases":["NA"],"n":50,"start":"2025-01-14","end":"2026-01-31","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Osteoarthritis Of Knee"],"interventions":[{"type":"DEVICE","name":"B-Cure laser pro"},{"type":"DEVICE","name":"Sham"}],"sponsor":"Barzilai Medical Center","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Omri Lubovsky","title":"Head of Orthopedic Department","affiliation":"Barzilai Medical Center"},"officials":[{"name":"Omri Lubovsky, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Barzilai University Medical Center Ashkelon Israel"}],"countries":["Israel"],"sites":[{"facility":"Barzilai University Medical Center","city":"Ashkelon","country":"Israel"}],"n_sites":1,"outcome":"Change from baseline in level of pain by VAS","summary":"Osteoarthritis is a degenerative disease affecting joint cartilage and its surrounding tissue. It is the leading cause of disability in the elderly. Photobiomodulation (PBM), has been used widely for alleviation of pain, reduction of inflammation, and acceleration of wound healing, and particularly to treat knee osteoarthritis (KOA). The purpose of the current study is to determine if a near-infrared PBM device (B-Cure Laser), applied at home, by the patient or personal caregiver in a real-life situation, can reduce pain and improve functionality in patients with KOA.","updated":"2025-01-14","first_posted":"2025-01-14","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser à domicile (B-Cure) contre sham dans la gonarthrose"},{"nct":"NCT06762197","title":"Radial Shockwave Versus Low Level Laser Therapy in Patients With Chronic Piriformis Muscle Syndrome","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":63,"start":"2025-01-01","end":"2025-03-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Extracorporeal Shock Wave","Radial Shock Wave","Low Level Laser","Piriformis Muscle Syndrome"],"interventions":[{"type":"OTHER","name":"Conventional treatment"},{"type":"DEVICE","name":"shockwave therapy"},{"type":"DEVICE","name":"low level laser therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mohamed Mahdi Ali Ibrahim","title":"principal investigator","affiliation":"Cairo University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"out-patient clinic in physiotherapy department at EL KATEB Hospital","city":"Giza","country":"Egypt"}],"n_sites":1,"outcome":"Assessing the change of body mass index","summary":"The study aims to compare the effects of radiation shockwave and low-level laser therapy on piriformis muscle thickness, lower extremity function, pain intensity, and hip range of motion in patients with piriformis syndrome.","updated":"2025-01-07","first_posted":"2025-01-07","type":"INTERVENTIONAL","ctx":"rachis","titre":"Ondes de choc radiales ou laser basse énergie dans le syndrome du piriforme"},{"nct":"NCT06763419","title":"Internal Photobiomodulation For Management Of Temporomandibular Joint Internal Derangement","acronym":null,"status":"RECRUITING","phases":["NA"],"n":50,"start":"2024-12-25","end":"2025-02-28","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Temporomandibular Joint Disorders"],"interventions":[{"type":"DEVICE","name":"External low level laser therapy"},{"type":"DEVICE","name":"Internal low level laser therapy"}],"sponsor":"Nourhan M.Aly","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Nourhan M.Aly","title":"Assistant Lecturer of Dental Public Health","affiliation":"University of Alexandria"},"officials":[{"name":"Nermeen Rady, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Faculty of Dentistry, Alexandria University, Egypt"},{"name":"Mariam M Bahgat, PhD","role":"STUDY_CHAIR","affiliation":"Faculty of Dentistry, Alexandria University, Egypt"},{"name":"Aly Atteya, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Faculty of Dentistry, Alexandria University, Egypt"},{"name":"Hoda MA Abdel-Naby, PhD","role":"STUDY_DIRECTOR","affiliation":"Faculty of Medicine, Alexandria University, Egypt"}],"countries":["Egypt"],"sites":[{"facility":"Faculty of Dentistry","city":"Alexandria","country":"Egypt"}],"n_sites":1,"outcome":"Pain level assessment using Visual Analogue Scale","summary":"Aim of the study was to compare the efficacy of internal versus external photobiomodulation (PBM) in the management of patients with TMJ internal derangements (TMJ-ID).","updated":"2025-01-08","first_posted":"2025-01-08","type":"INTERVENTIONAL","ctx":"ATM","titre":"PBM interne ou externe dans le dérangement interne de l'ATM"},{"nct":"NCT06692998","title":"High and Low Level Laser Therapy in De Quervain's Tenosynovitis","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":40,"start":"2024-12-01","end":"2026-12-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["DeQuervain Tendinopathy"],"interventions":[{"type":"OTHER","name":"Rehabilitation"}],"sponsor":"Afyonkarahisar Health Sciences University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Sevda Adar","title":"Assistant Professor","affiliation":"Afyonkarahisar Health Sciences University"},"officials":[{"name":"SEVDA ADAR, Ass. Prof.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Afyonkarahisar Health Sciences University"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Afyonkarahisar Health Sciences University Health Application and Research Center Physical Medicine and Rehabilitation Clinic","city":"Afyonkarahisar","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Visual Pain Scale (VAS)","summary":"The aim in this study was to compare the effects of high and low power laser treatments in the treatment of de Quervein tenosynovitis clinically and ultrasonographically.","updated":"2026-11-05","first_posted":"2024-11-18","type":"INTERVENTIONAL","ctx":"tendon","titre":"Laser haute et basse énergie dans la ténosynovite de De Quervain"},{"nct":"NCT07102602","title":"Feasibility of Assessing Muscle Displacement and Muscle Excursion on Muscle Fatigue, With and Without Preventive Strategies","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":20,"start":"2024-11-30","end":"2025-02-25","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Muscle Fatigue"],"interventions":[{"type":"DEVICE","name":"high intensity laser therapy"},{"type":"DEVICE","name":"Sham laser therapy"}],"sponsor":"National Taiwan University Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Taiwan"],"sites":[{"facility":"National Taiwan University College of Medicine","city":"Taipei","country":"Taiwan"}],"n_sites":1,"outcome":"Muscle displacement","summary":"Study Subjects: This study will recruit healthy males aged 18 to 35 who regularly exercise for at least 2.5 hours per week.\n\nExpected Number of Participants: 20.\n\nMethods and Procedures: This trial will be randomized into two groups, Groups A and B, who will undergo two isokinetic concentric exercise sessions (fatiguing exercise) separated by 15 days. Group A will first receive a fatigue prevention strategy (high-energy laser) followed by a placebo-controlled no-fatigue strategy 15 days later. Group B will first receive a placebo-controlled no-fatigue strategy followed by a fatigue prevention strategy (high-energy laser) 15 days later. The fatigue prevention strategy involves irradiating the quadriceps femoris with a 900-joule high-intensity laser therapy (3-watt output power for 5 minutes) before the isokinetic concentric exercise. The no-fatigue strategy (sham-controlled) involves irra","updated":"2025-08-04","first_posted":"2025-08-04","type":"INTERVENTIONAL","ctx":"muscle","titre":"Laser haute intensité préventif et fatigue musculaire"},{"nct":"NCT06703775","title":"Low Level Laser Versus Neural Mobilization of Brachial Plexus on Shoulder Dysfunction Post Liver Donation","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":66,"start":"2024-11-26","end":"2025-01-26","allocation":"RANDOMIZED","masking":"NONE","conditions":["Shoulder Pain"],"interventions":[{"type":"OTHER","name":"Low level laser therapy (LLLT)"},{"type":"OTHER","name":"Neural mobilization techniques"},{"type":"OTHER","name":"Conventional physical therapy program"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Hayam Abd Elrazek Mohamed","title":"Principal Investigator","affiliation":"Cairo University"},"officials":[{"name":"Amal Mohamed Abd El-baky, PhD","role":"STUDY_CHAIR","affiliation":"Professor, Cairo university"}],"countries":["Egypt"],"sites":[{"facility":"faculty of physical therapy, Cairo University","city":"Giza","country":"Egypt"}],"n_sites":1,"outcome":"Arabic version of Shoulder Pain and Disability Index (SPADI)","summary":"The purpose of the study will be to compare therapeutic effect of low level laser versus neural mobilization techniques on shoulder dysfunction post liver donation.","updated":"2024-11-25","first_posted":"2024-11-25","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser basse énergie ou mobilisation neurale après don de foie"},{"nct":"NCT06654739","title":"RCT on the Performance and Safety of LightForce® Therapy Lasers on Knee Osteoarthritis Pain Reduction (SPARK)","acronym":"SPARK","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":64,"start":"2024-11-23","end":"2026-03-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Osteoarthritis of Knee"],"interventions":[{"type":"DEVICE","name":"Laser therapy + physiotherapy/exercise protocol"},{"type":"DEVICE","name":"Sham Laser therapy + physiotherapy/exercise protocol"}],"sponsor":"DJO UK Ltd","sponsor_class":"INDUSTRY","collaborators":["Donawa Lifescience Consulting S.r.l."],"responsible":null,"officials":[{"name":"Bernard Bonthoux, Physiotherap","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Cabinet d'Ostéopathie"}],"countries":["France","Italy","United Kingdom"],"sites":[{"facility":"Cabinet d'Ostéopathie","city":"Grésy-sur-Aix","country":"France"},{"facility":"Cabinet Allaire","city":"Le Havre","country":"France"},{"facility":"Casertafisio","city":"Caserta","country":"Italy"},{"facility":"Fisioterapia Carioni","city":"Milan","country":"Italy"},{"facility":"Fisioterapia EUR","city":"Roma","country":"Italy"},{"facility":"Fisioterapia Gardenie","city":"Roma","country":"Italy"},{"facility":"Indergaard Physiotherapy","city":"Leeds","country":"United Kingdom"}],"n_sites":7,"outcome":"Pain change","summary":"DJO UK Ltd (ENOVIS) is conducting this study to assess the effectiveness of LightForce® Therapy Lasers on pain reduction in subjects with unilateral or bilateral knee osteoarthritis. In detail this study will assess superiority of LightForce® Therapy Lasers combined with standard of care, represented by physiotherapy/exercise program compared to sham laser combined with standard of care (physiotherapy/exercise program) on pain reduction in subjects with knee osteoarthritis. In addition, this study allows to collect post market clinical data on the safety and performance of LightForce® Therapy Lasers, when used, following the normal clinical practice, in accordance with its approved and CE marked intended use.","updated":"2025-11-17","first_posted":"2024-10-23","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Essai SPARK : lasers LightForce contre sham dans la gonarthrose (France, Italie)"},{"nct":"NCT07163208","title":"Therapeutic Efficacy of Different Wavelengths of Low-Level Laser Therapy in the Treatment of Cervicogenic Headache","acronym":"WELL","status":"RECRUITING","phases":["NA"],"n":150,"start":"2024-09-05","end":"2025-09-30","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Cervicogenic Headache"],"interventions":[{"type":"DEVICE","name":"Low-Level Laser Therapy (LLLT)"},{"type":"OTHER","name":"Routine Physical Therapy (RPT)"}],"sponsor":"University of Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Arooj Munawar","title":"Principal Investigator","affiliation":"University of Lahore"},"officials":[{"name":"Umair Ahmed, PhD","role":"STUDY_DIRECTOR","affiliation":"University of Lahore, Lahore, Pakistan"}],"countries":["Pakistan"],"sites":[{"facility":"Department of Physiotherapy, Sir Ganga Ram Hospital","city":"Lahore","country":"Pakistan"}],"n_sites":1,"outcome":"Number of Participants with Reduction in Headache Frequency","summary":"This study tests if low-level laser therapy (LLLT) with different light wavelengths can help people with cervicogenic headache, a type of headache caused by neck problems. Adults aged 18-65 with this headache for at least 3 months will try one of three LLLT treatments (675nm, 820nm, or a mix of wavelengths) along with regular physical therapy like stretching and exercises. The study will check pain levels, how often headaches happen, neck movement, disability, and quality of life over 6 weeks, with follow-ups at 3 and 6 months. the investigators want to find the best LLLT option to reduce headache symptoms safely.","updated":"2025-09-19","first_posted":"2025-09-09","type":"INTERVENTIONAL","ctx":"rachis","titre":"Longueurs d'onde du laser basse énergie dans la céphalée cervicogénique"},{"nct":"NCT06426251","title":"Photobiomodulation Therapy in Patients Receiving Total Knee Arthroplasty","acronym":null,"status":"RECRUITING","phases":["NA"],"n":15,"start":"2024-05-20","end":"2027-09-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Inflammation","Osteoarthritis","Post Operative Pain"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"National Taiwan University Hospital Hsin-Chu Branch","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Hsiang-Chieh Hsieh","role":"STUDY_CHAIR","affiliation":"National Taiwan University Hospital Hsin-Chu Branch"}],"countries":["Taiwan"],"sites":[{"facility":"National Taiwan University Hospital, Hsin-Chu Branch","city":"Hsinchu","country":"Taiwan"}],"n_sites":1,"outcome":"the change of bioimpedance","summary":"Photobiomdoulation is the use of near-infrared light to relieve pain, stimulate healing and reduce inflammation. Swelling and inflammation is a common condition after orthopedics surgeries over extremity and spine. This study aim to evaluate the effect of photobiomodulation over patients after Total Knee Arthroplasty.","updated":"2024-05-29","first_posted":"2024-05-23","type":"INTERVENTIONAL","ctx":"arthrose","titre":"PBM après prothèse totale de genou"},{"nct":"NCT05689788","title":"High-intensity Laser Therapy for Neck Pain","acronym":null,"status":"RECRUITING","phases":["NA"],"n":72,"start":"2024-03-31","end":"2024-05-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Non-specific Chronic Neck Pain"],"interventions":[{"type":"DEVICE","name":"High-intensity laser therapy"},{"type":"PROCEDURE","name":"Stretching exercise"},{"type":"DEVICE","name":"Sham High-intensity laser therapy"}],"sponsor":"Quiropraxia y Equilibrio","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Hernán Andrés de la Barra Ortiz","title":"Professor","affiliation":"Universidad Nacional Andres Bello"},"officials":[{"name":"Hernán de la Barra Ortiz, MSc","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Universidad Nacional Andres Bello"}],"countries":["Chile"],"sites":[{"facility":"Universidad Andrés Bello","city":"Santiago","country":"Chile"},{"facility":"Hernán Andrés de la Barra","city":"Santiago","country":"Chile"}],"n_sites":2,"outcome":"Pain pressure thereshold (PPT)","summary":"Chronic nonspecific neck pain is a common musculoskeletal disorder recognized for its high rates of disability and economic losses, ranking second in musculoskeletal conditions after low back pain. There are several effective physical therapy interventions to treat chronic nonspecific neck pain, such as laser therapy. High-intensity laser therapy (HILT) is a recent treatment proposed to reduce musculoskeletal pain; however, there are few studies that prove its effects in reducing neck pain.\n\nThe aim of this randomized clinical trial is to evaluate the effect of high-intensity laser therapy on pain intensity in patients with chronic nonspecific neck pain.\n\nThe research will be carried out in the laboratory of physical agents at the Andrés Bello University, Campus Casona de las Condes. Participants will be employers and volunteer students with non-specific chronic neck pain. Participants w","updated":"2025-08-07","first_posted":"2023-01-19","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser haute intensité contre sham dans la cervicalgie"},{"nct":"NCT06732570","title":"Effect of High Intensity Laser on Shoulder Impingement.","acronym":"lasershoulder","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":40,"start":"2024-02-18","end":"2026-06-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["High Intensity Laser","Shoulder Impingement Syndrome","Shoulder Pain"],"interventions":[{"type":"DEVICE","name":"high intensity laser"},{"type":"OTHER","name":"manual therapy"},{"type":"OTHER","name":"exercise therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Abd Elkhalek Mansour Ahmed","title":"physical therapist, Al Azhar university hospital, MSC, DPT","affiliation":"Cairo University"},"officials":[{"name":"Abd ELkhalek Mansour Ahmed, MSC, DPT","role":"STUDY_DIRECTOR","affiliation":"physical therapist, Al Azhar university hospital, Sayed Galal hospital"},{"name":"Khaled Ahmed olama, professor","role":"STUDY_DIRECTOR","affiliation":"Physical Therapy, Department for Physical Therapy for pediatrics Faculty of Physical Therapy Cairo University"},{"name":"mohamed Ali Elshafey, professor","role":"STUDY_DIRECTOR","affiliation":"Physical Therapy, Department for Physical Therapy for pediatrics Faculty of Physical Therapy Cairo University"},{"name":"hatem Mohamed El-Azizi, professor","role":"STUDY_DIRECTOR","affiliation":"Radiology Department, Faculty of Medicine, Cairo University"}],"countries":["Egypt"],"sites":[{"facility":"Cairo University","city":"Giza","country":"Egypt"}],"n_sites":1,"outcome":"Acromio-humeral distance (AHD) and Coraco-humeral distance (CHD).","summary":"Treatment for shoulder impingement is conservative initially, Rehabilitation programs generally consist of exercise therapy and manual therapy that provide relief from symptoms of impingement. High-intensity laser therapy used recently and was found to be effective in the short term in the treatment of pain and disability in patients with impingement.\n\nThis study aims to\n\n* Investigate the effect of high intensity power laser therapy on sonographic measurement in the adolescent suffering from shoulder impingement syndrome.\n* Investigate the effect of high intensity power laser therapy on pain in the adolescent suffering from shoulder impingement syndrome.\n* Investigate the effect of high intensity power laser therapy on shoulder function in the adolescent suffering from shoulder impingement syndrome.\n\nRESEARCH QUESTION:\n\nDoes using high intensity power laser affects shoulder dysfunction ","updated":"2024-12-13","first_posted":"2024-12-13","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser haute intensité dans le conflit de l'épaule"},{"nct":"NCT06007976","title":"LLLT to Reduce Low Back Pain","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":60,"start":"2024-02-16","end":"2026-12","allocation":"NON_RANDOMIZED","masking":"NONE","conditions":["Low Back Pain"],"interventions":[{"type":"DEVICE","name":"Erchonia® Trident"}],"sponsor":"Mayo Clinic","sponsor_class":"OTHER","collaborators":["Erchonia Corporation"],"responsible":{"name":"Ivana T Croghan, PhD","title":"Principal Investigator","affiliation":"Mayo Clinic"},"officials":[{"name":"Ivana T Croghan, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Mayo Clinic"},{"name":"Ryan T Hurt, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Mayo Clinic"}],"countries":["United States"],"sites":[{"facility":"Mayo Clinic","city":"Rochester","country":"United States"}],"n_sites":1,"outcome":"Change in Brief Pain Inventory score","summary":"The purpose of this research study is to gather information on the effectiveness of the Trident low-level laser therapy (LLLT) in combination with clinical patient education manuals to reduce lower back pain.","updated":"2026-11-02","first_posted":"2023-08-23","type":"INTERVENTIONAL","ctx":"rachis","titre":"Laser basse énergie (Erchonia Trident) dans la lombalgie"},{"nct":"NCT05916235","title":"Photobiomodulation for Management of Temporomandibular Disorder Pain","acronym":"ULLTRA","status":"RECRUITING","phases":["NA"],"n":130,"start":"2024-02-08","end":"2028-10","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Pain Related to TMD"],"interventions":[{"type":"DEVICE","name":"THOR® laser system"}],"sponsor":"University of Florida","sponsor_class":"OTHER","collaborators":["National Institute of Dental and Craniofacial Research (NIDCR)"],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"University of Florida","city":"Gainesville","country":"United States"}],"n_sites":1,"outcome":"Pain Level Change with PBM treatment using a Numerical Rating Scale","summary":"Photobiomodulation (PBM), is FDA-approved for temporary relief of muscle and joint pain, but there is no indication for TMD. Our goal in this study is to conduct a clinical trial of multimodal PBM for TMD pain. This study will be a double-blind, sham-controlled, randomized trial testing the efficacy of PBM for pain related to TMD.","updated":"2026-11-06","first_posted":"2023-06-23","type":"INTERVENTIONAL","ctx":"ATM","titre":"PBM (laser THOR) contre la douleur des troubles temporo-mandibulaires"},{"nct":"NCT05816798","title":"Photobiomodulation in Chronic Knee Pain in Patients Who Are in PreRehabilitation for Bariatric Surgery","acronym":null,"status":"RECRUITING","phases":["PHASE2","PHASE3"],"n":62,"start":"2023-07-28","end":"2025-05-01","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Chronic Knee Pain","Obesity, Morbid"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"OTHER","name":"Standard Physiotherapy Tretament"},{"type":"DEVICE","name":"Photobiomodulation Placebo"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":["Universidade Federal de Goias"],"responsible":{"name":"Rebeca Boltes Cecatto","title":"MD., PhD. Researcher","affiliation":"University of Nove de Julho"},"officials":[{"name":"Rebeca B Cecatto, MD PHD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Nove de Julho University"}],"countries":["Brazil"],"sites":[{"facility":"Gastric Outpatient Clinic of HC-UFG","city":"Goiânia","country":"Brazil"}],"n_sites":1,"outcome":"Visual Analog Scale Change","summary":"Chronic pain is a global public health problem, which intensifies even more in the obese population, reaching about 33% of these patients. Among the topography, chronic knee pain affects 80%, constituting an important cause of disability and decreased quality of life. In addition, in grade 3 obesity, also called morbid obesity, in which bariatric surgery is already indicated, knee pain makes it difficult or prevents participation in the pre-habilitation program that includes physical therapy through therapeutic exercises with the aim of reducing postoperative complications. In this sense, a double-blind, randomized, placebo-controlled clinical trial will be conducted with the objective of evaluating the effect of photobiomodulation (PBM) on pain and functionality of obese patients with chronic knee pain who are in a prehabilitation program for bariatric surgery, discussing its role as an","updated":"2025-06-06","first_posted":"2023-04-18","type":"INTERVENTIONAL","ctx":"arthrose","titre":"PBM et douleur chronique du genou avant chirurgie bariatrique"},{"nct":"NCT06282770","title":"Photobiomodulation for Lower Back Pain Post Spinal Fusion and Decompression Surgery","acronym":null,"status":"RECRUITING","phases":["NA"],"n":80,"start":"2023-07-01","end":"2026-06-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Spinal Fusion","Chronic Lower Back Pain"],"interventions":[{"type":"DEVICE","name":"Laser Diode Brace"},{"type":"DEVICE","name":"Sham Laser Diode Brace"}],"sponsor":"University of California, Los Angeles","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Daniel Lu, MD, PhD","title":"Neurosurgeon","affiliation":"University of California, Los Angeles"},"officials":[{"name":"Sara K Chung, PA","role":"STUDY_DIRECTOR","affiliation":"University of California, Los Angeles"},{"name":"Sandra M Holley, PhD","role":"STUDY_DIRECTOR","affiliation":"University of California, Los Angeles"},{"name":"Sichen Li, PhD","role":"STUDY_DIRECTOR","affiliation":"University of California, Los Angeles"},{"name":"Adreanne Rivera, BS","role":"STUDY_DIRECTOR","affiliation":"University of California, Los Angeles"}],"countries":["United States"],"sites":[{"facility":"Semel Institute of Neuroscience at UCLA","city":"Los Angeles","country":"United States"},{"facility":"UCLA Clinical and Translational Research Center","city":"Los Angeles","country":"United States"}],"n_sites":2,"outcome":"Self-reported patient outcome questionnaires after photobiomodulation therapy - VAS","summary":"After spinal fusion and decompression surgery there is a possible risk of developing chronic back pain. After surgery there is typically inflammation around the operation site and this inflammation can be painful and debilitating to patients.\n\nMany possible treatment plans have been incorporated to assist the patient with recovery - notably medications, physical therapy, and braces. However, few studies have looked at laser diodes that utilize high-power laser lights that are aimed at decreasing pain and inflammation. Investigators aim to look compare patients using a back brace with laser diodes within versus those who wear a normal brace used as a placebo. Investigators will also assess the patient's surgical wound to monitor the progression of wound healing while using the brace.","updated":"2026-01-13","first_posted":"2024-02-28","type":"INTERVENTIONAL","ctx":"rachis","titre":"Ceinture à diodes laser contre sham après arthrodèse ou décompression lombaire"},{"nct":"NCT05596474","title":"Effect of Beet-root Juice and PBM Treatments on Muscle Fatigue","acronym":null,"status":"RECRUITING","phases":["NA"],"n":10,"start":"2022-09-09","end":"2024-08-31","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Health Care Utilization","Healthy Aging"],"interventions":[{"type":"DIETARY_SUPPLEMENT","name":"Beet-root juice"},{"type":"RADIATION","name":"red-light therapy"},{"type":"DIETARY_SUPPLEMENT","name":"Placebo"},{"type":"RADIATION","name":"sham light"}],"sponsor":"Wake Forest University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Andrew Wells, Ph.D","title":"Principal Investigator","affiliation":"Wake Forest University"},"officials":[{"name":"Andrew D Wells, Ph.D.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Wake Forest University, Reynolda Campus"}],"countries":["United States"],"sites":[{"facility":"Wake Forest Univesity","city":"Winston-Salem","country":"United States"}],"n_sites":1,"outcome":"Total forearm work performed","summary":"The goal of this randomized counterbalanced repeated measures study is to test beet-root juice supplementation and red light therapy augment forearm muscle endurance in apparently healthy older adults over 65 years of age. The main questions seek to answer the following question:\n\nDoes beet-root juice supplementation improve forearm muscle endurance compared to a placebo supplement?\n\nDoes red light therapy improve forearm muscle endurance compared to a sham light exposure?\n\nDoes beet-root juice supplementation in combination with red light therapy improve forearm muscle endurance compared to a placebo-sham light control?","updated":"2024-03-20","first_posted":"2022-10-27","type":"INTERVENTIONAL","ctx":"muscle","titre":"Jus de betterave et lumière rouge contre la fatigue musculaire"},{"nct":"NCT05328401","title":"To Evaluate the Therapeutic Effect of Laser Acupuncture in Patients With Acute or Subacute Post Stroke Shoulder Pain","acronym":null,"status":"RECRUITING","phases":["NA"],"n":58,"start":"2022-04-16","end":"2028-03-15","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Post Stroke Shoulder Pain"],"interventions":[{"type":"DEVICE","name":"Verum laser acupuncture"},{"type":"DEVICE","name":"Sham laser acupuncture"}],"sponsor":"Chang Gung Memorial Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Yu Wei Chang","role":"STUDY_DIRECTOR","affiliation":"Chang Gung Medical Foundation"}],"countries":["Taiwan"],"sites":[{"facility":"Chang Gung Memorial Hospital, Keelung Medical Center","city":"Keelung","country":"Taiwan"}],"n_sites":1,"outcome":"Passive range of motion of shoulder","summary":"Investigators propose a research design protocol to evaluate the efficacy of laser acupuncture in improving shoulder pain and improving shoulder function recovery after stroke.","updated":"2026-03-06","first_posted":"2022-04-14","type":"INTERVENTIONAL","ctx":"épaule","titre":"Laser-acupuncture contre sham dans l'épaule douloureuse après AVC"},{"nct":"NCT07108400","title":"Efficacy of a Combination of Ultrasound-guided Intra-articular Injections of Hyaluronic Acid, High-power Laser Therapy and Rehabilitation on Functioning in Patients Affected by Hip Osteoarthritis.","acronym":null,"status":"RECRUITING","phases":["NA"],"n":57,"start":"2022-03-17","end":"2025-08-03","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Hip Osteoarthritis"],"interventions":[{"type":"PROCEDURE","name":"ultrasound-guided injections of hyaluronic acid plus high-power laser therapy"},{"type":"PROCEDURE","name":"ultrasound-guided injections of hyaluronic acid plus sham\" high-power laser therapy"}],"sponsor":"De Sire Alessandro","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"De Sire Alessandro","title":"professor","affiliation":"University of Catanzaro"},"officials":[],"countries":["Italy"],"sites":[{"facility":"University \"Magna Graecia \"of Catanzaro","city":"Catanzaro","country":"Italy"},{"facility":"University \"Magna Graecia \"of Catanzaro","city":"Catanzaro","country":"Italy"}],"n_sites":2,"outcome":"the Harris Hip Score (HHS)","summary":"High-power laser therapy (HPLT) is effective in treating musculoskeletal conditions, reducing pain and improving joint functionality. This randomized controlled trial (RCT) aimed to explore the effectiveness of a combination of HPLT, hyaluronic acid injections, and rehabilitation for patients with hip osteoarthritis.","updated":"2025-08-07","first_posted":"2025-08-07","type":"INTERVENTIONAL","ctx":"arthrose","titre":"Laser haute puissance, acide hyaluronique et rééducation dans la coxarthrose"}],"mucite-orale":[{"nct":"NCT06623305","title":"A Clinical Trial of the Administration of Light Therapy to Prevent Mouth Sores in Children With Cancer","acronym":"PBM","status":"NOT_YET_RECRUITING","phases":["NA"],"n":50,"start":"2026-11","end":"2027-11","allocation":"RANDOMIZED","masking":"NONE","conditions":["Mucositis Oral"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation for prevention arm"},{"type":"DEVICE","name":"Photobiomodulation for exploratory arm"}],"sponsor":"Medical College of Wisconsin","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Elissa Shulta","title":"Principal Investigator","affiliation":"Medical College of Wisconsin"},"officials":[],"countries":["United States"],"sites":[{"facility":"Medical College of Wisconsin","city":"Milwaukee","country":"United States"}],"n_sites":1,"outcome":"Evaluate the feasibility of using PBM in pediatric oncology patients.","summary":"The goal of this clinical trial is to learn if light therapy can prevent mouth sores in children with cancer. The main questions it aims to answer are:\n\nIs it reasonable and acceptable to provide light therapy for children with cancer?\n\nDoes light therapy prevent mouth sores related to medical treatment?\n\nResearchers will compare children who do not receive light therapy to children who do receive light therapy during the clinical trial to see if light therapy helps to prevent mucositis.\n\nParticipants will:\n\n* Complete a survey.\n* Have picture taken of their mouth to look for mouth sores.\n* Receive light therapy every day while admitted to the hospital on the cancer unit or while admitted to an alternate unit, and continue to receive light therapy in the home setting until they reach 8 days after the start of their chemotherapy cycle.","updated":"2026-10-06","first_posted":"2024-10-02","type":"INTERVENTIONAL","ctx":"chimio","titre":"PBM pour prévenir la mucite chez l'enfant atteint de cancer"},{"nct":"NCT07865780","title":"Photobiomodulation Alone Versus Photobiomodulation Combined With Topical Oral Oxygen Therapy for Radiotherapy-Induced Oral Mucositis in Head and Neck Cancer Patients: A Randomized Clinical Trial","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["PHASE1","PHASE2"],"n":46,"start":"2026-08-15","end":"2026-09-20","allocation":"RANDOMIZED","masking":"NONE","conditions":["Mucositis Oral","Head & Neck Cancer"],"interventions":[{"type":"DEVICE","name":"sirolase xtent laser"},{"type":"DRUG","name":"blue m gel"}],"sponsor":"Assiut University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Nashwa Helaly Mohamed","title":"Lecturer","affiliation":"Assiut University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"faculty of dentistry Assiut University","city":"Asyut","country":"Egypt"}],"n_sites":1,"outcome":"Incidence of WHO grade","summary":"Oral mucositis is the inflammation and ulceration of the mucous membranes within the oral cavity, characterized by atrophy, edema, and erythema (1), and it occurs in nearly all patients with advanced head and neck cancer (HNC) receiving chemotherapy and radiotherapy \\[2,3\\]. It can seriously disrupt a person's life, affecting both quality of life and the course of treatment (2).\n\nIdentifying the optimal management for oral mucositis remains a significant clinical challenge. Therapeutic modalities such as photobiomodulation (PBM) and benzydamine have shown beneficial effects in reducing mucosal injury and accelerating healing (3). In addition, maintaining proper oral hygiene and using adjunctive therapeutic agents can help minimize mucositis severity. Advanced interventions, including low-level laser therapy and optimized radiation delivery techniques like Intensity-Modulated Radiotherapy","updated":"2026-10-08","first_posted":"2026-10-08","type":"INTERVENTIONAL","ctx":"ORL","titre":"PBM seule ou avec oxygénothérapie buccale dans la mucite radio-induite"},{"nct":"NCT06458517","title":"Evaluation of Two Methods of Administration of Photobiomodulation in the Context of the Prevention and Treatment of Mucositis Induced by Radiotherapy, During the Treatment of Head and Neck Cancers","acronym":"RADIO-PBM","status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-06-15","end":"2029-11-15","allocation":"RANDOMIZED","masking":"NONE","conditions":["Head and Neck Neoplasms"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation session - intraoral"},{"type":"DEVICE","name":"Photobiomodulation session - transcutaneous"}],"sponsor":"Centre Paul Strauss","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Jordan EBER, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Institut de cancérologie Strasbourg Europe"}],"countries":["France"],"sites":[{"facility":"Institut de cancérologie Strasbourg Europe","city":"Strasbourg","country":"France"}],"n_sites":1,"outcome":"Cumulative incidence of oral mucositis (grade ≥ 2) in both group (intraoral and transcutaneous PBM)","summary":"The aim of this feasibility, prospective, single-center trial is to compare an intra-oral Photobiomodulation (PBM) via the Caremin650TM device (NeoMedLight) and a transcutaneous PBM via the ATP 38® device (Swiss Bio Innov) in patients treated with radiotherapy or chemoradiotherapy for cancer of the oropharynx or oral cavity. PBM session will be carried out first at the rate of two sessions per week for preventive purposes, and then, in case of occurence of grade 1 mucositis, three sessions per week with curative purpose.","updated":"2026-06-05","first_posted":"2024-06-13","type":"INTERVENTIONAL","ctx":"chimio","titre":"PBM intrabuccale ou transcutanée contre la mucite (France)"},{"nct":"NCT07605234","title":"Phase II Single Arm Open Label Study Evaluating the Feasibility and Safety of Photobiomodulation as an Adjunct to Standard Supportive Care for Chemotherapy Induced Oral Mucositis in Pediatric Patients With Hematolymphoid Malignancies","acronym":"BEAM","status":"NOT_YET_RECRUITING","phases":["NA"],"n":46,"start":"2026-06-01","end":"2027-03-23","allocation":"NA","masking":"NONE","conditions":["Oral Mucositis Due to Chemotherapy","Hematolymphoid Malignancies"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation Therapy"}],"sponsor":"Tata Memorial Hospital","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":{"name":"Sandeep Gurav","title":"OIC Department of Dental ad Prosthetic Surgery, TMH Parel, Mumbai","affiliation":"Tata Memorial Hospital"},"officials":[{"name":"Sandeep Gurav","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Tata Memorial Hospital, Parel"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Feasibility of Photobiomodulation Therapy","summary":"Chemotherapy induced oral mucositis is a common and debilitating complication in pediatric patients receiving chemotherapy for hematolymphoid malignancies. Oral mucositis can cause painful mouth ulcers, difficulty in eating and drinking, impaired nutrition, increased risk of infection, and significant discomfort. In severe cases, oral mucositis may lead to interruptions, delays, or dose modifications in chemotherapy, which can negatively affect cancer treatment outcomes and quality of life. Current management of chemotherapy induced oral mucositis is mainly supportive and includes maintenance of oral hygiene, bland mouth rinses, topical anesthetics, systemic analgesics, antimicrobial therapy when indicated, and nutritional support. However, these measures do not consistently promote healing of the oral mucosa or reduce the duration and severity of oral mucositis.\n\nPhotobiomodulation ther","updated":"2026-05-22","first_posted":"2026-05-22","type":"INTERVENTIONAL","ctx":"chimio","titre":"PBM en complément des soins chez l'enfant sous chimiothérapie : faisabilité et sécurité"},{"nct":"NCT07183267","title":"Using Red Light Therapy to Ease Skin Side Effects and Mouth Side Effects, in Children and Young People Aged 0 to 16 Years Old, Receiving Radiotherapy","acronym":"RADIANT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":248,"start":"2026-06-01","end":"2028-06-01","allocation":"NA","masking":"NONE","conditions":["Radio Dermatitis","Mucositis Oral","Oesophagitis"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"The Christie NHS Foundation Trust","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Ed Smith","role":"STUDY_DIRECTOR","affiliation":"The Christie NHS Foundation Trust"}],"countries":["United Kingdom"],"sites":[{"facility":"The Christie NHS Foundation Trust","city":"Manchester","country":"United Kingdom"}],"n_sites":1,"outcome":"Number of Paediatric Participants with Treatment-Related Skin Toxicity as Assessed by RTOG","summary":"The goal of this interventional study is to see if the daily use of red light therapy called photobiomodulation can help sore skin and sore mouths in children having radiotherapy.\n\nAll children aged 0-16 years old who are receiving either proton or photon radiotherapy treatment, except to the brain only, will be asked if they would like to join the study.\n\nThe main questions it aims to answer are:\n\n1. Does the use of red light therapy help the skin side effects in children and young people undergoing proton or photon therapy?\n2. Does the use of red light therapy help the mouth side effects in children and young people undergoing proton or photon therapy in the head and neck area?\n\nResearchers will compare the patients enrolled on to the study with a like for like historic patient to see if red light therapy improves the sore skin and sore mouths caused by proton or photon therapy.\n\nParti","updated":"2026-03-19","first_posted":"2025-09-19","type":"INTERVENTIONAL","ctx":"chimio","titre":"Lumière rouge contre les effets cutanés et buccaux des traitements chez l'enfant de 0 à 16 ans"},{"nct":"NCT07810530","title":"Study of a Copaiba-Based Mouthwash Combined With Low-Level Laser Therapy in the Prevention of Oral Mucositis in Patients Undergoing Hematopoietic Stem Cell Transplantation","acronym":null,"status":"RECRUITING","phases":["PHASE2"],"n":76,"start":"2026-03-29","end":"2027-11","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Oral Mucositis","Oral Mucositis (Ulcerative) Due to Antineoplastic Therapy","Oral Mucositis Due to Chemotherapy","Oral Mucositis in Patients Undergoing HSCT"],"interventions":[{"type":"DRUG","name":"Copaíba"},{"type":"DRUG","name":"Placebo"}],"sponsor":"Instituto Nacional de Cancer, Brazil","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":null,"officials":[{"name":"Héliton Spíndola, PhD","role":"STUDY_DIRECTOR","affiliation":"Instituto Nacional de Cancer"}],"countries":["Brazil"],"sites":[{"facility":"Instituto Nacional de Cancer, Brazil","city":"Rio de Janeiro","country":"Brazil"}],"n_sites":1,"outcome":"Safety and efficacy evaluation through adverse event related to the use of the product (Common Terminology Criteria for Adverse Events v5.0 and the Visual Analogic Scale)","summary":"Oral mucositis (OM) one of the most significant acute toxicity of Hematopoietic Stem Cell Transplantation (HSCT). There is already scientific evidence suporting OM the use of: low-level laser therapy (LLLT), cryotherapy (in autologous HSCT when conditioning regimens include high-dose melphalan), and keratinocyte growth factor (in autologous HSCT with high-dose chemotherapy associated with RT). In this sense, an alternative treatment becomes necessary. Based on the preliminary results of the phase I study, a double-blind, randomized phase II study is suggested to evaluate the effectiveness of copaiba-based mouthwash in the prevention of oral mucositis in HSCT was proposed. Patients will be randomized into 2 groups: A (copaíba) and B (placebo) and will use the mouthwash 4x/day. Each group will have 38 patients and be blind to the group in which they are included. They will be evaluated dai","updated":"2026-09-09","first_posted":"2026-09-09","type":"INTERVENTIONAL","ctx":"ORL","titre":"Bain de bouche au copaïba associé au laser pour prévenir la mucite"},{"nct":"NCT07372443","title":"Photobiomodulation in the Prevention and Management of Oral Mucositis in Children","acronym":"PBMOM-PEDMX","status":"NOT_YET_RECRUITING","phases":["NA"],"n":49,"start":"2026-01","end":"2027-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Oral Mucositis","Chemotherapy Effect","Pediatric Cancer"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"DRUG","name":"bioadhesive gel"}],"sponsor":"Universidad de Guanajuato","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mariana Paulina Rodríguez Vargas","title":"Principal Investigator","affiliation":"Universidad de Guanajuato"},"officials":[{"name":"María C Palacios, PhD","role":"STUDY_DIRECTOR","affiliation":"Universidad de Guanajuato"}],"countries":[],"sites":[],"n_sites":0,"outcome":"Oral mucositis grade","summary":"Oral mucositis (OM) is a frequent, debilitating complication in pediatric oncology that impairs quality of life, nutrition, hydration, and treatment adherence. This randomized, prospective, single blind trial in Mexico will evaluate photobiomodulation (PBM) versus a conventional bioadhesive gel for prevention and treatment of antineoplastic therapy-induced OM in children aged 4-17 with leukemia, lymphoma, or head and neck tumors. A total of 49 participants will be enrolled. The study has two components: (1) Treatment - parallel comparison of PBM versus bioadhesive gel for established OM; (2) Prevention - crossover design in which patients receive both interventions across successive chemotherapy cycles. PBM will be delivered with a 660 nm device, 40 mW, 10 J/cm². The primary outcome is OM grade by the WHO scale assessed on days 7, 11, 14, and 21. Expected results include reduced OM incid","updated":"2026-01-28","first_posted":"2026-01-28","type":"INTERVENTIONAL","ctx":"chimio","titre":"PBM ou gel bioadhésif contre la mucite de l'enfant"},{"nct":"NCT07387978","title":"A Study to Describe the Effect of Photobiomodulation (Low Level Laser Therapy) in Reducing the Severity and Incidence of Oral Mucositis (Oral Ulceration) in Oral Cancer Patients Undergoing Radiation Treatment","acronym":"PBM","status":"RECRUITING","phases":["NA"],"n":30,"start":"2025-11-26","end":"2028-11","allocation":"NA","masking":"NONE","conditions":["Oral Mucositis"],"interventions":[{"type":"DEVICE","name":"photobiomodulation"}],"sponsor":"Peter MacCallum Cancer Centre, Australia","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Australia"],"sites":[{"facility":"Peter MacCallum Cancer Centre","city":"Melbourne","country":"Australia"}],"n_sites":1,"outcome":"Cumulative incidence and severity of acute oral mucositis","summary":"The goal of this study is to describe the effect of photobiomodulation (PBM) on the incidence and severity of oral mucositis in post-operative oral cancer patients receiving radiotherapy +/- chemotherapy.\n\nParticipants will receive PBM treatment five times a week throughout the course of their radiotherapy.\n\nThe main question it aims to answer is whether photobiomodulation reduces the incidence and severity of oral mucositis.","updated":"2026-02-04","first_posted":"2026-02-04","type":"INTERVENTIONAL","ctx":"ORL","titre":"PBM et mucite après chirurgie d'un cancer de la bouche puis radiothérapie"},{"nct":"NCT07436650","title":"Efficacy of High-Level Laser Therapy in Managing Oral Mucositis Among Pediatric Patients Undergoing Hematopoietic Stem Cell Transplantation","acronym":null,"status":"RECRUITING","phases":["NA"],"n":14,"start":"2025-06-15","end":"2030-08","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Oral Mucositis"],"interventions":[{"type":"DEVICE","name":"high power laser therapy"},{"type":"DRUG","name":"Basic oral care"}],"sponsor":"Ain Shams University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Asmaa Ayman Mohammed Gabr","title":"Teaching Assistant","affiliation":"Ain Shams University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Oncology and Bone marrow transplant unit, Children's hospital, Ain Shams University","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Oral mucositis score","summary":"The goal of this clinical trial is to learn if high-level laser therapy can manage oral mucositis in pediatric patients undergoing hematopoietic bone marrow transplantation. The main question it aims to answer is :\n\nIs high-level laser therapy effective as a treatment for oral mucositis in pediatric hemopoietic stem cell transplant patients? Researchers will compare patients receiving basic oral care to see the effect on the WHO oral mucositis scale.\n\nParticipants will be subjected to high level laser on lesion sites .","updated":"2026-03-19","first_posted":"2026-02-27","type":"INTERVENTIONAL","ctx":"CSH","titre":"Laser haute puissance contre la mucite de l'enfant greffé de CSH"},{"nct":"NCT06625619","title":"On the BRINK: PhotoBiomodulation (PBM) for Mucositis in Patients Undergoing Allogeneic Hematopoietic Stem Cell TRansplant (HSCT) - Implementing the Evidence & Discovering New Knowledge","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":[],"n":6,"start":"2024-10-07","end":"2026-11-24","allocation":null,"masking":null,"conditions":["Hematopoietic and Lymphatic System Neoplasm","Malignant Solid Neoplasm"],"interventions":[{"type":"OTHER","name":"Non-Interventional Study"}],"sponsor":"City of Hope Medical Center","sponsor_class":"OTHER","collaborators":["National Cancer Institute (NCI)"],"responsible":null,"officials":[{"name":"Annette Isozaki, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"City of Hope Medical Center"}],"countries":["United States"],"sites":[{"facility":"City of Hope Medical Center","city":"Duarte","country":"United States"}],"n_sites":1,"outcome":"Mucositis according to the World Health Organization (WHO) Scale","summary":"This study evaluates mucositis and other oral symptoms in patients undergoing photobiomodulation in patients undergoing hematopoietic stem cell transplantation.","updated":"2026-01-28","first_posted":"2024-10-03","type":"OBSERVATIONAL","ctx":"CSH","titre":"Étude BRINK : PBM de la mucite en allogreffe de CSH"},{"nct":"NCT06071637","title":"Low Power Laser Therapy As Prevention Of Oral Mucositis And Oropharyngeal Pain In Patients Undergoing Allogenetic HSCT","acronym":null,"status":"RECRUITING","phases":["PHASE3"],"n":84,"start":"2023-08-01","end":"2026-07-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Hematopoietic Stem Cell Transplantation","Low-Level Light Therapy","Stomatitis"],"interventions":[{"type":"PROCEDURE","name":"Double low-power laser therapy simultaneous applicated"}],"sponsor":"Instituto Nacional de Cancer, Brazil","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":null,"officials":[],"countries":["Brazil"],"sites":[{"facility":"Instituto Nacional de Cancer","city":"Rio de Janeiro","country":"Brazil"},{"facility":"Instituto Nacional de Cancer","city":"Rio de Janeiro","country":"Brazil"}],"n_sites":2,"outcome":"Prevention of oral mucositis according to WHO and OMAS scale","summary":"Objective: To compare the effects of two low-power laser therapy protocols (application of a wavelength in the mouth, red region and another in the neck infrared region X simultaneous dual application of two wavelengths, red and infrared region in the mouth and neck) in the prevention of oral mucositis and oropharyngeal pain, dysphagia, TPN and opioid use in patients undergoing HSCT allogenic.\n\nMaterials and methods: This is a phase III, double-blind, randomized study that will use LBP to prevent oral mucositis and oropharyngeal pain in two protocols with different dosimetry (divided into Group A and Group B). Patients will be included enrolled at the Bone Marrow Transplant Center - Cancer Hospital I - INCA, with indication of allogeneic HSCT, over 18 years old, able to cooperate with the treatment and perform the oral hygiene protocol, who present oral mucosa complete on the first day o","updated":"2023-10-06","first_posted":"2023-10-06","type":"INTERVENTIONAL","ctx":"CSH","titre":"Double laser basse puissance contre la mucite et la douleur oropharyngée en allogreffe"},{"nct":"NCT04671862","title":"Photobiomodulation for the Prevention of Radiation Induced Oral Mucositis","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":25,"start":"2021-06-01","end":"2026-12-31","allocation":"NA","masking":"NONE","conditions":["Mucositis Oral","Head and Neck Cancer","Radiation Dermatitis"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"Ottawa Hospital Research Institute","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Canada"],"sites":[{"facility":"The Ottawa Hospital","city":"Ottawa","country":"Canada"}],"n_sites":1,"outcome":"Rate of occurence of radiation mucositis","summary":"Radiotherapy for head and neck cancer can cause severe mucositis (ulcers in the mouth) and pain. Photobiomodulation (Light therapy) will be used before and during radiotherapy to try to reduce the occurence and severity of mucositis in patients treated with radiotherapy for head and neck cancer\n\nPrevious studies in head and neck cancer patients have shown that photobiomodulation (light therapy) can prevent mucositis. There are currently no centers in Canada using this technique in routine practice, but this is recommended in International guidelines and widely used in Europe. The investigators therefore wish to implement this technique in Ottawa under the umbrella of a clinical trial to insure its safety and efficacy in a Canadian context.","updated":"2026-10-19","first_posted":"2020-12-17","type":"INTERVENTIONAL","ctx":"ORL","titre":"PBM pour prévenir la mucite radio-induite"},{"nct":"NCT03983369","title":"Low-level Laser Therapy in the Prevention of Chemotherapy-induced Mucositis in Children and Young Adults","acronym":"MUCILA","status":"RECRUITING","phases":["PHASE3"],"n":315,"start":"2018-08-29","end":"2026-08-28","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Mucositis Oral"],"interventions":[{"type":"DEVICE","name":"Low-Level Laser Therapy"},{"type":"OTHER","name":"Placebo"}],"sponsor":"Gustave Roussy, Cancer Campus, Grand Paris","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["France"],"sites":[{"facility":"Gustave Roussy","city":"Villejuif","country":"France"},{"facility":"Centre Oscar Lambret","city":"Lille","country":"France"},{"facility":"Hôpital Robert Debré","city":"Paris","country":"France"},{"facility":"Institut Curie","city":"Paris","country":"France"},{"facility":"CHU de Rennes","city":"Rennes","country":"France"}],"n_sites":5,"outcome":"Proportion of grade 3-4 mucositis","summary":"To assess the efficacy of preventive Low-Level Laser Therapy (LLLT) for reducing the incidence of WHO's grade 3-4 oral mucositis in children and young adults receiving chemotherapy regimens associated with a high rate of mucositis: conventional chemotherapy or High Dose Chemotherapy (HDC) conditioning regimens with Hematological Stem Cell Transplantation (HSCT).","updated":"2026-02-06","first_posted":"2019-06-12","type":"INTERVENTIONAL","ctx":"chimio","titre":"Laser basse énergie pour prévenir la mucite chimio-induite de l'enfant et du jeune adulte (France)"}],"odontologie":[{"nct":"NCT07886723","title":"Photobiomodulation After Nonsurgical Root Canal Treatment","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-10-19","end":"2027-05-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Symptomatic Apical Periodontitis","Postoperative Pain","Mechanical Allodynia"],"interventions":[{"type":"DEVICE","name":"Adjunctive Photobiomodulation"},{"type":"DEVICE","name":"Sham Photobiomodulation"}],"sponsor":"University of Minnesota","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Ronald Ordinola-Zapata","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Minnesota"}],"countries":["United States"],"sites":[{"facility":"University of Minnesota School of Dentistry Graduate Endodontic Clinic","city":"Minneapolis","country":"United States"}],"n_sites":1,"outcome":"Change in Mechanical Allodynia Measured by Maximum Occlusal Force Difference","summary":"This randomized, double-blind controlled clinical trial will evaluate whether adjunctive photobiomodulation improves recovery after nonsurgical root canal treatment in adults with teeth diagnosed with symptomatic apical periodontitis.\n\nParticipants will receive standard nonsurgical root canal treatment and will be randomized to adjunctive photobiomodulation using the Fotona LightWalker Nd:YAG laser or to an identical simulated laser procedure without laser energy delivery.\n\nThe study will evaluate mechanical allodynia using maximum occlusal force measurements comparing the treated tooth with the contralateral asymptomatic tooth. Postoperative pain will also be assessed using the Numeric Rating Scale after percussion testing.","updated":"2026-10-21","first_posted":"2026-10-21","type":"INTERVENTIONAL","ctx":"endo","titre":"PBM contre sham après traitement canalaire d'une parodontite apicale symptomatique : douleur et allodynie"},{"nct":"NCT07795073","title":"Acceleration of Tooth Movement Using PRP and Photobiomodulation With Clear Aligners","acronym":null,"status":"NOT_YET_RECRUITING","phases":["PHASE1","PHASE2"],"n":42,"start":"2026-09-01","end":"2027-04-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Orthodontic Tooth Movement"],"interventions":[{"type":"BIOLOGICAL","name":"Platelet Rich Plasma (PRP) injection"},{"type":"DEVICE","name":"photobiomodulation (PBM) Therapy"},{"type":"DEVICE","name":"clear aligner(12-hour wear protocol)"},{"type":"DEVICE","name":"Clear aligner(22-hour wear protocol)"}],"sponsor":"Sana'a University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Arij Lutf Abdulrhman Abdul Majid","title":"PhD student","affiliation":"Sana'a University"},"officials":[{"name":"Arij L Abdulmajid, MSc","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Sanaa University"}],"countries":["Yemen"],"sites":[{"facility":"Faculty of Dentistry Sanaa university","city":"Sanaa","country":"Yemen"}],"n_sites":1,"outcome":"Rate of clinical tooth movement via intraoral digital scans","summary":"This study compares the effectiveness of two adjunct therapies- photobiomodulation (low-level laser therapy) (PBM) and localized platelet-rich plasma (PRP) injections in accelerating orthodontic tooth movement. Participants receiving clear aligner therapy will be randomly assigned to one of three groups: clear aligners with PBM, clear aligners with PRP, or clear aligners alone (control group). The goal is to evaluate the efficiency, tooth movement tracking and safety.","updated":"2026-08-31","first_posted":"2026-08-31","type":"INTERVENTIONAL","ctx":"ortho","titre":"PRP et photobiomodulation pour accélérer le déplacement dentaire sous aligneurs"},{"nct":"NCT07658235","title":"Micro-osteoperforation Versus Photobiomodulation Therapy for Accelerating Maxillary Canine Retraction","acronym":"MOP-PBMT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":75,"start":"2026-07-01","end":"2027-03-28","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Malocclusion","Orthodontic Tooth Movement","Maxillary Canine Retraction"],"interventions":[{"type":"PROCEDURE","name":"Micro-osteoperforation (MOP)"},{"type":"DEVICE","name":"Photobiomodulation Therapy using 976 nm Diode Laser"},{"type":"OTHER","name":"Conventional orthodontic canine retraction"}],"sponsor":"Kufa University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Almustafa Alhumadi","title":"lecturer","affiliation":"Kufa University"},"officials":[],"countries":["Iraq"],"sites":[{"facility":"University of Kufa College of Dentistry","city":"Najaf","country":"Iraq"}],"n_sites":1,"outcome":"Rate of maxillary canine retraction","summary":"Orthodontic treatment often requires moving the upper canine teeth (the pointed teeth) into the spaces left after removing premolar teeth. This process is usually slow and can take many months, making the total treatment time longer.This study will compare two techniques that may speed up this tooth movement:\n\nMicro-osteoperforation (MOP): A minimally invasive procedure in which a small device is used to create tiny holes in the jawbone near the canine tooth under local anesthesia. These micro-perforations stimulate the bone to remodel faster, which allows the tooth to move more quickly.\n\nPhotobiomodulation therapy (PBMT) / Low-Level Laser Therapy (LLLT): A painless, non-invasive technique that uses a low-power laser light applied to the gum tissue near the canine tooth. The laser energy stimulates cells in the bone and supporting tissues to accelerate tooth movement without any cutting ","updated":"2026-06-18","first_posted":"2026-06-18","type":"INTERVENTIONAL","ctx":"ortho","titre":"Micro-ostéoperforations contre PBM 976 nm pour accélérer la rétraction de la canine maxillaire"},{"nct":"NCT07591948","title":"The Effect of Low-Level Laser Therapy on Accelerating Tooth Movement and Reducing Pain During Orthodontic Treatment","acronym":"LLLT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":30,"start":"2026-06-02","end":"2028-02-02","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Acceleration of Tooth Movement"],"interventions":[{"type":"PROCEDURE","name":"Low level laser therapy"}],"sponsor":"Sana'a University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Faris Mohammed Ali Aljobur","title":"Principal Investigator","affiliation":"Sana'a University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"tooth movement measurement","summary":"Orthodontic treatment is a common and effective approach to correcting dental malocclusions and improving oral function and aesthetics. The process involves applying mechanical forces to move teeth into their desired positions, which can lead to discomfort and pain for patients, especially during the initial stages of treatment. While the ultimate goal of orthodontic therapy is to achieve proper alignment, the associated pain and the time required to complete the treatment often become significant concerns for patients. (Jheon et al., 2017). The duration of treatment, which typically spans several months or even years, is influenced by various factors including the type of malocclusion, the force applied, and the biological response of the periodontal tissues to the applied forces. (Sangle et al., 2023). Recent advancements in orthodontic care have focused on finding ways to accelerate t","updated":"2026-05-18","first_posted":"2026-05-18","type":"INTERVENTIONAL","ctx":"ortho","titre":"Laser basse énergie pour accélérer le déplacement dentaire et réduire la douleur orthodontique"},{"nct":"NCT07626580","title":"Comparison of Rate of Tooth Movement Between MOPs vs MOPs & LLLT Combined","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":33,"start":"2026-06","end":"2026-09","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Orthodontic Tooth Movement","Low Level Laser Therapy","Canine Retraction"],"interventions":[{"type":"OTHER","name":"Micro-osteoperforation"},{"type":"DEVICE","name":"Low Level Laser Therapy and Micro-osteoperforations Combined"}],"sponsor":"Riphah International University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Ulfat Bashir","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Riphah International University"}],"countries":["Pakistan"],"sites":[{"facility":"Islamic International Dental Hospital","city":"Islamabad","country":"Pakistan"}],"n_sites":1,"outcome":"Rate of Tooth Movement","summary":"Orthodontic treatment is often prolonged, requiring years to achieve desirable outcomes. The prolonged duration of treatment increases the risk of complications such as root resorption, periodontal damage, and patient non-compliance.\n\nTo address these concerns, various methods have been explored to accelerate orthodontic tooth movement, including pharmacological agents, mechanical vibration, corticotomies, and minimally invasive techniques like Micro-Osteoperforations (MOPs) and Low-Level Laser Therapy (LLLT). Micro-Osteoperforations (MOPs) have gained popularity as a minimally invasive technique that enhances bone remodeling by inducing a localized inflammatory response, thereby accelerating tooth movement.\n\nStudies have shown that MOPs can effectively stimulate the expression of cytokines, increasing osteoclastic activity and facilitating rapid orthodontic tooth movement. However, the ","updated":"2026-06-04","first_posted":"2026-06-04","type":"INTERVENTIONAL","ctx":"ortho","titre":"Micro-ostéoperforations seules ou associées au laser basse énergie : vitesse de rétraction canine"},{"nct":"NCT07379515","title":"Effects of Topical Anesthesia Approaches on Dental Pain During and After Restorative Management of Dental Caries","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":204,"start":"2026-04-15","end":"2026-07-31","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Pulpitis","Pain Management"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation (PBM)-induced analgesia device using multi-wavelength LED"},{"type":"OTHER","name":"Medicated analgesia"},{"type":"OTHER","name":"Placebo"}],"sponsor":"Dubai Health","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":{"name":"Sameeha Husain Al Marzooqi","title":"Consultant","affiliation":"Dubai Health"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Pain score after local anesthesia administration, dental procedure, and 48 hours postoperatively.","summary":"The purpose of the Research Study and Overview of Participation: This study will compare different approaches used to prevent pain when giving local anesthesia to numb the teeth while managing dental cavities and decay. Specifically, it seeks to determine which approach will reduce the pain and discomfort during or after the procedure. This will help dentists to choose the best approach to reduce patient's pain and discomfort and improve the overall experience of dental treatment.\n\nParticipants in the study would likely undergo the following:\n\n1. Screening and Consent: Participants would be assessed for eligibility (e.g., age, health status, and presence of dental caries requiring treatment) and would provide informed consent.\n2. Intervention: Participants would be randomly assigned to different groups based on the type or method of topical anesthesia being tested.\n3. Treatment Procedure","updated":"2026-04-13","first_posted":"2026-01-30","type":"INTERVENTIONAL","ctx":"anesthésie","titre":"Analgésie par photobiomodulation contre anesthésie topique médicamenteuse lors des soins de caries"},{"nct":"NCT07449169","title":"Diode Laser Plus CPP-ACPF vs CPP-ACPF Alone for Dentin Hypersensitivity","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":70,"start":"2026-04-01","end":"2027-06-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Dentin Hypersensitivity","Tooth Hypersensitivity"],"interventions":[{"type":"DEVICE","name":"Diode laser photobiomodulation combined with CPP-ACPF varnish"},{"type":"OTHER","name":"CPP-ACPF varnish"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mariam Mamdouh Mohamed Kamal","title":"Dentist","affiliation":"Cairo University"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Reduction in dentin hypersensitivity in response to evaporative (air-blast) stimulus","summary":"This study aims to compare the effectiveness of diode laser photobiomodulation combined with CPP-ACPF varnish versus CPP-ACPF varnish alone in reducing dentin hypersensitivity. Participants diagnosed with dentin hypersensitivity will receive either the combined treatment or varnish application alone. Pain levels will be evaluated using a standardized visual analog scale before and after treatment sessions. The results of this study may help determine whether adding diode laser therapy enhances the effectiveness of conventional varnish treatment in managing dentin hypersensitivity.","updated":"2026-03-04","first_posted":"2026-03-04","type":"INTERVENTIONAL","ctx":"hypersensibilité","titre":"Laser diode associé au vernis CPP-ACPF contre vernis seul dans l'hypersensibilité dentinaire"},{"nct":"NCT07466641","title":"LLLLT vs Piezocision in Accelerating Orthodontic Canine Retraction","acronym":null,"status":"RECRUITING","phases":["NA"],"n":21,"start":"2026-04-01","end":"2027-02","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Malocclusion, Angle Class II, Division 1","Bimaxillary Protrusion","Class I Malocclusion"],"interventions":[{"type":"PROCEDURE","name":"Low Level Laser Therapy"},{"type":"PROCEDURE","name":"Piezocision"}],"sponsor":"Hesham Nabil Ali Al-Qamhawy","sponsor_class":"OTHER","collaborators":["Al-Azhar University"],"responsible":{"name":"Hesham Nabil Ali Al-Qamhawy","title":"Principal Investigator","affiliation":"Al-Azhar University"},"officials":[{"name":"Farouk A Hussein, Professor","role":"STUDY_CHAIR","affiliation":"Professor in Orthodontics; Faculty of Dental Medicine, Boys, Cairo; Al-Azhar University"}],"countries":["Egypt"],"sites":[{"facility":"Outpatient Clinics of the Department of Orthodontics, Faculty of Dental Medicine, Boys, Cairo, Al-Azhar University.","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Rate of canine retraction","summary":"This comparative controlled clinical study aims to evaluate and compare the effectiveness of piezocision and low-level laser therapy (LLLT) as adjunctive interventions to accelerate orthodontic canine retraction. Participants will be randomly assigned to one of three groups: piezocision, LLLT, or a control group (no adjunctive procedure). The study will assess the impact of these interventions on the rate of tooth movement, the type of tooth movement, and patient experience.","updated":"2026-05-11","first_posted":"2026-03-12","type":"INTERVENTIONAL","ctx":"ortho","titre":"Laser basse énergie contre piézocision pour accélérer la rétraction canine"},{"nct":"NCT07747350","title":"Comparison Between the Effectiveness of Low-Grade Laser Therapy vs. Conventional Analgesics for Pain Reduction During Orthodontic Treatment in Malay Female Population","acronym":"LLTvsANALG","status":"RECRUITING","phases":["NA"],"n":30,"start":"2026-02-01","end":"2026-02-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Orthodontic Pain"],"interventions":[{"type":"DEVICE","name":"Low-Level Laser Therapy (LLLT)"},{"type":"DRUG","name":"Conventional Analgesic (Paracetamol)"}],"sponsor":"ROA RAAD FADHEL","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"ROA RAAD FADHEL","title":"dentist","affiliation":"Universiti Sains Malaysia"},"officials":[],"countries":["Malaysia"],"sites":[{"facility":"School of Dental Sciences Universiti Sains Malaysia","city":"Kota Bharu","country":"Malaysia"}],"n_sites":1,"outcome":"Pain Intensity Score","summary":"All patients will be treated using the fixed appliance on the upper and lower arches.\n\n0.014\" Niti(Nickel-Titanium) archwire is used to ensure all patients will receive the same force.\n\nAll participants will receive a pain diary. In the pain diary, they are required to complete a KAP(Knowledge, Attitudes, and Practices) questionnaire regarding pain before the procedure. They are also required to record the pain VAS (Visual Analog Scale) score at different times (before procedure, 6 hours, 12 hours, 24 hours, 3 days, 5 days and 7 days after procedure). For PCM (Paracetamol) 650mg group, 1 tablet will be given 1 hour before the procedure and every 6 hours for 24 hours (5 doses in total) as pain begins two hours after activation, peak at 24 hours and reduces after two days . Paracetamol if taken more than 4g per day may cause serious liver damage. United State of Food and Drugs Administrati","updated":"2026-08-07","first_posted":"2026-08-05","type":"INTERVENTIONAL","ctx":"ortho","titre":"Laser basse énergie contre paracétamol pour la douleur orthodontique"},{"nct":"NCT07810699","title":"Diode Laser Versus LED for Maxillary Canine Retraction in Orthodontic Patients","acronym":null,"status":"RECRUITING","phases":["NA"],"n":34,"start":"2026-01-03","end":"2027-07","allocation":"NON_RANDOMIZED","masking":"NONE","conditions":["Malocclusion Class I"],"interventions":[{"type":"DEVICE","name":"Diode Laser Photobiomodulation"},{"type":"DEVICE","name":"LED Photobiomodulation"}],"sponsor":"Can Tho University of Medicine and Pharmacy","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Vietnam"],"sites":[{"facility":"Saigon Dental Clinic - Dr. Lam","city":"Can Tho","country":"Vietnam"}],"n_sites":1,"outcome":"Amount of Maxillary Canine Retraction","summary":"This study aims to compare the effects of diode laser and light-emitting diode (LED) photobiomodulation on maxillary canine retraction during fixed orthodontic treatment. Participants requiring bilateral maxillary first premolar extraction will receive both interventions using a split-mouth design. One maxillary canine will receive diode laser photobiomodulation, while the contralateral maxillary canine will receive LED photobiomodulation.\n\nMaxillary canine movement will be evaluated at 4, 8, 12, and 16 weeks during retraction to compare the amount and rate of tooth movement between the two interventions. Pain associated with orthodontic tooth movement will also be assessed.\n\nPulp oxygen saturation (SpO₂) of the maxillary canines will be measured to evaluate changes in pulpal oxygenation during orthodontic canine retraction. SpO₂ will be assessed at baseline and at predefined follow-up t","updated":"2026-09-09","first_posted":"2026-09-09","type":"INTERVENTIONAL","ctx":"ortho","titre":"Laser diode contre LED pour la rétraction de la canine maxillaire"},{"nct":"NCT07286474","title":"Effects of Laser Therapy and Vitamin D Pills on Braces Tooth Movement: A Random Controlled Study","acronym":"LLLT","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":50,"start":"2026-01-01","end":"2026-10-31","allocation":"RANDOMIZED","masking":"NONE","conditions":["Malocclusion of Anterior Teeth"],"interventions":[{"type":"DIETARY_SUPPLEMENT","name":"Cholecalciferol (Vit D3)"},{"type":"RADIATION","name":"Low-Level Laser Therapy"},{"type":"DEVICE","name":"Fixed Orthodontic Appliance"}],"sponsor":"Universiti Sains Malaysia","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Syed Abid Altaf Bukhari","title":"PhD Student","affiliation":"Universiti Sains Malaysia"},"officials":[{"name":"Rozita Hassan, BDS, MS, MOrtho RCSEd","role":"STUDY_DIRECTOR","affiliation":"Universiti Sains Malayisa"}],"countries":["Saudi Arabia"],"sites":[{"facility":"Armed Forces Hospital","city":"Madinah","country":"Saudi Arabia"}],"n_sites":1,"outcome":"Rate of Orthodontic Tooth Movement","summary":"This clinical trial aims to evaluate the efficacy of low-level laser therapy (LLLT) in conjunction with oral vitamin D3 supplementation in accelerating orthodontic tooth movement in adults with crowded mandibular anterior teeth undergoing orthodontic treatment. Additionally, the study seeks to assess the safety profile and potential adverse effects, including pain and root resorption.\n\nThe primary research questions are as follows:\n\n1. Does vitamin D3 enhance the rate of orthodontic tooth movement?\n2. Does the combination of vitamin D3 and LLLT result in a greater acceleration of tooth movement compared to either intervention alone?\n3. Do vitamin D3 and LLLT influence the extent of root resorption?\n4. Do vitamin D3 and LLLT mitigate pain associated with orthodontic treatment?\n5. Do vitamin D3 and LLLT reduce the frequency of required clinical visits?\n\nThe study will compare the outcomes ","updated":"2026-04-28","first_posted":"2025-12-16","type":"INTERVENTIONAL","ctx":"ortho","titre":"Laser basse énergie et vitamine D sur le déplacement dentaire sous appareil fixe"},{"nct":"NCT07558720","title":"Effect of Diode Laser and 20% Benzocaine Anesthetic Gel on Pain Reduction Following Tooth Separation With Elastomeric Separators in Fixed Orthodontic Patients: A Randomized Trial in Karachi-Pakistan","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":72,"start":"2025-12-01","end":"2026-04","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["We Are Not Studying a Disease or Condition","Pain Reduction"],"interventions":[{"type":"OTHER","name":"Laser"},{"type":"OTHER","name":"Benzocaine 20%"}],"sponsor":"Dow University of Health Sciences","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Muhammad Ashfaq","title":"Docter","affiliation":"Dow University of Health Sciences"},"officials":[],"countries":["Pakistan"],"sites":[{"facility":"Dow Dental College","city":"Karachi","country":"Pakistan"}],"n_sites":1,"outcome":"mean difference in pain scores","summary":"The goal of this clinical trial is to learn if low level laser therapy works equivalent to benzocaine in reducing the pain caused by separators in fixed orthodontic treatment. The main questions it aims to answer are:\n\nIs there any difference in mean pain scores with Low Level Laser Therapy (LLLT) and 20% Benzocaine anesthetic gel of patients receiving elastomeric separators in fixed orthodontic treatment?\n\nResearchers will compare low level laser therapy to benzoaine gel to evaluate reduction in pain\n\nParticipants will be applied low level laser at the appointment of separator placement and patient himself will apply benzocaine gel thrice daily at the site of separator placement. patient will use placebo on the other side. Gel and placebo would be applied for one month.\n\nPatient will take the gel for 7 days.","updated":"2026-04-30","first_posted":"2026-04-30","type":"INTERVENTIONAL","ctx":"ortho","titre":"Laser diode contre gel de benzocaïne pour la douleur des séparateurs orthodontiques"},{"nct":"NCT06691269","title":"Photobiomodulation and Tooth Analgesia","acronym":null,"status":"RECRUITING","phases":["NA"],"n":200,"start":"2025-07-07","end":"2027-06","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Dental Anaesthesia","Dental Pain","Dental Analgesia"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"DRUG","name":"Topical Benzocaine"},{"type":"DRUG","name":"Local Anesthesia"}],"sponsor":"University of Maryland, Baltimore","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"University of Maryland School of Dentistry, Pediatric Clinics","city":"Baltimore","country":"United States"}],"n_sites":1,"outcome":"Study 1- Response to Cold Pulp (Pulp sensibility) testing","summary":"The purpose of this study is to test photobiomodulation (PBM) with a non-invasive light device for reducing discomfort during dental treatments in children. We plan to conduct a series of three clinical studies in 200 school-aged children requiring routine dental treatment. The first study aims to test if PBM works for tooth and soft tissue by assessing response to cold testing and probing of gums. The second study aims to test if use of PBM on soft tissues before injection reduces discomfort. The third study aims to test if PBM can be used to do simple dental fillings in baby teeth without numbing injection.","updated":"2026-08-12","first_posted":"2024-11-15","type":"INTERVENTIONAL","ctx":"anesthésie","titre":"Photobiomodulation contre benzocaïne topique et anesthésie locale pour l'analgésie dentaire"},{"nct":"NCT07013162","title":"Efficacy of Laser Therapy for Periodontitis","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":21,"start":"2025-07-01","end":"2026-06-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Periodontal Disease"],"interventions":[{"type":"PROCEDURE","name":"High power diode laser + SRT"},{"type":"PROCEDURE","name":"Low diode diode laser + SRT"},{"type":"PROCEDURE","name":"Curettage (SRT) only"}],"sponsor":"University of Science and Technology, Yemen","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Amani Abdulhakeem Alsharani","title":"Assistant Lecturer and principal investigator","affiliation":"University of Science and Technology, Yemen"},"officials":[{"name":"Waddah N Al-Hajj, Assoc prof","role":"STUDY_CHAIR","affiliation":"Faculty of dentistry -Thamar university"}],"countries":["Yemen"],"sites":[{"facility":"University of Science and Technology Dental Clinic","city":"Sanaa","country":"Yemen"},{"facility":"University of Science and Technology Dental Clinic","city":"Sanaa","country":"Yemen"}],"n_sites":2,"outcome":"Plaque Index (PI)","summary":"The aim of this study is to evaluate the efficacy of diode laser in addition to periodontal treatment in periodontitis patients and to investigate their effects on gingival crevicular fluid (GCF) cytokine levels before and after treatment, among some Yemeni individuals in Sana'a city.","updated":"2026-05-07","first_posted":"2025-06-10","type":"INTERVENTIONAL","ctx":"paro","titre":"Laser diode haute ou basse puissance en complément du surfaçage dans la parodontite"},{"nct":"NCT07018531","title":"Vertical Soft Tissue Augmentation With Tent Pole Technique and Its Influence on Marginal Bone Loss Around Dental Implants","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":112,"start":"2025-07","end":"2026-06","allocation":"RANDOMIZED","masking":"NONE","conditions":["Soft Tissue Augmentation Around Dental Implants"],"interventions":[{"type":"PROCEDURE","name":"VST augmentation with TPT"},{"type":"PROCEDURE","name":"TPT-PRF"},{"type":"PROCEDURE","name":"TPT-PBM"},{"type":"PROCEDURE","name":"Group control: implant placement without TPT"}],"sponsor":"University of Santiago de Compostela","sponsor_class":"OTHER","collaborators":["Galimplant Dental Implants"],"responsible":{"name":"Mario Pérez Sayáns","title":"Full Professor in Oral Medicine, Oral Surgery and Implantology, Faculty of Dental Medicine, University of Santiago de Compostela","affiliation":"University of Santiago de Compostela"},"officials":[],"countries":["Spain","Tunisia"],"sites":[{"facility":"Oral Medicine, Oral Surgery and Implantology Unit (Medoralres), Faculty of Medicine and Dentistry, University of Santiago de Compostela","city":"Santiago de Compostela","country":"Spain"},{"facility":"Oral Health and Oral Rehabilitation Research Laboratory, LR12ES11, Faculty of Dental Medecine of Monastir, University of Monastir","city":"Monastir","country":"Tunisia"}],"n_sites":2,"outcome":"vertical soft tissue height","summary":"This study aims to evaluate the effectiveness of the tent pole technique in vertical peri-implant soft tissue augmentation and to assess its impact on marginal bone loss. Additionally, the adjunctive use of platelet-rich fibrin and photobiomodulation will be explored to determine their influence on the clinical outcomes of this procedure.","updated":"2025-06-17","first_posted":"2025-06-12","type":"INTERVENTIONAL","ctx":"implants","titre":"Augmentation verticale des tissus mous autour des implants : technique tent-pole avec PRF ou PBM"},{"nct":"NCT06538142","title":"Photobiomodulation and New Restorative Material for Teeth With MIH on Control of Hypersensitivity and Longevity","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":100,"start":"2025-04-01","end":"2026-04-01","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Hypomineralization Molar Incisor","Hypersensitivity Dentin"],"interventions":[{"type":"PROCEDURE","name":"Photobiomodulation + Restoration with Self-cure Composite Resin"},{"type":"PROCEDURE","name":"Restoration with Self-cure Composite Resin"},{"type":"PROCEDURE","name":"Photobiomodulation + Restoration with Photopolymerizable Bulk-fill Composite Resin"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Sandra Kalil Bussadori","title":"Principal Investigator","affiliation":"University of Nove de Julho"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Hypersensitivity Assessment","summary":"Introduction: Molar incisor hypomineralization (MIH) is a qualitative defect of enamel development that occurs in the mineralization phase. MIH affects one or more permanent molars and, occasionally, permanent incisors.\n\nObjective: The aim of the proposed study is to determine whether photobiomodulation combined with a new self-cure resin improves hypersensitivity in molars with MIH and caries (primary outcome). Secondary outcomes include assessing the clinical performance of the self-cure composite resin in terms of restoration longevity and comparing the effectiveness of three interventions-photobiomodulation combined with self-cure resin, self-cure resin alone, and photobiomodulation combined with bulkfill photopolymerizable resin-in controlling hypersensitivity over time.\n\nMethods and analysis: Permanent molars with MIH in patients eight to 12 years of age will be allocated to three ","updated":"2025-01-22","first_posted":"2024-08-05","type":"INTERVENTIONAL","ctx":"hypersensibilité","titre":"Photobiomodulation et nouveau matériau de restauration dans les MIH hypersensibles"},{"nct":"NCT06639009","title":"Effect of Laser Photobiomodulation in Improving Mouth Opening in Oral Submucous Fibrosis","acronym":"OSMFPBMT","status":"RECRUITING","phases":["NA"],"n":315,"start":"2024-09-01","end":"2025-11-30","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Oral Submucous Fibrosis"],"interventions":[{"type":"OTHER","name":"940nm diode laser photobiomodulation"},{"type":"OTHER","name":"Conventional non -Invasive management in Oral Submucous fibrosis"}],"sponsor":"Dr. Shalini Gupta","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Dr. Shalini Gupta","title":"Additional Professor","affiliation":"All India Institute of Medical Sciences"},"officials":[{"name":"Shalini Gupta, MDS, FDSRCS(Edin)","role":"PRINCIPAL_INVESTIGATOR","affiliation":"All India Institute of Medical Sciences"}],"countries":["India"],"sites":[{"facility":"All India Institute of Medical Sciences","city":"New Delhi","country":"India"}],"n_sites":1,"outcome":"Maximal Interincisal Mouth opening (mm):","summary":"This a patient and outcome assessor blinded, multiple arm, randomized placebo controlled clinical trial.\n\nThe goal of the study is to study the adjunctive effect of 940nm laser photobiomodulation therapy (PBMT) in precancerous condition like moderate Oral submucous Fibrosis in increasing the mouth opening. It will also assess the the effect of PBMT on oral burning sensation cheek flexibility, electromyography of bilateral masseter muscle, inflammatory and fibrogenic cytokines and oral health quality of life at baseline and after 1 and 3 months of PBMT.\n\nAdult subjects fulfilling the selection criteria will be prospectively recruited after ethical clearance and informed written consent. They will be randomized into 3 groups in 1:1 :1 distribution\n\nThe three groups are as follows:\n\nGroup A: Photobiomodulation therapy given intraorally on bilateral buccal mucosa and extraorally (sham) with ","updated":"2024-10-15","first_posted":"2024-10-15","type":"INTERVENTIONAL","ctx":"autres","titre":"Photobiomodulation 940 nm pour l'ouverture buccale dans la fibrose sous-muqueuse orale"},{"nct":"NCT06574152","title":"Effect of Photobiomodulation on Pain and Healing of the Vertical Releasing Incision After Endodontic Microsurgery","acronym":null,"status":"RECRUITING","phases":["NA"],"n":90,"start":"2024-08-20","end":"2028-05-04","allocation":"RANDOMIZED","masking":"NONE","conditions":["Apical Periodontitis","Endodontically Treated Teeth","Endodontic Disease","Apical Cyst","Apical Granuloma","Periradicular Disease"],"interventions":[{"type":"DEVICE","name":"PBM treatment"},{"type":"DEVICE","name":"PBM sham treatment"},{"type":"DEVICE","name":"EMS"}],"sponsor":"The University of Texas Health Science Center, Houston","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Juliana Barros, DDS, MS","title":"Professor","affiliation":"The University of Texas Health Science Center, Houston"},"officials":[{"name":"Juliana Barros, DDS,MS","role":"PRINCIPAL_INVESTIGATOR","affiliation":"The University of Texas Health Science Center, Houston"}],"countries":["United States"],"sites":[{"facility":"The University of Texas Health Science Center at Houston","city":"Houston","country":"United States"}],"n_sites":1,"outcome":"Change in pain as assessed by a Visual Analogue Scale (VAS)","summary":"The purpose of this study is to evaluate the effect of Photobiomodulation (PBM) in postoperative pain after endodontic microsurgery (EMS) in patients from the University of Texas Health Science Center at Houston, School of Dentistry Graduate Endodontic Clinic and to assess the soft tissue healing of the vertical releasing incision (VRI) after PBM","updated":"2026-08-17","first_posted":"2024-08-27","type":"INTERVENTIONAL","ctx":"endo","titre":"PBM contre sham sur la douleur et la cicatrisation de l'incision après microchirurgie endodontique"},{"nct":"NCT06199674","title":"Effects of PBM on Fixed-appliance Orthodontic Patients","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":50,"start":"2024-01-20","end":"2027-06-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Orthodontics","Root Resorption"],"interventions":[{"type":"DEVICE","name":"photobiomodulation therapy"},{"type":"OTHER","name":"orthodontic fixed-appliance"}],"sponsor":"The University of Hong Kong","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Zhiyi Shan","title":"Clinical Assistant Professor","affiliation":"The University of Hong Kong"},"officials":[{"name":"Zhiyi Shan","role":"PRINCIPAL_INVESTIGATOR","affiliation":"The University of Hong Kong"}],"countries":["Hong Kong"],"sites":[{"facility":"The University of Hong Kong","city":"Hong Kong","country":"Hong Kong"}],"n_sites":1,"outcome":"Orthodontic-induced inflammatory root resorption (OIIRR)","summary":"The aim of this study is to investigate the effects of photobiomodulation therapy (PBM) on the dental and periodontal health of patients undergoing fixed-appliance orthodontic treatment, including orthodontically induced root resorption, orthodontic pain, space closing rate, and dental microbiome profile in dental plaques.","updated":"2026-06-24","first_posted":"2024-01-10","type":"INTERVENTIONAL","ctx":"ortho","titre":"Photobiomodulation et résorption radiculaire sous appareil orthodontique fixe"},{"nct":"NCT06971081","title":"LED Application Following Dental Extraction in Patients Taking Direct Oral Anticoagulants.","acronym":"DENT-DOAC","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":50,"start":"2023-08-17","end":"2025-06-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Direct Oral Anticoagulants (DOACs)"],"interventions":[{"type":"OTHER","name":"LED light"}],"sponsor":"University College, London","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["United Kingdom"],"sites":[{"facility":"UCL","city":"London","country":"United Kingdom"}],"n_sites":1,"outcome":"Bleeding time","summary":"The DENT-DOAC trial is a single-blinded RCT investigating the effectiveness of LED application following dental extractions in patients taking direct oral anticoagulants (DOACs) . The study aims to address a significant clinical challenge, as bleeding following dental extraction is a well-recognized complication in patients taking anticoagulants, and the number of patients taking DOACs requiring dental procedures has increased substantially in recent years.\n\nThe trial will be conducted at the Eastman Dental Hospital (EDH-UCLH) and will recruit 50 participants who will be randomly divided into two groups of 25 each. The test group will receive both LED light application and haemostatic sponge treatment, while the control group will receive only the haemostatic sponge.\n\nThe study population will include patients taking DOACs (rivaroxaban, apixaban, edoxaban, or dabigatran) and are schedule","updated":"2025-05-14","first_posted":"2025-05-14","type":"INTERVENTIONAL","ctx":"chirurgie","titre":"LED après extraction dentaire chez les patients sous anticoagulants oraux directs"},{"nct":"NCT05907161","title":"Low Laser Therapy and Hyaluronic Acid as an Adjunct to Non-surgical Periodontal Therapy","acronym":null,"status":"RECRUITING","phases":["NA"],"n":45,"start":"2023-06-09","end":"2026-02","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Periodontitis"],"interventions":[{"type":"DEVICE","name":"SRP+LASER (Dentsply Sirona - SIROLaser Blue)"},{"type":"DEVICE","name":"SRP+HA"},{"type":"DEVICE","name":"SRP"}],"sponsor":"University of Ljubljana","sponsor_class":"OTHER","collaborators":["University Medical Centre Ljubljana"],"responsible":null,"officials":[{"name":"Aleš Fidler, Dr.","role":"STUDY_DIRECTOR","affiliation":"University Medical Centre Ljubljana"}],"countries":["Slovenia"],"sites":[{"facility":"Univerity Medical Center Ljubljana","city":"Ljubljana","country":"Slovenia"}],"n_sites":1,"outcome":"Probing pocket depth reduction","summary":"Periodontal disease is an oral disease characterized by microbially associated, host-mediated inflammation of the periodontium. In the treatment of periodontal disease, conventional periodontal therapy includes both surgical and non-surgical approaches. Non-surgical therapy (i.e. scaling and root planing - SRP) remains an essential part of periodontal therapy. Here, diseased root surface debridement utilizing different hand and ultrasonic instrumentation is performed to facilitate periodontal re-attachment and to reduce the bacterial mass in the periodontal pocket.\n\nIn the last decade, the use of lasers (light amplification by stimulated emission of radiation) has occupied part of the dialogue within periodontology due to several proposed advantages. In the arena of periodontology, laser use, as an adjunct to non-surgical therapy, was demonstrated to enhance periodontal healing; however,","updated":"2025-09-19","first_posted":"2023-06-18","type":"INTERVENTIONAL","ctx":"paro","titre":"Laser basse énergie ou acide hyaluronique en complément du traitement parodontal non chirurgical"},{"nct":"NCT05650359","title":"Study of the Use of Orthopulse Photobiomodulation","acronym":null,"status":"RECRUITING","phases":["NA"],"n":42,"start":"2022-10-13","end":"2028-05-15","allocation":"RANDOMIZED","masking":"NONE","conditions":["Orthodontics"],"interventions":[{"type":"DEVICE","name":"OrthoPulse"},{"type":"OTHER","name":"No intervention"}],"sponsor":"Biolux Technology GmbH","sponsor_class":"INDUSTRY","collaborators":["medXteam GmbH"],"responsible":null,"officials":[{"name":"Todd Dickerson","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Private Practice 1200 W Warner Rd, Chandler, AZ 85224"}],"countries":["United States"],"sites":[{"facility":"Private Practice","city":"Chandler","country":"United States"}],"n_sites":1,"outcome":"The primary endpoint of this PMCF study is the rate of tooth alignment.","summary":"This PMCF study evaluates the safety and performance of OrthoPulse photobiomodulation to accelerate tooth movement during alignment with fixed appliances.","updated":"2024-08-07","first_posted":"2022-12-14","type":"INTERVENTIONAL","ctx":"ortho","titre":"Dispositif OrthoPulse de photobiomodulation pendant le traitement orthodontique"}],"ophtalmologie":[{"nct":"NCT07554690","title":"Photobiomodulation Laser for Reticular Pseudodrusen in Age-Related Macular Degeneration","acronym":"PBM in iAMD","status":"NOT_YET_RECRUITING","phases":["NA"],"n":67,"start":"2026-10","end":"2027-12-31","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["AMD - Age-Related Macular Degeneration"],"interventions":[{"type":"PROCEDURE","name":"Photobiomodulation Therapy"},{"type":"PROCEDURE","name":"Sham Photobiomodulation"}],"sponsor":"Fondazione G.B. Bietti, IRCCS","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Italy"],"sites":[{"facility":"IRCCS Fondazione G.B.Bietti c/o Ospedale Britannico","city":"Roma","country":"Italy"}],"n_sites":1,"outcome":"Change in Low-Luminance Visual Acuity (LLVA)","summary":"This study evaluates whether a low-energy laser treatment called photobiomodulation (PBM) can improve visual function and retinal structure in patients with age-related macular degeneration (AMD) who have reticular pseudodrusen. PBM is a non-invasive therapy that uses specific wavelengths of light to stimulate cellular activity and reduce inflammation without causing tissue damage.\n\nParticipants will be randomly assigned to receive either active PBM treatment or a sham (inactive) treatment. The study will assess changes in visual performance under low-light conditions and retinal structure over a 12-month period.\n\nThe goal is to determine whether PBM can slow disease progression and improve visual function in patients with early stages of AMD.","updated":"2026-09-04","first_posted":"2026-04-28","type":"INTERVENTIONAL","ctx":"DMLA","titre":"Laser de photobiomodulation contre sham dans les pseudo-drusen réticulés de la DMLA"},{"nct":"NCT07329712","title":"Comparing Tear Proteomics Profile in Dry Eye Disease pre-and Post-treatment With Low Level Light Therapy","acronym":null,"status":"RECRUITING","phases":[],"n":30,"start":"2025-11-05","end":"2026-12-31","allocation":null,"masking":null,"conditions":["Dry Eye","Meibomian Gland Dysfunction (Disorder)"],"interventions":[],"sponsor":"Singapore National Eye Centre","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":{"name":"Louis Tong","title":"Clinician-Scientist, Senior Consultant","affiliation":"Singapore National Eye Centre"},"officials":[{"name":"Louis Tong, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Singapore Eye Research Institute"}],"countries":["Singapore"],"sites":[{"facility":"Singapore Eye Research Insititute","city":"Singapore","country":"Singapore"}],"n_sites":1,"outcome":"Comparing tear proteomics profile in dry eye disease pre-and post-treatment with low level light therapy","summary":"The purpose of this research study is to understand the mechanism of action of low level light therapy and also potentially yield markers associated with good treatment response. Low-level light therapy is light-based treatment delivered through advance eye-light device. This therapy uses light energy to provide energy to the meibomian gland cells to slow down age-ing, improve tear stability and reduce inflammation.","updated":"2026-01-09","first_posted":"2026-01-09","type":"OBSERVATIONAL","ctx":"sécheresse","titre":"Protéomique des larmes avant et après photothérapie basse énergie dans l'œil sec"},{"nct":"NCT07369804","title":"Study on Safety and Efficacy of Focused LED-Based Red-Light Therapy in Myopic Adults","acronym":null,"status":"RECRUITING","phases":["NA"],"n":14,"start":"2025-10-08","end":"2026-07-31","allocation":"NA","masking":"NONE","conditions":["Myopia"],"interventions":[{"type":"DEVICE","name":"fLED-based red-light therapy"}],"sponsor":"The Hong Kong Polytechnic University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["China"],"sites":[{"facility":"The Hong Kong Polytechnic University","city":"Hong Kong","country":"China"}],"n_sites":1,"outcome":"Changes in choroidal thickness measured by OCT","summary":"This research project is a prospective, single-arm, open-label pilot study designed to evaluate the efficacy and safety of focused LED-based repeated low-level red-light (fLED-RLRL) therapy in myopic adults. The primary objective is to assess whether the therapy can increase choroidal thickness and improve choroidal blood flow. The secondary objective is to evaluate the safety and tolerability of red light therapy in adult myopes.\n\nThe study will enroll 14 myopic adults aged 18 to 50 years, with spherical equivalent refractions ranging from -0.50 to -6.00 diopters. Participants will receive home-based fLED-RLRL therapy (wavelength 650 ± 10 nm, power 0.20 mW) twice daily for 3 minutes per session, 5 days per week, over a total of 28 days, combined with single-vision spectacles. The fLED red-light device employs a standard LED semiconductor chip integrated with a total internal reflection ","updated":"2026-01-27","first_posted":"2026-01-27","type":"INTERVENTIONAL","ctx":"myopie","titre":"Sécurité et efficacité d'une lumière rouge LED focalisée chez l'adulte myope"},{"nct":"NCT07160036","title":"Repeatability of AO-SLO (Mona IIa) Technology and Cone Cell Density of Individuals Use Repeated Low-level Red-light Therapy","acronym":"AO-SLO","status":"RECRUITING","phases":["NA"],"n":180,"start":"2025-09-20","end":"2025-11-20","allocation":"NON_RANDOMIZED","masking":"QUADRUPLE","conditions":["Myopia"],"interventions":[{"type":"DEVICE","name":"RLRL(Model RS-200-2A, Eyerising; Suzhou Xuanjia Optoelectronic Technology Co., Ltd., Suzhou, China))"}],"sponsor":"Ruihua Wei","sponsor_class":"OTHER","collaborators":["Tianjin Medical University Eye Hospital"],"responsible":{"name":"Ruihua Wei","title":"Professor","affiliation":"Tianjin Medical University Eye Hospital"},"officials":[{"name":"Ruihua Wei","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Tianjin Medical University Eye Hospital, Tianjin, Tianjin 120120 Recruiting"}],"countries":["China"],"sites":[{"facility":"Tianjin Medical University Eye Hospital","city":"Tianjin","country":"China"}],"n_sites":1,"outcome":"The density of cone cells","summary":"To explore the repeatability of AO-SLO (Mona IIa) technology and the difference of cone cell density between individuals who used or not used repeated low-intensity red light treatment","updated":"2025-09-15","first_posted":"2025-09-08","type":"INTERVENTIONAL","ctx":"myopie","titre":"Densité des cônes en imagerie AO-SLO chez les utilisateurs de lumière rouge répétée (RLRL)"},{"nct":"NCT07332988","title":"Effect of Low-Level Light Therapy on Ocular Surface Parameters in Patients With Graves Disease","acronym":"LLLT-Graves","status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":30,"start":"2025-08-01","end":"2026-08","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Dry Eye Disease (DED)","Graves Ophthalmopathy"],"interventions":[{"type":"DEVICE","name":"Sham (No Treatment)"},{"type":"DEVICE","name":"Low Light Level therapy"}],"sponsor":"Grigore T. Popa University of Medicine and Pharmacy","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Timofte Zorila Mihaela Madalina","title":"Principal Investigator","affiliation":"Grigore T. Popa University of Medicine and Pharmacy"},"officials":[{"name":"Mihaela Madalina Timofte Zorila","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Medicine \"Gr. T. Popa\", Iasi, Romania"}],"countries":["Romania"],"sites":[{"facility":"University of Medicine and Pharmacy \"Grigore T. Popa\"","city":"Iași","country":"Romania"}],"n_sites":1,"outcome":"Changes in tear film stability (NIBUT and FBUT) from baseline during the treatment and in the follow-up period in patients with Graves' ophthalmopathy who undergo low-level light therapy (LLLT)","summary":"This prospective, interventional, randomized, controlled, double-blind clinical study evaluates the effect of Low-Level Light Therapy (LLLT) delivered by a polychromatic periocular mask (Eye-light®️) versus a sham device in adults with dry eye disease (DED) associated with Graves' ophthalmopathy, refractory to conventional topical treatment. The LLLT protocol applies photobiomodulation to eyelid and periocular tissues to support meibomian gland function and reduce tear inflammatory biomarkers. The primary endpoint is the change in tear film stability measured by Non-Invasive Tear Break-Up Time (NIBUT) and Fluorescein Tear Break-Up Time (FBUT). Secondary outcomes include symptom scores (OSDI), Schirmer I test, tear osmolarity, ocular surface staining scales, automated conjunctival hyperemia, blink analysis, meibomian gland morphology (meibography/meiboscale), tear inflammatory biomarkers,","updated":"2026-01-12","first_posted":"2026-01-12","type":"INTERVENTIONAL","ctx":"sécheresse","titre":"Photothérapie basse énergie contre sham sur la surface oculaire dans la maladie de Basedow"},{"nct":"NCT07173530","title":"Low Level Light Therapy & Skin Pigmentation","acronym":null,"status":"RECRUITING","phases":["NA"],"n":40,"start":"2025-06-11","end":"2026-08","allocation":"NON_RANDOMIZED","masking":"NONE","conditions":["Dry Eye","Meibomian Gland Dysfunction (Disorder)"],"interventions":[{"type":"DEVICE","name":"Three 15-minute low-level light therapy sessions using Light Emitting Diodes of wavelength 633nm (Essilor epi-c plus)."}],"sponsor":"University of Houston","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Eric R. Ritchey","title":"Associate Professor","affiliation":"University of Houston"},"officials":[],"countries":["United States"],"sites":[{"facility":"The University of Houston College of Optometry","city":"Houston","country":"United States"}],"n_sites":1,"outcome":"Eyelid temperature","summary":"The goal of this clinical trial is to determine if there is a difference in eyelid temperature after low-level light therapy (LLLT) in individuals with different amounts of skin pigmentation and dry eye/meibomian gland disease. Participants will have 3 fifteen minute in office LLLT therapy sessions over a period of approximately 7 to 14 days.","updated":"2025-09-15","first_posted":"2025-09-15","type":"INTERVENTIONAL","ctx":"sécheresse","titre":"Photothérapie basse énergie de l'œil sec selon la pigmentation cutanée"},{"nct":"NCT06780293","title":"Laser Acupuncture on Dry Eye and Sjögren's Syndrome-related Dry Eye Symptoms (LADESJS)","acronym":"LADESJS","status":"RECRUITING","phases":["PHASE2"],"n":140,"start":"2025-02-03","end":"2025-04-30","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Dry Eye Syndrome (DES)","Laser Acupuncture","Sjögren's Syndrome (SS)"],"interventions":[{"type":"OTHER","name":"Laser acupuncture (LA)"},{"type":"DIAGNOSTIC_TEST","name":"Numerical Rating Scale (NRS)"},{"type":"DIAGNOSTIC_TEST","name":"Schirmer's test"},{"type":"DIAGNOSTIC_TEST","name":"Ocular Surface Disease Index (OSDI)"},{"type":"DIAGNOSTIC_TEST","name":"EULAR Sjögren's Syndrome Patient Reported Index (ESSPRI)"},{"type":"DIAGNOSTIC_TEST","name":"Traditional Chinese Medicine (TCM) tongue diagnosis"}],"sponsor":"Taipei Veterans General Hospital, Taiwan","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":{"name":"Ching-Mao Chang","title":"Director of Division of Integrative Medicine, Center for Traditional Medicine","affiliation":"Taipei Veterans General Hospital, Taiwan"},"officials":[],"countries":["Taiwan"],"sites":[{"facility":"Ching-Mao Chang","city":"Taipei","country":"Taiwan"}],"n_sites":1,"outcome":"Numerical Rating Scale (NRS)","summary":"This randomized, double-blind, placebo-controlled clinical trial aims to evaluate the efficacy of adding laser acupuncture at Fengchi (GB20), Zanzhu (BL2), Hegu (LI4), and Quchi (LI11) acupoints to standard care for the treatment of dry eye symptoms in both Sjögren's Syndrome-related dry eye (SJS-DES) and non-Sjögren's Syndrome-related dry eye (Non-SJS-DES) populations. A total of 140 dry eye patients will be recruited and divided into two groups: 70 participants with SJS-DES and 70 with Non-SJS-DES. Participants will be randomly assigned into three groups: Sham+LA group (60 participants receiving 4 weeks of placebo laser acupuncture followed by 4 weeks of active laser acupuncture), LA+LA group (60 participants receiving 4 weeks of active laser acupuncture followed by another 4 weeks of active laser acupuncture), and a Waiting List group (20 participants receiving no laser acupuncture tr","updated":"2025-04-09","first_posted":"2025-01-17","type":"INTERVENTIONAL","ctx":"sécheresse","titre":"Laser-acupuncture dans l'œil sec, dont celui du syndrome de Sjögren"},{"nct":"NCT07229001","title":"Treating Meibomian Gland Disease in a Pediatric Population","acronym":"LLLT in Peds","status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":15,"start":"2024-10-01","end":"2026-12-30","allocation":"RANDOMIZED","masking":"NONE","conditions":["Dry Eye Disease, Meibomian Gland Disease"],"interventions":[{"type":"OTHER","name":"Low level light treatment"},{"type":"OTHER","name":"warm compress and artificial tear"}],"sponsor":"Illinois College of Optometry","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Yi Pang","title":"professor","affiliation":"Illinois College of Optometry"},"officials":[],"countries":["United States"],"sites":[{"facility":"Illinois College of Optometry","city":"Chicago","country":"United States"}],"n_sites":1,"outcome":"Change in MG","summary":"Dry Eye Disease (DED) is commonly encountered among eye care professionals. DED is a disease of the tears and ocular surface that is multi-factorial resulting in a wide range of symptoms and signs with potentially damaging effects. As technology continues to evolve and as digital devices become more available in social, work environments, and in school settings, patients are increasingly complaining of ocular discomfort and fluctuations in their vision.\n\nIn order to diagnose DED which encompasses Meibomian gland dysfunction (MGD), a detailed case history of \\\\patients' symptoms along with imaging to investigate the amount of disease present in their eyes is needed. A customized questionnaire and the Keratograph meibographer will allow for a subjective and objective investigation of dry eye disease in patients. Artificial tears and warm compress are traditional methods used to treat DED. ","updated":"2025-11-14","first_posted":"2025-11-14","type":"INTERVENTIONAL","ctx":"sécheresse","titre":"Photothérapie basse énergie du dysfonctionnement meibomien de l'enfant"},{"nct":"NCT06371300","title":"Photobiomodulation With REd vs BluE Light (REBEL)","acronym":null,"status":"RECRUITING","phases":["NA"],"n":36,"start":"2024-05-01","end":"2026-10-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Dry Eye Syndromes","Meibomian Gland Dysfunction","Blepharitis"],"interventions":[{"type":"DEVICE","name":"Red LLLT"},{"type":"DEVICE","name":"Blue LLLT"},{"type":"DEVICE","name":"Sham Red LLLT"},{"type":"DEVICE","name":"Sham Blue LLLT"}],"sponsor":"Aston University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"James S Wolffsohn, PhD","role":"STUDY_DIRECTOR","affiliation":"Aston University"}],"countries":["New Zealand","United Kingdom"],"sites":[{"facility":"University of Auckland","city":"Auckland","country":"New Zealand"},{"facility":"Aston Dry Eye Clinic","city":"Birmingham","country":"United Kingdom"}],"n_sites":2,"outcome":"Change from Baseline in Bacterial Colony to the Final Follow-up 1 Month After Final Treatment Session","summary":"The use of photobiomodulation or low-level light therapy (LLLT) in the ophthalmic field stemmed from dermatology which has shown impact on skin blood flow and regeneration. There has been a rise in clinical interest with emerging evidence in the benefits of photobiomodulation in managing chronic inflammatory conditions such as dry eye disease including improvements in ocular discomfort symptoms, tear film stability and tear volume. Despite the observed clinical benefits, limited research has been done to compare photobiomodulation utilising different wavelengths, as most research on dry eye disease has focused on red wavelengths. It has been purported that blue wavelengths may disrupt microbial growth while red wavelengths stimulate energy production and hence increase heat in the affected tissues, although research into these differential impacts at the ocular surface and external eye h","updated":"2026-01-21","first_posted":"2024-04-17","type":"INTERVENTIONAL","ctx":"sécheresse","titre":"Photothérapie rouge contre bleue contre sham dans l'œil sec meibomien et la blépharite (REBEL)"},{"nct":"NCT06351605","title":"A Registry Study to Assess Photobiomodulation in Dry Age-Related Macular Degeneration (GLOBALIGHT)","acronym":null,"status":"RECRUITING","phases":[],"n":500,"start":"2023-09-01","end":"2028-11","allocation":null,"masking":null,"conditions":["Dry Age-related Macular Degeneration"],"interventions":[{"type":"DEVICE","name":"Valeda® Light Delivery System"}],"sponsor":"LumiThera, Inc.","sponsor_class":"INDUSTRY","collaborators":[],"responsible":null,"officials":[{"name":"Sr. Principal Clinical Trial Operations, Surgical","role":"STUDY_DIRECTOR","affiliation":"Alcon Research, LLC"}],"countries":["Norway","United States"],"sites":[{"facility":"Retina Vitreous Associates Medical Group","city":"Beverly Hills","country":"United States"},{"facility":"Cincinnati Eye Institute","city":"Cincinnati","country":"United States"},{"facility":"Carolina Eyecare Physicians","city":"Charleston","country":"United States"},{"facility":"Valley Retina Institute","city":"McAllen","country":"United States"},{"facility":"Pacific Northwest Retina","city":"Silverdale","country":"United States"},{"facility":"Institutt for Oyehelse","city":"Oslo","country":"Norway"}],"n_sites":6,"outcome":"Change in Visual Acuity from Baseline at each Treatment Visit","summary":"The purpose of this registry study is to collect real life data pertaining to the safety and clinical effectiveness of multi-wavelength photobiomodulation (PBM) as provided by the Valeda Light Delivery System in participants with dry age-related macular degeneration (AMD) in routine clinical practice. Data will be collected retrospectively and prospectively.\n\nPBM involves the use of visible light to near infrared light (NIR) (500-1000 nanometers) produced by a laser or a non-coherent light source applied to the surface of the body to activate mitochondrial respiratory chain components, stabilize metabolic function, and promote cellular proliferation.\n\nThis registry study will be conducted in Europe, the US, and select other countries approved by their regulatory agency.\n\nThis registry study was initiated as a combined retrospective and prospective data collection effort. After the acquis","updated":"2026-09-22","first_posted":"2024-04-08","type":"OBSERVATIONAL","ctx":"DMLA","titre":"Registre international Valeda dans la DMLA sèche (GLOBALIGHT)"},{"nct":"NCT05507840","title":"Photobiomodulation for Dry Age Related Macula Degeneration","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":121,"start":"2022-12-01","end":"2026-12-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Photobiomodulation","Age-Related Macular Degeneration"],"interventions":[{"type":"DEVICE","name":"Valeda machine"}],"sponsor":"Oslo University Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"ANCA ROALD","title":"Principal Investigator, MD dr. med.","affiliation":"Oslo University Hospital"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Percentage of patients that develope late AMD in the study eye compared with control after 3 years of follow-up","summary":"The study will investigate the effect of photobiomodulation treatment on the risk of developing late age related macula degeneration (AMD) in the study eye in patients with wet AMD in the fellow eye.","updated":"2022-10-12","first_posted":"2022-08-19","type":"INTERVENTIONAL","ctx":"DMLA","titre":"Photobiomodulation Valeda dans la DMLA sèche"}],"neuropathie-peripherique":[{"nct":"NCT07788248","title":"Low-Level Laser Therapy for Carpal Tunnel Syndrome","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":105,"start":"2026-09-01","end":"2027-02-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Carpal Tunnel Syndrome (CTS)"],"interventions":[{"type":"DEVICE","name":"Low-Level Laser Therapy (LLLT)"},{"type":"DEVICE","name":"Paraffin Bath Therapy"},{"type":"DEVICE","name":"Sham Low-Level Laser Therapy"},{"type":"OTHER","name":"Standard Conservative Care"}],"sponsor":"Bursa Yuksek Ihtisas Training and Research Hospital","sponsor_class":"OTHER_GOV","collaborators":[],"responsible":{"name":"Sinem Akselim","title":"Principle investigator","affiliation":"Bursa Yuksek Ihtisas Training and Research Hospital"},"officials":[],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"University of Health Sciences, Bursa Yuksek Ihtisas Training and Research Hospital","city":"Bursa","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Change from Baseline in Boston Carpal Tunnel Questionnaire - Symptom Severity Scale (SSS)","summary":"Carpal tunnel syndrome (CTS) is the most common peripheral entrapment neuropathy, caused by compression of the median nerve within the carpal tunnel at the wrist. It typically presents with paresthesia, numbness, and pain in the median nerve distribution, and in advanced cases may lead to thenar atrophy and reduced grip strength. Conservative treatment options for mild-to-moderate CTS include wrist splinting, exercise programs, and physical therapy modalities such as low-level laser therapy (LLLT) and paraffin bath therapy; however, the comparative efficacy of these modalities has not been well established.\n\nThis study aims to compare the efficacy of low-level laser therapy (LLLT), paraffin bath therapy, and sham LLLT, each combined with standard conservative care (night wrist splinting and tendon/nerve gliding exercises), in patients with mild-to-moderate CTS. Participants will be rando","updated":"2026-08-26","first_posted":"2026-08-26","type":"INTERVENTIONAL","ctx":"compression","titre":"Laser basse énergie, paraffine ou sham dans le syndrome du canal carpien"},{"nct":"NCT07681921","title":"Randomized Clinical Investigation of Photobiomodulation (PBM) for the Management of Early Peripheral Neuropathy Related to Medical Oncologic Therapy","acronym":"ENL","status":"NOT_YET_RECRUITING","phases":["NA"],"n":98,"start":"2026-09-01","end":"2028-09-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Chemotherapy Induced Peripheral Neuropathy"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"}],"sponsor":"Jules Bordet Institute","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Belgium"],"sites":[{"facility":"Jules Bordet Institute","city":"Brussels","country":"Belgium"}],"n_sites":1,"outcome":"severity of CIPN measured by modified Total Neurpathy Score m-TNS","summary":"Chemotherapy-induced peripheral neuropathy (CIPN) is one of the common complications of cancer treatment and involves paresthesia, numbness and/or burning pain in distal limbs. This condition has a high health impact because it is associated with psychological distress, fall risk, and poor sleep quality. Furthermore, it impairs patients' daily activities and thereby decreases their quality of life. The overall incidence of CIPN is approximately 68% in the first month after chemotherapy. The available evidence for preventive and therapeutic options for CIPN is limited. Therefore, only symptom management based on pharmacological and/or physical therapy is applied with limited success. Photobiomodulation (PBM) has the potential to reduce the development of CIPN in breast cancer patients. PBM uses visible and/or (near)-infrared light at a low power produced by laser diodes or light-emitting ","updated":"2026-07-02","first_posted":"2026-07-02","type":"INTERVENTIONAL","ctx":"CIPN","titre":"PBM dans la neuropathie périphérique débutante liée aux traitements du cancer (Belgique)"},{"nct":"NCT07714720","title":"Photobiomodulation for Median Nerve Neuroplasticity in Carpal Tunnel Syndrome: A Randomized Controlled Trial","acronym":"PBM-CTS-RCT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":70,"start":"2026-08-15","end":"2027-05-15","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Carpal Tunnel Syndrome (CTS)"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation (Low-Level Laser Therapy)"},{"type":"DEVICE","name":"Sham Photobiomodulation"},{"type":"OTHER","name":"Routine Physiotherapy Programme"}],"sponsor":"University of Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Dr Sajid Mehmood, MS (OMPT)","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Lahore"},{"name":"Dr Ashfaq Ahmad, PhD","role":"STUDY_DIRECTOR","affiliation":"University of Lahore"},{"name":"Dr Umair Ahmed, PhD","role":"STUDY_CHAIR","affiliation":"University of Lahore"},{"name":"Dr Ishaq Ahmed, PhD","role":"STUDY_CHAIR","affiliation":"University of Lahore"}],"countries":["Pakistan"],"sites":[{"facility":"University of Lahore Hospital","city":"Lahore","country":"Pakistan"}],"n_sites":1,"outcome":"Change From Baseline in Median Nerve Sensory Conduction Velocity at Week 4 and week 8","summary":"Carpal Tunnel Syndrome (CTS) is the most common peripheral entrapment neuropathy, causing pain, paresthesia, and hand dysfunction due to median nerve compression at the wrist. While physiotherapy provides symptom relief, it does not effectively address the underlying neuroplastic deficits of the median nerve. Photobiomodulation (PBM), delivered at 830 nm near-infrared wavelength, has shown potential to enhance peripheral nerve regeneration via cytochrome c oxidase activation, ATP synthesis, and upregulation of neurotrophic factors including brain-derived neurotrophic factor (BDNF). This randomized controlled trial will evaluate whether 830 nm PBM (200 mW, 4 J/cm², 12 sessions over 4 weeks) combined with routine physiotherapy produces significantly greater neuroplastic recovery of the median nerve - assessed by high-resolution ultrasound (HRUS) measurement of median nerve cross-sectional ","updated":"2026-07-20","first_posted":"2026-07-20","type":"INTERVENTIONAL","ctx":"compression","titre":"PBM et neuroplasticité du nerf médian dans le canal carpien"},{"nct":"NCT07356362","title":"High-power Laser Therapy for Notalgia Paresthetica.","acronym":null,"status":"RECRUITING","phases":["NA"],"n":40,"start":"2026-07-17","end":"2026-10-23","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Notalgia Paresthetica"],"interventions":[{"type":"DEVICE","name":"High-power laser"},{"type":"OTHER","name":"Sham Laser"}],"sponsor":"Uşak University","sponsor_class":"OTHER","collaborators":["Balikesir University"],"responsible":null,"officials":[{"name":"Ender Y Salbas, Asst. Prof.","role":"STUDY_CHAIR","affiliation":"University of Balikesir"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Usak University","city":"Uşak","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Pain screening with PainDETECT","summary":"A non-invasive modality for the management of neuromusculoskeletal pain conditions that has emerged as a compelling option is high-power laser therapy (HPLT). The pathophysiology of notalgia paresthetica (NP) is treated uniquely by HPLT, which targets both the presumed muscular component of nerve entrapment and the resultant neuropathic symptoms. The main goal of this study, which is randomised, controlled and blinded by assessors, is to find out how well High-Power Laser Therapy (HPLT) works as an extra treatment to standard care in reducing itching, pain and improving quality of life for patients with long-term nerve pain.","updated":"2026-07-20","first_posted":"2026-01-21","type":"INTERVENTIONAL","ctx":"autres","titre":"Laser haute puissance contre sham dans la notalgie paresthésique"},{"nct":"NCT07661667","title":"This Study Aims to Investigate the Efficacy of Photobiomodulation in the Treatment of Anti-MAG-induced Peripheral Neuropathy (LASER-MAG)","acronym":"LASER-MAG","status":"ENROLLING_BY_INVITATION","phases":[],"n":10,"start":"2026-06-09","end":"2026-12","allocation":null,"masking":null,"conditions":["Anti MAG Neuropathy"],"interventions":[{"type":"RADIATION","name":"photobiomodulation"}],"sponsor":"Centre Hospitalier de Cornouaille","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Madame Rameau","title":"doctor","affiliation":"Centre Hospitalier de Cornouaille"},"officials":[{"name":"Le Clech LLC Lenaig, doctor","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Centre Hospitalier de Cornouaille"}],"countries":["France"],"sites":[{"facility":"Centre hospitalier de Cornouaille","city":"Quimper","country":"France"}],"n_sites":1,"outcome":"To evaluate the efficacy of photobiomodulation in the symptomatic treatment of anti-MAG-induced peripheral neuropathies","summary":"Patients treated in the hematology department of the Quimper/Cornouaille Hospital Center for IgM monoclonal gammopathy with anti-MAG and symptomatic peripheral neuropathy often reach a therapeutic impasse.\n\nThe treatment of neuropathic pain is complex, but recently a new non-pharmacological therapy, photobiomodulation, has shown evidence of efficacy and improved quality of life in the treatment of these peripheral neuropathies.\n\nThis new therapy uses low-intensity lasers; it is non-invasive, athermic, and has no reported side effects. The general principle is to expose tissues to visible light in the red and near-infrared spectrum to elicit a biological response.\n\nThe study aims to evaluate the efficacy and tolerability of photobiomodulation in this population of patients with anti-MAG neuropathy.","updated":"2026-06-22","first_posted":"2026-06-22","type":"OBSERVATIONAL","ctx":"autres","titre":"PBM dans la neuropathie à anti-MAG (France)"},{"nct":"NCT07590414","title":"High-intensity Laser Therapy Versus Low Level Laser Therapy in the Treatment of Trigeminal Neuralgia","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":38,"start":"2026-05-15","end":"2026-12-30","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Trigeminal Neuralgia"],"interventions":[{"type":"OTHER","name":"1064 nm Nd-YAG Laser"},{"type":"OTHER","name":"940 nm Diode laser"}],"sponsor":"Alexandria University","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["Egypt"],"sites":[{"facility":"Outpatient Clinic of Oral medicine Department, Faculty of Dentistry, Alexandria University, Egypt","city":"Alexandria","country":"Egypt"}],"n_sites":1,"outcome":"Change in pain scores","summary":"Trigeminal neuralgia (TN) is the most common and severe type of neuropathic pain disorder affecting the orofacial region. It is characterized by sudden, intense, episodic attacks of pain in the distribution of trigeminal nerve, usually unilateral. The condition severely impairs patient's quality of life. TN represents a diagnostic and therapeutic challenge, pharmacological therapy remains the first-line management, and many patients experience reduced drug tolerance or significant side effects over time. Surgical options are considered for refractory cases but are invasive and carry risks such as infection, nerve damage, and recurrence of symptoms. In recent years, laser based therapies have gained attention as safe, non-invasive alternatives. Low level laser therapy (LLLT) promotes photo-biomodulation and nerve repair without thermal damage, while high-intensity laser therapy (HILT) can","updated":"2026-05-15","first_posted":"2026-05-15","type":"INTERVENTIONAL","ctx":"orofaciale","titre":"Laser haute intensité ou basse énergie dans la névralgie du trijumeau"},{"nct":"NCT07405008","title":"Laser Acupuncture on Carpal Tunnel Syndrome .","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":54,"start":"2026-03-01","end":"2026-05-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Carpal Tunnel Syndrome (CTS) in Breast Cancer Patients"],"interventions":[{"type":"DEVICE","name":"LASER acupuncture technique"},{"type":"OTHER","name":"Traditional physical therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Naiera Sabry Mohamed Shams","title":"Physiotherapy Specialist at Damanhur Medical National Institute, EL-Behira, Egypt","affiliation":"Cairo University"},"officials":[{"name":"Research Ethical Committee Faculty of Physical Therapy","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Cairo University"}],"countries":["Egypt"],"sites":[{"facility":"Faculty of Physical Therapy","city":"Giza","country":"Egypt"}],"n_sites":1,"outcome":"Median Motor Nerve Conduction Study","summary":"The study will be carried out on a total number of fifty-four females with age ranged 40 - 60 years old suffering from CTS post mastectomy ,the patients will be randomly assigned into two groups equal in number (27 patients for each group from Damanhur Medical National institute).\n\n1. -Group (A): This group will include 27 patients will receive laser acupuncture technique 3 times per week in addition to traditional physical therapy program (myofascial release, nerve flossing ex., Tendon gliding ex. strengthening ex., ROM ex. and night splint) for 8 weeks.\n2. -Group (B): This group will include 27 patients will receive traditional physical therapy program (myofascial release, nerve flossing ex., Tendon gliding ex., strengthening ex., ROM ex. and night splint) for 8 weeks.","updated":"2026-02-12","first_posted":"2026-02-12","type":"INTERVENTIONAL","ctx":"compression","titre":"Laser-acupuncture dans le syndrome du canal carpien"},{"nct":"NCT07613489","title":"Photobiomodulation for Diabetic Peripheral Neuropathy","acronym":"PBMT-DPN","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":36,"start":"2026-02-01","end":"2026-06-24","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Diabetic Peripheral Neuropathy","Diabetes Mellitus Type 2"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation Therapy"},{"type":"DEVICE","name":"Sham Laser Therapy"}],"sponsor":"University of Faisalabad","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Anbreena Rasool","title":"Assistant Professor, Department of Rehabilitation Sciences","affiliation":"University of Faisalabad"},"officials":[],"countries":["Pakistan"],"sites":[{"facility":"The University of Faisalabad","city":"Faisalābad","country":"Pakistan"}],"n_sites":1,"outcome":"Change in Pain Intensity","summary":"Diabetic peripheral neuropathy (DPN) is a common complication of long-term diabetes, affecting approximately 50 percent of patients. It causes tingling, numbness, and burning pain primarily in the feet, which reduces quality of life. Photobiomodulation therapy (PBMT), also known as low-level laser therapy, is a non-invasive treatment that may improve nerve function by reducing inflammation and promoting cellular repair. This randomized controlled trial aims to evaluate the effectiveness of PBMT in improving nerve function and quality of life in patients with DPN. A total of 36 participants with type 2 diabetes and DPN will be randomly assigned to either a treatment group receiving PBMT (900 nm wavelength, 25W, 1000 Hz frequency) or a control group receiving sham laser therapy. The intervention will be applied to the dorsum and plantar surface of the foot every other day for 6 weeks. Outc","updated":"2026-06-23","first_posted":"2026-05-29","type":"INTERVENTIONAL","ctx":"diabète","titre":"PBM contre sham dans la neuropathie diabétique"},{"nct":"NCT07328360","title":"The Efficacy of High-Power Laser Therapy in Meralgia Paresthetica","acronym":null,"status":"RECRUITING","phases":["NA"],"n":50,"start":"2026-01-12","end":"2026-07-05","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Meralgia Paresthetica"],"interventions":[{"type":"DEVICE","name":"High-power laser"},{"type":"OTHER","name":"Sham laser"},{"type":"OTHER","name":"Standard Conservative Care"}],"sponsor":"Uşak University","sponsor_class":"OTHER","collaborators":["Balikesir University"],"responsible":{"name":"Ali Yavuz Karahan","title":"Professor","affiliation":"Uşak University"},"officials":[{"name":"Ali Y Karahan, Prof.","role":"STUDY_CHAIR","affiliation":"University of Usak"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Usak University","city":"Uşak","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"PainDETECT","summary":"The management of MP typically follows a conservative pathway, encompassing patient education, lifestyle modifications (e.g., avoidance of tight garments, weight loss), pharmacotherapy (such as neuropathic pain agents or corticosteroid injections), and physical therapy. However, evidence supporting the efficacy of these interventions is largely anecdotal or derived from low-quality studies, and a substantial proportion of patients experience persistent symptoms refractory to standard care.\n\nTherefore, the primary objective of this randomized, sham-controlled, assessor-blinded study is to investigate the efficacy of HPLT as an adjunct to standard conservative care on pain intensity, sensory symptoms, and functional capacity in patients with chronic Meralgia Paresthetica. The investigators hypothesize that patients receiving active HPLT will demonstrate significantly greater improvements i","updated":"2026-01-13","first_posted":"2026-01-09","type":"INTERVENTIONAL","ctx":"compression","titre":"Laser haute puissance dans la méralgie paresthésique"},{"nct":"NCT07294157","title":"Comparison of Rest Splints vs High-Intensity Laser Therapy in Carpal Tunnel Syndrome","acronym":null,"status":"RECRUITING","phases":["NA"],"n":78,"start":"2025-12-15","end":"2026-07-15","allocation":"RANDOMIZED","masking":"NONE","conditions":["Carpal Tunnel Syndrome (CTS)"],"interventions":[{"type":"DEVICE","name":"Rest splint group"},{"type":"DEVICE","name":"high-intensity laser therapy (HILT)"},{"type":"DEVICE","name":"sham high-intensity laser therapy (HILT)"}],"sponsor":"Afyonkarahisar Health Sciences University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Ramazan Tuncer","title":"med.doctor","affiliation":"Afyonkarahisar Health Sciences University"},"officials":[{"name":"Ümit DÜNDAR, Profesor","role":"PRINCIPAL_INVESTIGATOR","affiliation":"AFYONKARAHİSAR HEALTH SCİENCES UNİVERSITY"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Afyonkarahisar Health Science University","city":"Afyonkarahisar","country":"Turkey (Türkiye)"},{"facility":"Afyonkarahisar Health Sciences Unıversity","city":"Afyonkarahisar","country":"Turkey (Türkiye)"}],"n_sites":2,"outcome":"Visual Analog Scale (VAS):","summary":"The aim of this study is to compare the effectiveness of rest splints and high-intensity laser therapy(HILT) added to physical therapy programs for patients with carpal tunnel syndrome in terms of pain, function, nerve conduction studies, and grip strength.","updated":"2026-01-13","first_posted":"2025-12-19","type":"INTERVENTIONAL","ctx":"compression","titre":"Attelle de repos ou laser haute intensité dans le canal carpien"},{"nct":"NCT07266636","title":"Effects of Photobiomodulation and Electrical Stimulation Among Bell's Palsy Patients","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":34,"start":"2025-11-25","end":"2026-05-25","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Bell's Palsy"],"interventions":[{"type":"RADIATION","name":"Photobiomodulation alongwith facial exercise"},{"type":"OTHER","name":"Electrical Stimulation alongwith facial exercise"}],"sponsor":"Lahore University of Biological and Applied Sciences","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"House-Brackmann Facial Nerve Grading System","summary":"Despite promising evidence supporting both photobiomodulation (PBM) and electrical stimulation (ES) in Bell's palsy rehabilitation, key gaps remain in the literature. Few studies have directly compared these modalities under standardized conditions, especially while keeping facial exercises constant across groups. Inconsistent treatment parameters such as variations in PBM wavelength or ES intensity limit the comparability and replication of existing findings. Additionally, many studies rely on subjective outcome measures and lack structured timelines for assessing facial symmetry, neuromuscular coordination, or long-term recovery, including complications like synkinesis. These limitations highlight the need for a well-controlled comparative study to determine the more effective modality when paired with consistent facial rehabilitation exercises.","updated":"2025-12-05","first_posted":"2025-12-05","type":"INTERVENTIONAL","ctx":"orofaciale","titre":"PBM ou électrostimulation dans la paralysie faciale de Bell"},{"nct":"NCT07414069","title":"High-Intensity Laser Therapy in Carpal Tunnel Syndrome: Clinical, Sonographic, and Electrophysiological Outcomes","acronym":null,"status":"RECRUITING","phases":["NA"],"n":80,"start":"2025-11-02","end":"2026-03-05","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Carpal Tunnel Syndrome"],"interventions":[{"type":"DEVICE","name":"High-Intensity Laser Therapy (HILT)"},{"type":"DEVICE","name":"Sham High-Intensity Laser Therapy"}],"sponsor":"Ankara City Hospital Bilkent","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Filiz Eser, professor","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Ankara City Hospital Bilkent"}],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Ankara Bilkent City Hospital","city":"Ankara","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Pain Severity assessed by Visual Analog Scale (VAS)","summary":"Carpal tunnel syndrome (CTS) is the most common entrapment neuropathy of the upper extremity and is characterized by pain, paresthesia, and functional impairment resulting from increased pressure within the carpal tunnel. Although conservative treatment approaches such as splinting and pharmacological therapy are commonly used, High-Intensity Laser Therapy (HILT) has emerged as a non-invasive modality with potential analgesic, anti-inflammatory, and biostimulatory effects. However, evidence regarding its efficacy remains limited, particularly from sham-controlled studies incorporating objective outcome measures. This prospective, randomized, double-blind, sham-controlled clinical trial aims to evaluate the clinical, sonographic, and electrophysiological effectiveness of HILT in patients with mild-to-moderate CTS. Eligible patients aged 18 to 65 years with electrophysiologically confirmed","updated":"2026-02-17","first_posted":"2026-02-17","type":"INTERVENTIONAL","ctx":"compression","titre":"Laser haute intensité contre sham dans le canal carpien : clinique, échographie, EMG"},{"nct":"NCT06834685","title":"Evaluating Laser Photobiomodulation for the Treatment of Neuropathic Pain in Chemotherapy-induced Peripheral Neuropathy in Cancer Patients","acronym":"NEUROdoux","status":"RECRUITING","phases":["NA"],"n":70,"start":"2025-10-07","end":"2028-05","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Cancer Survivors","Peripheral Neuropathic Pain"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation sessions"}],"sponsor":"Institut du Cancer de Montpellier - Val d'Aurelle","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Estelle GUERDOUX, PHD","role":"STUDY_DIRECTOR","affiliation":"INSTITUT REGIONAL DU CANCER DE MONTPELLIER"}],"countries":["France"],"sites":[{"facility":"Centre Azuréen de Cancérologie","city":"Mougins","country":"France"},{"facility":"ICM","city":"Montpellier","country":"France"}],"n_sites":2,"outcome":"Evaluation of the efficacy of photobiomodulation on neuropathic pain in a experimental group and evaluate the placebo effect in a controlled group","summary":"Chemotherapy-induced peripheral neuropathy (CIPN) (including taxanes, platinum, al pervenche from Madagascar alkaloids...), is a frequent secondary effect of treatments: 68% at 1-month post-chemotherapy, 60% at 3 months and 30% after 6 months. Symptoms associated with CIPN are usually symmetric and bilateral (typical distribution in \"gloves and socks\") inducing sensory alterations, paresthesias, dysesthesias, numbness and pain. Neuropathic Pain (NP) is an important characteristic of CIPN, affects 25-80% of patients with CIPN, and reduces quality of life (e.g., concomitant psychological distress, risks of falls, risks of neurocognitive impairments, and sleep disorders).\n\nIn severe cases, it is even necessary to delay and/or reduce the dose of chemotherapy. The benefit of drug interventions on NP remains limited. To date, there are no proven preventive strategies and few evidence-based tre","updated":"2026-07-28","first_posted":"2025-02-19","type":"INTERVENTIONAL","ctx":"CIPN","titre":"PBM laser contre la douleur neuropathique chimio-induite (France)"},{"nct":"NCT07191808","title":"EXPLORING EFFECTIVENESS OF LOW LEVEL LASER THERAPY IN THE TREATMENT OF PATIENTS WITH BELLS PALSY","acronym":"bells palsy","status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":100,"start":"2025-10","end":"2025-12","allocation":"NA","masking":"NONE","conditions":["Bell Palsy","Bell&#39;s Palsy"],"interventions":[{"type":"OTHER","name":"Low Level Laser Therapy"}],"sponsor":"University of Lahore","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Shahid Ahmed","title":"Shahid Ahmed","affiliation":"University of Lahore"},"officials":[{"name":"Prof Dr Ashfaq Ahmed, PhD","role":"STUDY_DIRECTOR","affiliation":"University of Lahore"}],"countries":["Pakistan"],"sites":[{"facility":"NACE","city":"Faisalābad","country":"Pakistan"}],"n_sites":1,"outcome":"House-Brackmann Score","summary":"The aim of the proposed research is to explore effectiveness of Low Level LASER Therapy in the country and to compare its effectiveness with routine physiotherapy. The societal benefit of submitted research is to formulate a guideline for physical therapy clinicians of the country to treat patients with Bell's Palsy through modern tool of Low Level LASER Therapy if found effective for improvement in quality of lives","updated":"2025-09-25","first_posted":"2025-09-25","type":"INTERVENTIONAL","ctx":"orofaciale","titre":"Laser basse énergie dans la paralysie faciale de Bell"},{"nct":"NCT07014774","title":"Efficacy of Laser Acupuncture on Carpal Tunnel Syndrome Following Hand Flexor Tendon Repair","acronym":"LASER","status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2025-06-15","end":"2025-09-15","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Laser Acupuncture","Flexor Tendon Repair","Hand Surgery","Carpal Tunnel Syndrome (CTS)"],"interventions":[{"type":"DEVICE","name":"Laser acupuncture"},{"type":"OTHER","name":"Traditional Therapy"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mahmoud Adel Abdel-Hakim Amin","title":"Principle Investigator","affiliation":"Cairo University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Learning Hospitals Al Kaser Al Ayni Hospitals","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Symptom Relief:","summary":"The purpose of this study is to determine the efficacy of laser acupuncture in alleviating CTS symptoms following flexor tendon repair in the hand.","updated":"2025-06-11","first_posted":"2025-06-11","type":"INTERVENTIONAL","ctx":"compression","titre":"Laser-acupuncture et canal carpien après réparation des fléchisseurs"},{"nct":"NCT07381361","title":"Photobiomodulation Therapy vs. Alpha-Lipoic Acid in Burning Mouth Syndrome Treatment","acronym":null,"status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":60,"start":"2025-04-10","end":"2026-01-20","allocation":"RANDOMIZED","masking":"NONE","conditions":["Burning Mouth Syndrome","Low Level Laser Therapy"],"interventions":[{"type":"OTHER","name":"Low Level Laser Therapy"},{"type":"DRUG","name":"Alpha Lipoic Acid"}],"sponsor":"Lu Jiang","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Lu Jiang","title":"Clinical Professor","affiliation":"Sichuan University"},"officials":[{"name":"Lu Jiang, MD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Sichuan University"}],"countries":["China"],"sites":[{"facility":"West China Hospital of Stomatology, Sichuan University","city":"Chengdu","country":"China"}],"n_sites":1,"outcome":"Visual Analogue Scale (VAS)","summary":"The aim of this study was to evaluate the efficacy of photobiomodulation therapy and alpha-lipoic acid in the treatment of burning mouth syndrome by symptom assessment with visual analogue scale.","updated":"2026-02-03","first_posted":"2026-02-02","type":"INTERVENTIONAL","ctx":"orofaciale","titre":"PBM ou acide alpha-lipoïque dans le syndrome de la bouche brûlante"},{"nct":"NCT06732622","title":"Laser Acupuncture for Idiopathic Bell's Palsy","acronym":null,"status":"RECRUITING","phases":["NA"],"n":360,"start":"2024-12-01","end":"2026-05-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Bell Palsy"],"interventions":[{"type":"DEVICE","name":"Laser acupuncture"},{"type":"DRUG","name":"Steroids"},{"type":"DEVICE","name":"Sham laser acupuncture"}],"sponsor":"Beijing Tongren Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["China"],"sites":[{"facility":"China Beijing TongRen Hospital, Capital Medical University Beijing, China","city":"Beijing","country":"China"}],"n_sites":1,"outcome":"House Brackmann Grading System (HB)","summary":"Bell's palsy is characterized by acute, unilateral onset that compromises function and esthetics, exerting a considerable impact on the social, professional, and psychological aspects of the lives of affected individuals. The objective of this study was to determine whether laser acupuncture therapy could relieve symptoms in patients with Bell's palsy.","updated":"2024-12-13","first_posted":"2024-12-13","type":"INTERVENTIONAL","ctx":"orofaciale","titre":"Laser-acupuncture, corticoïdes ou sham dans la paralysie de Bell idiopathique"},{"nct":"NCT05763706","title":"Photobiomodulation Therapy in the Management of Chemotherapy-Induced Peripheral Neuropathy","acronym":"NeuroLight 2","status":"RECRUITING","phases":["NA"],"n":172,"start":"2023-03-27","end":"2025-03-15","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Chemotherapy-induced Peripheral Neuropathy"],"interventions":[{"type":"DEVICE","name":"Multiwave Locked System® (M6 laser, ASA srl, Arcugnano (VI), Italy)"}],"sponsor":"Jessa Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Jeroen mebis, Prof. Dr.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Jessa Hospital"}],"countries":["Belgium"],"sites":[{"facility":"Jessa Hospital","city":"Hasselt","country":"Belgium"}],"n_sites":1,"outcome":"Modified total neuropathy score (mTNS)","summary":"This study aims to investigate the effectiveness of photobiomodulation therapy (PBM) in the management of chemotherapy-induced peripheral neuropathy (CIPN). Therefore, the hypothesis is that PBM can reduce the severity of CIPN in cancer patients, increasing the patient's quality of life.","updated":"2023-03-30","first_posted":"2023-03-10","type":"INTERVENTIONAL","ctx":"CIPN","titre":"PBM (laser MLS) dans la prise en charge de la neuropathie chimio-induite"},{"nct":"NCT05199389","title":"Photobiomodulation Therapy in the Prevention and Management of Chemotherapy-Induced Peripheral Neuropathy","acronym":"NeuroLight","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":60,"start":"2022-01-31","end":"2023-11-15","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Chemotherapy-induced Peripheral Neuropathy"],"interventions":[{"type":"DEVICE","name":"Multiwave Locked System® (M6 laser, ASA srl, Arcugnano (VI), Italy)"}],"sponsor":"Jessa Hospital","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Jeroen Mebis, Prof. Dr.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Jessa Hospital"}],"countries":["Belgium"],"sites":[{"facility":"Jessa Hospital","city":"Hasselt","country":"Belgium"}],"n_sites":1,"outcome":"Modified total neuropathy score (mTNS)","summary":"This study aims to investigate the effectiveness of photobiomodulation therapy (PBM) in the management of chemotherapy-induced peripheral neuropathy (CIPN). Therefore, the hypothesis is that PBM can reduce the severity of CIPN in cancer patients, increasing the patient's quality of life.","updated":"2024-03-06","first_posted":"2022-01-20","type":"INTERVENTIONAL","ctx":"CIPN","titre":"PBM (laser MLS) pour prévenir et traiter la neuropathie chimio-induite"}],"gynecologie":[{"nct":"NCT07806526","title":"The Use of Photobiomodulation for Pain and Healing in Cesarean Section","acronym":null,"status":"NOT_YET_RECRUITING","phases":["PHASE2"],"n":30,"start":"2026-09","end":"2027-03","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Post Partum","Cesarean Birth","Pain Management","Wound Care"],"interventions":[{"type":"RADIATION","name":"Photobiomodulation (PBM)"},{"type":"RADIATION","name":"Placebo PBM"},{"type":"OTHER","name":"Standard Hospital Treatment"}],"sponsor":"University of Nove de Julho","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Rebeca Boltes Cecatto","title":"Professor M.D. Ph.D. Rebeca Boltes Cecatto","affiliation":"University of Nove de Julho"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Pain Intensity","summary":"Good incisional wound healing and postoperative pain are the primary concerns regarding cesarean delivery, as it can lead to serious complications and delayed recovery for patients. Both pharmacological and non-pharmacological interventions have been investigated to promote effective analgesia and favorable healing of the cesarean surgical incision. Among the therapies under investigation for this purpose, photobiomodulation (PBM) stands out. Photobiomodulation consists of the use of low-intensity therapeutic light, and several publications have emphasized its analgesic properties and its capacity to promote wound healing across various etiologies. This study aims to evaluate the analgesic and wound-healing effects of PBM on the skin surgical incision following cesarean section. This will be a randomized controlled clinical trial in which 30 women undergoing elective cesarean delivery wi","updated":"2026-09-08","first_posted":"2026-09-08","type":"INTERVENTIONAL","ctx":"obstétrique","titre":"PBM contre placebo : douleur et cicatrisation après césarienne"},{"nct":"NCT07697768","title":"Photobiomodulation for Vaginal Dysfunctions: Home-Based vs Outpatient Treatment","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":150,"start":"2026-07-30","end":"2027-06-30","allocation":"RANDOMIZED","masking":"NONE","conditions":["Genitourinary Syndrome of Menopause (GSM)","Bacterial Vaginosis","Vulvovaginal Candidiasis (VVC)"],"interventions":[{"type":"DEVICE","name":"Blue LED Photobiomodulation"}],"sponsor":"Patricia Lordelo","sponsor_class":"OTHER","collaborators":["Escola Bahiana de Medicina e Saude Publica"],"responsible":{"name":"Patricia Lordelo","title":"Associate Professor","affiliation":"Centro de Atenção ao Assoalho Pélvico"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"Escola Bahiana de Medicina e Saúde Pública","city":"Salvador","country":"Brazil"}],"n_sites":1,"outcome":"Therapeutic Response to Blue LED Photobiomodulation","summary":"Vaginal disorders, including vulvovaginal candidiasis (VVC), bacterial vaginosis (BV), and genitourinary syndrome of menopause (GSM), are highly prevalent conditions that significantly affect women's quality of life and sexual health. These disorders are associated with inflammatory changes, vaginal dysbiosis, and symptoms such as pruritus, abnormal vaginal discharge, dryness, and dyspareunia. In this context, photobiomodulation has emerged as a noninvasive therapeutic approach with anti-inflammatory and tissue-repair properties. This study is a randomized clinical trial designed to compare the therapeutic response to blue LED photobiomodulation (401 ± 5 nm) delivered through home-based and outpatient treatment protocols. A total of 150 women aged 18 to 75 years with a diagnosis of GSM, BV, or VVC will be enrolled and randomly assigned to one of two treatment groups. Clinical and laborat","updated":"2026-07-13","first_posted":"2026-07-13","type":"INTERVENTIONAL","ctx":"GSM","titre":"PBM par LED bleue des dysfonctions vaginales : à domicile ou en consultation"},{"nct":"NCT07799857","title":"A Prospective Registry of Vaginal Photobiomodulation for Chronic Pelvic Pain.","acronym":"VOICE Registry","status":"RECRUITING","phases":[],"n":1000,"start":"2026-04-06","end":"2029-04","allocation":null,"masking":null,"conditions":["Chronic Pelvic Pain"],"interventions":[{"type":"DEVICE","name":"SoLá Pelvic Therapy (SPT)"}],"sponsor":"SoLa Pelvic Therapy","sponsor_class":"INDUSTRY","collaborators":["Uroshape LLC"],"responsible":null,"officials":[],"countries":["United States"],"sites":[{"facility":"Zipper Urogynecology Associates","city":"Melbourne","country":"United States"}],"n_sites":1,"outcome":"Change in Chronic Pelvic Pain Severity","summary":"The VOICE Registry is a multicenter, prospective, observational registry designed to collect real-world data on the clinical use of SoLá Pelvic Therapy® (SPT) in patients with chronic pelvic pain (CPP). The registry will follow patients receiving transvaginal photobiomodulation (PBM) therapy with SPT as part of their standard clinical care. The primary purpose of the registry is to collect real-world evidence on the use and safety of SPT.","updated":"2026-09-02","first_posted":"2026-09-02","type":"OBSERVATIONAL","ctx":"pelvien","titre":"Registre prospectif de la PBM vaginale dans la douleur pelvienne chronique"},{"nct":"NCT07480083","title":"Low-level Laser Therapy in Pain and Perineal Healing in the Immediate Postpartum Period: a Randomized Clinical Trial.","acronym":"LaserPerineal","status":"NOT_YET_RECRUITING","phases":["NA"],"n":206,"start":"2026-04-01","end":"2026-08-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Pain","Perineal Healing"],"interventions":[{"type":"DEVICE","name":"low-level laser therapy"},{"type":"DEVICE","name":"Sham treatment"}],"sponsor":"Instituto Materno Infantil Prof. Fernando Figueira","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Leila Katz","title":"PhD","affiliation":"Instituto Materno Infantil Prof. Fernando Figueira"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"Instituto de Medicina Integral Professor Fernando Figueira - IMIP","city":"Recife","country":"Brazil"}],"n_sites":1,"outcome":"Perineal pain intensity (VAS) (immediate)","summary":"This randomized clinical trial aims to evaluate the effectiveness of low-level laser therapy compared with sham treatment on pain intensity and perineal wound healing quality in the immediate postpartum period. The study seeks to determine whether low-level laser therapy can reduce perineal pain and improve healing outcomes in women with perineal trauma after vaginal birth.","updated":"2026-03-18","first_posted":"2026-03-18","type":"INTERVENTIONAL","ctx":"obstétrique","titre":"Laser basse énergie, douleur et cicatrisation du périnée en post-partum immédiat"},{"nct":"NCT07425080","title":"HELIOS Advanced: Human Oocyte Illumination to Enhance Development","acronym":"HELIOS-A","status":"RECRUITING","phases":["NA"],"n":270,"start":"2026-03-24","end":"2027-06-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["IVF Outcomes"],"interventions":[{"type":"OTHER","name":"Photobiomodulation"}],"sponsor":"Columbia University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Samuel Zev Williams","title":"Director of Columbia University Fertility Center; Wendy D. Havens Associate Professor of Women's Health; Chief of the Division of Reproductive Endocrinology and Infertility at Columbia University Irving Medical Center","affiliation":"Columbia University"},"officials":[{"name":"Samuel Zev Williams, MD/PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Columbia University"}],"countries":["United States"],"sites":[{"facility":"Columbia University Fertility Center","city":"New York","country":"United States"}],"n_sites":1,"outcome":"Number of usable blastocysts","summary":"Oocytes need a lot of energy to complete meiosis and fertilize successfully. As women get older, the \"power plants\" of the cells (called mitochondria) don't work as well. This makes it harder for eggs and embryos to develop normally. One possible way to help is with a gentle light treatment called photobiomodulation (PBM). This uses a special type of red light that boosts energy production in cells and helps them stay healthy. This study will test whether adding this light treatment during in vitro fertilization (IVF) can improve embryo growth and pregnancy outcomes.","updated":"2026-03-25","first_posted":"2026-02-20","type":"INTERVENTIONAL","ctx":"fertilité","titre":"HELIOS Advanced : illumination des ovocytes humains pour améliorer le développement"},{"nct":"NCT07419542","title":"Effect of High Power Laser Acupuncture on Post Menopausal Hot Flashes","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":60,"start":"2026-02-20","end":"2026-04-20","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Hot Flashes"],"interventions":[{"type":"DEVICE","name":"High power laser acupuncture"},{"type":"OTHER","name":"Placebo High power laser acupuncture"},{"type":"OTHER","name":"Paced Respiration Exercise"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Eman Saeed Mohamed Elgohary","title":"Principal Investigator","affiliation":"Cairo University"},"officials":[{"name":"Soheir Mahmoud El-Kosery, PhD","role":"STUDY_CHAIR","affiliation":"Professor, Cairo University"},{"name":"Mohamed Fawzy Abu-Elenin, PhD","role":"STUDY_DIRECTOR","affiliation":"Consultant"}],"countries":["Egypt"],"sites":[{"facility":"El Agoza police hospital","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Patient reported hot flashes questionnaire","summary":"The aim of this study will be to determine the effect of high power laser acupuncture on post menopausal hot flashes.","updated":"2026-02-19","first_posted":"2026-02-19","type":"INTERVENTIONAL","ctx":"GSM","titre":"Laser-acupuncture haute puissance contre les bouffées de chaleur de la ménopause"},{"nct":"NCT07319247","title":"Laser Therapy and Pelvic Floor Muscle Training for Stress Urinary Incontinence","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":36,"start":"2025-12-09","end":"2026-02-21","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Urinary Incontinence (UI)","Laser Therapy","Stress Urinary Incontinence (SUI)","Pelvic Floor Muscle Exercise"],"interventions":[{"type":"BEHAVIORAL","name":"PFME and Laser Therapy"},{"type":"BEHAVIORAL","name":"Plasebo Laser"},{"type":"BEHAVIORAL","name":"PFME"}],"sponsor":"Necmettin Erbakan University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"hanife dogan","title":"Physıcal Therapy and Rehabilitation","affiliation":"Necmettin Erbakan University"},"officials":[],"countries":["Turkey (Türkiye)"],"sites":[{"facility":"Physical Therapy Hospital","city":"Meram","country":"Turkey (Türkiye)"}],"n_sites":1,"outcome":"Urinary incontinence severity","summary":"The aim of this study was to investigate the effects of Pelvic Floor Muscle Training (PFMT) in addition to high-intensity laser therapy (HILT) on pelvic floor dysfunction, sexual dysfunction, and quality of life in women with stress urinary incontinence. Women with SUI will be randomly assigned to PFMT (Group I), Laser + PFMT (Group II), and placebo laser (Group III). PFMT will be administered twice weekly for 12 weeks under the supervision of a physiotherapist. PFMT will be administered with biofeedback. HILT will be applied to six points in the perineal region . The intensity will be 6W, the energy density will be 120J/cm2, and three sessions will be administered weekly for a total of six sessions. Women included in the study will be evaluated twice, at the beginning and at the end of the treatment, with the Incontinence Quality of Life Scale (I-QOL), Incontinence Severity Index (ISI),","updated":"2026-10-06","first_posted":"2026-01-06","type":"INTERVENTIONAL","ctx":"GSM","titre":"Laser et rééducation périnéale dans l'incontinence urinaire d'effort"},{"nct":"NCT07311928","title":"HELIOS: Human Embryo Illumination to Enhance Development","acronym":"HELIOS","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":200,"start":"2025-12-03","end":"2027-06-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["IVF Outcomes"],"interventions":[{"type":"OTHER","name":"Photobiomodulation"}],"sponsor":"Columbia University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Samuel Zev Williams","title":"Director of Columbia University Fertility Center; Wendy D. Havens Associate Professor of Women's Health; Chief of the Division of Reproductive Endocrinology and Infertility at Columbia University Irving Medical Center","affiliation":"Columbia University"},"officials":[{"name":"Samuel Zev Williams, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Columbia University"}],"countries":["United States"],"sites":[{"facility":"Columbia University Fertility Center","city":"New York","country":"United States"}],"n_sites":1,"outcome":"Number of usable blastocysts","summary":"Embryos need a lot of energy to grow, but as women get older, the \"power plants\" of the cells (called mitochondria) don't work as well. This makes it harder for embryos to develop normally. One possible way to help is with a gentle light treatment called photobiomodulation (PBM). This uses a special type of red light that boosts energy production in cells and helps them stay healthy. This study will test whether adding this light treatment during in vitro fertilization (IVF) can improve embryo growth and pregnancy chances.","updated":"2026-03-25","first_posted":"2025-12-31","type":"INTERVENTIONAL","ctx":"fertilité","titre":"HELIOS : illumination des embryons humains pour améliorer le développement"},{"nct":"NCT06337448","title":"Light Emitting Diode in the Treatment of Vulvodynia","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":10,"start":"2025-08-16","end":"2026-08","allocation":"NA","masking":"NONE","conditions":["Vulvodynia"],"interventions":[{"type":"DEVICE","name":"Blue LED"}],"sponsor":"Centro de Atenção ao Assoalho Pélvico","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Patricia Lordelo","title":"Head of the CentroAAP","affiliation":"Centro de Atenção ao Assoalho Pélvico"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"Centro de Atenção ao assoalho pélvico","city":"Salvador","country":"Brazil"}],"n_sites":1,"outcome":"Number of participants with treatment-related adverse events as assessed by Visual Analogue Scale.","summary":"Vulvar pain can be related to a specific cause (inflammation, cancer, trauma, infection) or can be classified as vulvodynia, when vulvar pain is idiopathic and lasts for at least three months. The main symptoms reported are pain, burning, erythema, increased sensitivity, itching and burning, which affect the quality of life, psycho-emotional well-being, relationships and sexual function of these women. Photobiomodulation has been described in the literature as an alternative to treat pain. Our group has studied blue LED for some vulvovaginal dysfunctions and, due to the positive sensory effects observed in patients with vaginal stenosis and genitourinary syndrome of menopause, it is hypothesized that this technique could also bring beneficial effects for women with vulvodynia. A pilot study will be carried out, with descriptive data, with 10 women with vulvodynia. Participants will be ev","updated":"2024-08-21","first_posted":"2024-03-29","type":"INTERVENTIONAL","ctx":"vulve","titre":"LED bleue dans la vulvodynie"},{"nct":"NCT06660212","title":"Biomodulation and Rehabilitation Interventions to tarGet Pelvic Health","acronym":"BRIGHT","status":"RECRUITING","phases":["NA"],"n":240,"start":"2025-03-17","end":"2027-10","allocation":"RANDOMIZED","masking":"QUADRUPLE","conditions":["Vulvodynia","Provoked Vestibulodynia","Dyspareunia"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation"},{"type":"DEVICE","name":"Sham photobiomodulation"},{"type":"PROCEDURE","name":"Multimodal physiotherapy"}],"sponsor":"University of Ottawa","sponsor_class":"OTHER","collaborators":["Canadian Institutes of Health Research (CIHR)","University of Laval, Quebec City, Canada","BioFlexTM Laser Therapy"],"responsible":{"name":"Dr. Linda McLean","title":"Professor","affiliation":"University of Ottawa"},"officials":[{"name":"Linda McLean, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Ottawa"},{"name":"Stephanie Bernard, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"University of Laval"}],"countries":["Canada"],"sites":[{"facility":"Motor Function Measurement Lab","city":"Ottawa","country":"Canada"},{"facility":"Bernard Lab","city":"Québec","country":"Canada"}],"n_sites":2,"outcome":"Vulvar Pain Assessment Questionnaire - Pain Severity","summary":"This trial will provide evidence for the effective management of pain and pain-related domains among those who experience provoked vestibulodynia (PVD) using photobiomodulation (PBM) and multimodal physiotherapy (mPT) in a randomized controlled trial (RCT). PVD is the most common subcategory of vulvovaginal pain experienced during sexual and non-sexual activities, affects the psychological and sexual health of an astounding one in five Canadian women, yet access to evidence-informed management approaches is limited. We will employ four intervention groups: PBM, sham PBM (control), PBM combined with mPT, and mPT with sham PBM to evaluate the effectiveness of each approach on its own and the two approaches in combination.\n\nAmong those who experience PVD, we seek to answer:\n\n1. Relative to baseline and to sham PBM, does a 14-week intervention involving PBM, mPT, or a combination of mPT and ","updated":"2026-05-05","first_posted":"2024-10-28","type":"INTERVENTIONAL","ctx":"pelvien","titre":"Essai BRIGHT : PBM et kinésithérapie multimodale en santé pelvienne"},{"nct":"NCT06347926","title":"Study of Sexual Quality of Life in Women With Breast Cancer Who Had Multidisciplinary Management With Photobiomodulation for Genitourinary Syndrome of the Menopause","acronym":"EVABIOSEIN","status":"RECRUITING","phases":["NA"],"n":25,"start":"2025-03-13","end":"2027-12","allocation":"NA","masking":"NONE","conditions":["Breast Cancer"],"interventions":[{"type":"PROCEDURE","name":"Questionnaires given before and after photobiomodulation"}],"sponsor":"Institut du Cancer de Montpellier - Val d'Aurelle","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[{"name":"Angélique Bobrie, MD","role":"STUDY_CHAIR","affiliation":"Institute of Cancer in Montpellier"}],"countries":["France"],"sites":[{"facility":"Institute of Cancer in Montpellier","city":"Montpellier","country":"France"}],"n_sites":1,"outcome":"Sexual satisfaction score on one dimension of the SHQ-22 questionnaire","summary":"The treatment of breast cancer as well as the disease are responsible for genito-urinary symptoms that can persist over time and impair quality of life. Given the improved prognosis of breast cancer, more and more patients are confronted with specific post-cancer issues, and the care has become a major health challenge.\n\nSexual health is a crucial component of well-being and overall quality of life. Vaginal dryness and dyspareunia are symptoms frequently found in patients treated for breast cancer, with chemotherapy and hormone therapy as risk factors. However, the treatment of sexual disorders remains underdeveloped in France.\n\nVaginal dryness is part of a broader syndrome known as genitourinary syndrome of menopause (GSM), or vulvovaginal atrophy, which may combine vulvovaginal (dryness, irritation, burning), sexual (dyspareunia) and urinary (infections, pollakiuria, urgency) symptoms ","updated":"2025-11-18","first_posted":"2024-04-04","type":"INTERVENTIONAL","ctx":"onco","titre":"Qualité de vie sexuelle après cancer du sein et PBM"},{"nct":"NCT06793293","title":"Postoperative in Cesarean Section, the Women Suffering from Pain Due to Wound \"incisional Pain\", High Level Laser One of Most Effective Methods That Promoting Healing and Decrease Pain so It Will Effective If Use in Decreasing Pain of Cesarian Section","acronym":null,"status":"ENROLLING_BY_INVITATION","phases":["NA"],"n":40,"start":"2024-10-01","end":"2025-04-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Cesarean Section Pain"],"interventions":[{"type":"DEVICE","name":"High level laser"},{"type":"DRUG","name":"Non-steroidal anti- inflammatory drugs and antibiotics"}],"sponsor":"Cairo University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Aya Ibrahim Awad Shweal","title":"Teacher assistance at faculty of physical therapy","affiliation":"Cairo University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Cairo university","city":"Cairo","country":"Egypt"}],"n_sites":1,"outcome":"Visual analog scale (VAS):","summary":"High power laser is safe and effective methods, it's uses increasing one day after day in decreasing pain and promoting healing so its use in postoperative cesarian section will help mothers to overcome pain and return to ADLs faster","updated":"2025-01-27","first_posted":"2025-01-27","type":"INTERVENTIONAL","ctx":"obstétrique","titre":"Laser haute intensité contre la douleur de la cicatrice de césarienne"},{"nct":"NCT06460415","title":"Effects of Photobiomodulation on Pain and Sexual Function in Women With Dyspareunia: Randomized Clinical Trial","acronym":null,"status":"NOT_YET_RECRUITING","phases":["NA"],"n":52,"start":"2024-06","end":"2027-01","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Dyspareunia","Pain","Sexual Dysfunction"],"interventions":[{"type":"DEVICE","name":"photobiomidulação"},{"type":"OTHER","name":"Placebo"}],"sponsor":"Federal University of Health Science of Porto Alegre","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Mariana Della Valentina Pessoa","title":"Mariana Della Valentina Pessoa","affiliation":"Federal University of Health Science of Porto Alegre"},"officials":[],"countries":["Brazil"],"sites":[{"facility":"Universidade Federal de Ciências da Saúde de Porto Alegre","city":"Porto Alegre","country":"Brazil"}],"n_sites":1,"outcome":"Visual numeric pain scale (VNS)","summary":"The goal of this clinical trial is to compare the effects of vulvar and intravaginal application of PBM compared to the sham group on pain and sexual function in women with dyspareunia . The main question \\[s\\] it aims to answer are:\n\n* What are the effects of vulvar and intravaginal application of photobiomodulation (PBM) compared to the sham group on the sexual function of women with dyspareunia in the immediate post-intervention moments and in follow-ups of 15, 30, 90 and 180 days?\n* What are the effects of vulvar and intravaginal application of photobiomodulation (PBM) compared to the sham group on pain in women with dyspareunia in the immediate post-intervention moments and in follow-ups of 15, 30, 90 and 180 days?\n\nParticipants will The GPBM photobiomodulation group will receive, during the 8 days of intervention, application in 8 points (4 red and 4 infrared) in the vulvar region ","updated":"2024-06-14","first_posted":"2024-06-14","type":"INTERVENTIONAL","ctx":"vulve","titre":"PBM, douleur et fonction sexuelle dans la dyspareunie"},{"nct":"NCT05165056","title":"Photobiomodulation Therapy in the Prevention and Management of Radiotherapy-induced Vaginal Toxicity","acronym":"GynLight","status":"RECRUITING","phases":["NA"],"n":62,"start":"2022-08-24","end":"2030-01","allocation":"RANDOMIZED","masking":"NONE","conditions":["Radiotherapy Side Effect","Vaginal Abnormality"],"interventions":[{"type":"DEVICE","name":"Intimleds"}],"sponsor":"Jessa Hospital","sponsor_class":"OTHER","collaborators":["Ziekenhuis Oost-Limburg","Hasselt University"],"responsible":null,"officials":[{"name":"Jeroen Mebis, Prof. Dr.","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Jessa Hospital"}],"countries":["Belgium"],"sites":[{"facility":"Ziekenhuis Oost-Limburg","city":"Genk","country":"Belgium"},{"facility":"Jessa Hospital","city":"Hasselt","country":"Belgium"}],"n_sites":2,"outcome":"CTCAE-score","summary":"This study aims to investigate the effectiveness of photobiomodulation therapy (PBMT) in the prevention and management of radiotherapy-induced vaginal toxicity (RIVT). Therefore, we hypothesize that PBMT can reduce the severity of RIVT in gynecological cancer patients, increasing the patient's QoL and sexual functioning.","updated":"2023-09-29","first_posted":"2021-12-21","type":"INTERVENTIONAL","ctx":"onco","titre":"PBM (Intimleds) pour prévenir et traiter la toxicité vaginale de la radiothérapie"},{"nct":"NCT05345600","title":"MILTA vs Placebo Use Comparison for the Management of Pain Related to Perineal Scars Following Delivery","acronym":"MILTADoIP","status":"ACTIVE_NOT_RECRUITING","phases":["NA"],"n":110,"start":"2022-01-31","end":"2023-03-23","allocation":"NON_RANDOMIZED","masking":"NONE","conditions":["Perineal Scars","Delivery Complication","Episiotomy","Pain","Treatment"],"interventions":[{"type":"OTHER","name":"MILTA probe"},{"type":"OTHER","name":"placebo probe"}],"sponsor":"Centre Hospitalier Universitaire, Amiens","sponsor_class":"OTHER","collaborators":[],"responsible":null,"officials":[],"countries":["France"],"sites":[{"facility":"CHU Amiens Picardie","city":"Amiens","country":"France"}],"n_sites":1,"outcome":"pain level","summary":"The incidence of perineal scars after a pregnancy is high, either related to an episiotomy or to spontaneous perineal tears. These perineal scars can result in acute pain but also in chronic pain for some women. Medical treatment includes level 1 and 2 analgesics and, even for a few women, level 3 analgesic.\n\nThe MILTA® uses photons which are emitted with low intensity in the visible and near infrared combining 5 physical principles to reduce pain : 1- The NPCL (Nano-Pulsed Cold Laser) emissions in coherent infrared light, at 905 nanometers; 2- Non-coherent emissions, pulsed by trichromatic RGB CSM diodes (400 to 650 nm); 3- Continuous non-coherent infrared emission monochromatic diodes at 905 nm; 4- A constant circular magnetic field (200 millitesla) equivalent to the terrestrial magnetic field and 5- The effect of magnetic tunnel which potentiates the light propagation. MILTA® treatmen","updated":"2025-11-19","first_posted":"2022-04-26","type":"INTERVENTIONAL","ctx":"obstétrique","titre":"Sonde MILTA contre placebo : douleur des cicatrices périnéales après accouchement"}],"sport":[{"nct":"NCT07511803","title":"Photobiomodulation on Recovery in Female Futsal Athletes","acronym":"PBMT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":15,"start":"2026-04-15","end":"2026-06-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Muscle Recovery","Exercise","Phototherapy","Futsal"],"interventions":[{"type":"DEVICE","name":"Active PBMT"},{"type":"DEVICE","name":"Placebo PBMT"}],"sponsor":"Universidade Norte do Paraná","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Andreo Fernando Aguiar","title":"Principal Investigator","affiliation":"Universidade Norte do Paraná"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Physical performance in the Bangsbo Sprint Test","summary":"The aim of this study is to investigate the effects of photobiomodulation therapy (PBMT) on recovery after high-intensity, intermittent exercises in female futsal athletes. It is hypothesized that PBMT is superior to placebo condition in improving the recovery of muscle function after high-intensity, intermittent exercises.","updated":"2026-04-06","first_posted":"2026-04-06","type":"INTERVENTIONAL","ctx":"récupération","titre":"PBM active contre placebo sur la récupération des joueuses de futsal"},{"nct":"NCT07511790","title":"Photobiomodulation on Performance in Female Futsal Athletes","acronym":"PBMT","status":"NOT_YET_RECRUITING","phases":["NA"],"n":15,"start":"2026-04-15","end":"2026-06-01","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Muscle Performance","Exercise","Phototherapy","Futsal"],"interventions":[{"type":"DEVICE","name":"Active PBMT"},{"type":"DEVICE","name":"Placebo PBMT"}],"sponsor":"Universidade Norte do Paraná","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Andreo Fernando Aguiar","title":"Principal Investigator","affiliation":"Universidade Norte do Paraná"},"officials":[],"countries":[],"sites":[],"n_sites":0,"outcome":"Physical performance in the Bangsbo Sprint Test","summary":"The aim of this study is to investigate the effects of photobiomodulation therapy (PBMT) on physical performance in female futsal athletes. It is hypothesized that PBMT is superior to placebo condition in improving the ability to perform repeated sprints and aerobic capacity in high-intensity, intermittent activity (i.e., Bangsbo sprint test and yoyo intermittent recovery level-1, respectively).","updated":"2026-04-06","first_posted":"2026-04-06","type":"INTERVENTIONAL","ctx":"performance","titre":"PBM active contre placebo sur la performance des joueuses de futsal"},{"nct":"NCT07446517","title":"Low-Level Laser Therapy for Osgood-Schlatter or Sever Pain in Youth Athletes","acronym":null,"status":"RECRUITING","phases":["NA"],"n":36,"start":"2026-03-01","end":"2027-04-30","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Osgood-Schlatter Disease","Sever's Disease"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation (Low-Level Laser Therapy)"},{"type":"DEVICE","name":"Sham Photobiomodulation (Sham Laser Treatment)"}],"sponsor":"Medical University of Gdansk","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Bartosz Wilczyński","title":"Principal Investigator","affiliation":"Medical University of Gdansk"},"officials":[{"name":"Bartosz Wilczyński, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Medical University of Gdansk"}],"countries":["Poland"],"sites":[{"facility":"Department of Immunobiology and Environment Microbiology, Debinki 7","city":"Gdansk","country":"Poland"}],"n_sites":1,"outcome":"Recruitment feasibility: proportion of eligible participants enrolled","summary":"The goal of this clinical trial is to learn if low-level laser therapy (also called photobiomodulation) works to treat knee or heel pain in physically active children and adolescents with Osgood-Schlatter disease or Sever disease. It will also learn about the safety of this treatment. The main questions it aims to answer are:\n\n1. Does low-level laser therapy lower pain more than a sham (placebo) laser treatment?\n2. Does low-level laser therapy improve daily and sport-related function more than a sham laser treatment?\n3. What medical problems, if any, do participants have during the study?\n\nResearchers will compare active low-level laser therapy to a sham (placebo) laser treatment. The sham treatment looks and feels the same but does not deliver therapeutic light. This comparison will show whether the laser therapy works better than placebo.\n\nParticipants will:\n\n* Complete screening and a","updated":"2026-10-09","first_posted":"2026-03-03","type":"INTERVENTIONAL","ctx":"blessures","titre":"Laser basse énergie contre sham dans la maladie d'Osgood-Schlatter ou de Sever du jeune sportif"}],"oncologie-support":[{"nct":"NCT07476209","title":"Sialendoscopy Versus Photobiomodulation in Prevention of Radiation Induced Xerostomia","acronym":null,"status":"RECRUITING","phases":["NA"],"n":42,"start":"2026-04-01","end":"2026-12-31","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Radiation Induced Xerostomia"],"interventions":[{"type":"PROCEDURE","name":"Sialendoscopy"},{"type":"PROCEDURE","name":"Photobiomodulation"}],"sponsor":"Alexandria University","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Basma Morsy","title":"Principal Investigator","affiliation":"Alexandria University"},"officials":[],"countries":["Egypt"],"sites":[{"facility":"Faculty of Dentistry, Alexandria University","city":"Alexandria","country":"Egypt"}],"n_sites":1,"outcome":"Xerostomia grade","summary":"Radiation induced xerostomia (RIX) represents a common debilitating side effect for (RT), adversely affecting oral health and hindering head and neck cancer (HNC) patients' quality of life (QOL). To date, managing (RIX) is mainly symptomatic, while the only FDA-approved preventive therapeutic agent is Amifostine, with associated systemic toxicities. Sialendoscopic management is a minimally invasive technique that can help in restoring ductal patency, decreasing inflammation and improving salivary flow. Laser Photobiomodulation (PBM) is a noninvasive approach that enhances salivary gland function by stimulating cellular activity, increasing blood flow and attenuating oxidative stress.\n\nAim: The present study aims to evaluate and compare the efficacy of sialendoscopic management and photobiomodulation in managing (RIX) in (HNC) patients.\n\nMaterials and Methods: A randomized clinical trial ","updated":"2026-03-25","first_posted":"2026-03-17","type":"INTERVENTIONAL","ctx":"xérostomie","titre":"Sialendoscopie contre photobiomodulation pour prévenir la xérostomie radio-induite"},{"nct":"NCT06837480","title":"Photobiomodulation in Head and Neck Cancer-Related Chronic Lymphedema","acronym":null,"status":"RECRUITING","phases":["NA"],"n":150,"start":"2026-01-15","end":"2029-08-30","allocation":"RANDOMIZED","masking":"TRIPLE","conditions":["Head and Neck Cancer","Lymphedema of the Head and Neck"],"interventions":[{"type":"DEVICE","name":"LTU-904 Portable Laser Therapy Unit (active laser device)"},{"type":"DEVICE","name":"LTU-904 Portable Laser Therapy Unit (sham/inactive laser device)"}],"sponsor":"Abramson Cancer Center at Penn Medicine","sponsor_class":"OTHER","collaborators":["National Cancer Institute (NCI)"],"responsible":{"name":"Jie Deng","title":"Professor, PhD","affiliation":"Abramson Cancer Center at Penn Medicine"},"officials":[],"countries":["United States"],"sites":[{"facility":"University of Pennsylvania Abramson Cancer Center","city":"Philadelphia","country":"United States"},{"facility":"Vanderbilt University Medical Center","city":"Nashville","country":"United States"}],"n_sites":2,"outcome":"Total Severity of External Lymphedema","summary":"The U.S. Food and Drug Administration approved photobiomodulation therapy (PBMT) as a treatment for breast cancer-related arm lymphedema (BCRL) in 2006. The investigators conducted two pilot clinical trials. Results demonstrated the feasibility, acceptability, and preliminary efficacy of PBMT for the treatment of chronic lymphedema in head and neck cancer (HNC) survivors. The objective of this study is to further investigate and confirm the positive effects of PBMT on HNC-related chronic lymphedema.","updated":"2026-06-23","first_posted":"2025-02-20","type":"INTERVENTIONAL","ctx":"lymphœdème","titre":"Laser portable contre sham dans le lymphœdème chronique cervico-facial après cancer ORL"},{"nct":"NCT05106608","title":"Photobiomodulation Therapy Plus M-health in Head and Neck Cancer Patients: LAXER Study","acronym":"LAXER","status":"RECRUITING","phases":["NA"],"n":60,"start":"2022-07-13","end":"2027-12","allocation":"RANDOMIZED","masking":"DOUBLE","conditions":["Head and Neck Cancer","Head and Neck Neoplasms","Xerostomia"],"interventions":[{"type":"DEVICE","name":"Energy density photobiomodulation (7.5)"},{"type":"DEVICE","name":"Energy density photobiomodulation (3)"},{"type":"DEVICE","name":"Sham placebo"}],"sponsor":"Universidad de Granada","sponsor_class":"OTHER","collaborators":[],"responsible":{"name":"Noelia Galiano-Castillo","title":"Principal Investigator","affiliation":"Universidad de Granada"},"officials":[{"name":"Noelia Galiano-Castillo, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Universidad de Granada"}],"countries":["Spain"],"sites":[{"facility":"Faculty of Health Sciences","city":"Granada","country":"Spain"}],"n_sites":1,"outcome":"General and specific quality of life.","summary":"The Photobiomodulation therapy could have positive effects on quality of life and oral health in head and neck cancer survivors post-radiotherapy. The improvement in quality of life will be maintained after a follow-up period.","updated":"2026-09-17","first_posted":"2021-11-04","type":"INTERVENTIONAL","ctx":"xérostomie","titre":"Photobiomodulation (7,5 ou 3 J/cm²) et suivi mobile contre la xérostomie des cancers ORL (LAXER)"},{"nct":"NCT04979078","title":"Photobiomodulation Therapy in the Management of Hand-foot Syndrome and Hand-foot Skin Reaction","acronym":"DermLight","status":"RECRUITING","phases":["NA"],"n":40,"start":"2022-01-12","end":"2024-08","allocation":"NA","masking":"NONE","conditions":["Hand-foot Syndrome","Hand-foot Skin Reaction"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation therapy (PBMT)"}],"sponsor":"Jessa Hospital","sponsor_class":"OTHER","collaborators":["Hasselt University"],"responsible":null,"officials":[{"name":"Jeroen Mebis, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Head of Medical Oncology Department"}],"countries":["Belgium"],"sites":[{"facility":"Hasselt University","city":"Hasselt","country":"Belgium"},{"facility":"Jessa Ziekenhuis VZW","city":"Hasselt","country":"Belgium"}],"n_sites":2,"outcome":"Skin reaction evaluation - CTCAE","summary":"Hand-foot syndrome (HFS) is a side effect of chemotherapy. HFS is characterized by redness, swelling, and pain on the palms of the hands and/or soles of the feet, which can progress to blistering. Hand-foot skin reaction (HFSR) refers to symptoms affecting the hands and/or feet associated with multikinase inhibitors (TKIs). HFS and HFSR are painful complications that can lead to compromised daily activities, sleep-wake disturbance and impaired mobility, eventually decreasing Quality of Life (QoL).\n\nPhotobiomodulation therapy (PBMT) is a non-invasive therapy based on the application of visible and/or near-infrared light produced by a laser diode or a light-emitting diode. The scientifically proven biologic effects of PBM are improved wound healing, and a reduction in pain, inflammation, and oedema. The aim of this study is to evaluate the effectiveness of PBMT in the management of HFS and","updated":"2023-06-18","first_posted":"2021-07-27","type":"INTERVENTIONAL","ctx":"main-pied","titre":"Photobiomodulation dans le syndrome main-pied et la réaction cutanée main-pied"},{"nct":"NCT04690439","title":"Photobiomodulation Therapy for the Management of Breast Cancer-related Lymphedema","acronym":"LymphLight","status":"RECRUITING","phases":["NA"],"n":104,"start":"2021-02-22","end":"2028-02","allocation":"RANDOMIZED","masking":"SINGLE","conditions":["Breast Cancer","Breast Cancer Related Lymphedema","Lymphedema of Upper Arm"],"interventions":[{"type":"DEVICE","name":"Photobiomodulation therapy (PBMT)"},{"type":"PROCEDURE","name":"Manual Lymphatic drainage"}],"sponsor":"Jessa Hospital","sponsor_class":"OTHER","collaborators":["Hasselt University"],"responsible":null,"officials":[{"name":"Jeroen Mebis, MD, PhD","role":"PRINCIPAL_INVESTIGATOR","affiliation":"Jessa Hospital"}],"countries":["Belgium"],"sites":[{"facility":"Hasselt University","city":"Hasselt","country":"Belgium"},{"facility":"Jessa Ziekenhuis","city":"Hasselt","country":"Belgium"}],"n_sites":2,"outcome":"Arm circumference and volume","summary":"Up to one out of five patients with breast cancer will develop lymphedema in the upper extremity after cancer treatment. Patients with breast cancer-related lymphedema (BCRL) suffer from pain, heaviness, tightness, and a decreased range of motion. Photobiomodulation therapy (PBMT) is a non-invasive therapy based on the application of visible and/or near-infrared light produced by a laser diode or a light-emitting diode. The scientifically proven biologic effects of PBM are improved wound healing, and a reduction in pain, inflammation, and oedema. Therefore, the aim of this study is to evaluate the effectiveness of PBMT on the management of BCRL.","updated":"2023-02-28","first_posted":"2020-12-30","type":"INTERVENTIONAL","ctx":"lymphœdème","titre":"Photobiomodulation contre drainage lymphatique manuel dans le lymphœdème du bras après cancer du sein"}]}};
